QT_ISI(17,{"2484":["(Telah dekat kepada manusia) kepada penduduk Mekah yang ingkar terhadap adanya hari berbangkit (hari penghisaban mereka) yaitu hari kiamat (sedang mereka berada dalam kelalaian) daripadanya (lagi berpaling) tidak bersiap-siap untuk menghadapinya, yaitu dengan bekal iman.",[["ٱقْتَرَبَ","(Telah) menghampiri"],["لِلنَّاسِ","untuk manusia"],["حِسَابُهُمْ","akaun mereka"],["وَهُمْ","sedangkan mereka"],["فِى","(ada) dalam"],["غَفْلَةٍۢ","kelalaian"],["مُّعْرِضُونَ","berpaling"]]],"2485":["(Tidak datang kepada mereka suatu ayat Alquran pun yang baru diturunkan dari Rabb mereka) secara berangsur-angsur, yakni lafal Alquran (melainkan mereka mendengarnya, sedang mereka bermain-main) mereka memperolok-oloknya.",[["مَا","Tidak"],["يَأْتِيهِم","datang kepada mereka"],["مِّن","daripada"],["ذِكْرٍۢ","satu Peringatan"],["مِّن","daripada"],["رَّبِّهِم","Tuhan mereka"],["مُّحْدَثٍ","baru"],["إِلَّا","kecuali"],["ٱسْتَمَعُوهُ","mereka mendengarnya"],["وَهُمْ","sedangkan mereka"],["يَلْعَبُونَ","(sedang) bermain"]]],"2486":["(Lagi dalam keadaan lalai) yakni kosong (hati mereka) untuk merenungkan makna-maknanya. (Dan mereka berbisik-bisik) mereka merahasiakan pembicaraan mereka (yakni orang-orang yang zalim itu) lafal ayat ini merupakan Badal daripada Dhamir Wawu yang terdapat di dalam lafal Wa Asarrun Najwa (\"Orang ini tidak lain) yakni Nabi Muhammad (hanyalah seorang manusia seperti kalian) dan yang disampaikannya itu adalah sihir belaka (maka apakah kalian menerima sihir itu) yakni apakah kalian mau mengikutinya (padahal kalian menyaksikannya?\") sedangkan kalian telah mengetahui, bahwa yang disampaikan itu adalah sihir.",[["لَاهِيَةًۭ","Terganggu"],["قُلُوبُهُمْ ۗ","hati mereka"],["وَأَسَرُّوا۟","Dan mereka bersembunyi"],["ٱلنَّجْوَى","perbualan peribadi itu"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","[mereka] berbuat zalim"],["هَلْ","Adakah"],["هَـٰذَآ","ini"],["إِلَّا","kecuali"],["بَشَرٌۭ","seorang manusia"],["مِّثْلُكُمْ ۖ","macam kamu"],["أَفَتَأْتُونَ","Jadi adakah kamu mendekati"],["ٱلسِّحْرَ","sihir itu"],["وَأَنتُمْ","sedangkan kamu"],["تُبْصِرُونَ","lihat (ia)"]]],"2487":["(Berkatalah Muhammad) kepada mereka, (\"Rabbku mengetahui semua perkataan) yang ada (di langit dan di bumi dan Dialah Yang Maha Mendengar) semua apa yang mereka rahasiakan di dalam pembicaraannya (lagi Maha Mengetahui\") apa yang mereka rahasiakan.",[["قَالَ","Dia berkata"],["رَبِّى","Tuhanku"],["يَعْلَمُ","mengetahui"],["ٱلْقَوْلَ","perkataan itu"],["فِى","dalam"],["ٱلسَّمَآءِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["وَهُوَ","Dan Dia"],["ٱلسَّمِيعُ","(ialah) Yang Maha Mendengar"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"2488":["(Bahkan) lafal Bal menunjukkan makna Intiqal atau memindahkan suatu pembicaraan kepada pembicaraan yang lain. Hal ini bersifat tetap di dalam ketiga tempat I'rab (mereka berkata pula:) dalam menanggapi Alquran yang diturunkan kepada Nabi Muhammad, bahwa Alquran itu adalah (\"Mimpi-mimpi yang kalut) mimpi yang tidak menentu yang dilihat dalam tidurnya (malah diada-adakannya) dialah yang membuat-buatnya (bahkan dia sendiri seorang penyair) maka jelas yang disampaikannya itu adalah syair (maka hendaklah ia mendatangkan kepada kita suatu mukjizat, sebagaimana Rasul-rasul yang telah lalu diutus\") yaitu semacam mukjizat unta Nabi Shaleh, tongkat dan tangan Nabi Musa, maka Allah swt. berfirman:",[["بَلْ","Bahkan"],["قَالُوٓا۟","mereka berkata"],["أَضْغَـٰثُ","Bercelaru"],["أَحْلَـٰمٍۭ","mimpi"],["بَلِ","tidak"],["ٱفْتَرَىٰهُ","dia (telah) menciptanya"],["بَلْ","tidak"],["هُوَ","dia"],["شَاعِرٌۭ","(adalah) seorang penyair"],["فَلْيَأْتِنَا","Jadi biarlah dia membawa kita"],["بِـَٔايَةٍۢ","satu tanda"],["كَمَآ","macam apa"],["أُرْسِلَ","telah dihantar"],["ٱلْأَوَّلُونَ","(kepada) yang dahulu"]]],"2489":["(Tidak ada suatu negeri pun yang beriman sebelum mereka) yakni penduduknya (yang Kami telah binasakan) disebabkan kedustaan mereka terhadap mukjizat-mukjizat yang didatangkan oleh Rasulnya (maka apakah mereka akan beriman?) tentu saja tidak.",[["مَآ","Tidak"],["ءَامَنَتْ","beriman"],["قَبْلَهُم","sebelum mereka"],["مِّن","sebarang"],["قَرْيَةٍ","bandar"],["أَهْلَكْنَـٰهَآ ۖ","yang telah Kami binasakan"],["أَفَهُمْ","begitu juga mereka"],["يُؤْمِنُونَ","beriman"]]],"2490":["(Kami tiada mengutus rasul-rasul sebelum kamu melainkan beberapa orang laki-laki yang Kami beri wahyu) menurut qiraat yang lain lafal Nuuhii dibaca Yuuhaa (kepada mereka) mereka bukanlah malaikat (maka tanyakanlah olehmu kepada orang-orang yang berilmu) yakni ulama yang mengetahui kitab Taurat dan kitab Injil (jika kalian tidak mengetahui) hal tersebut, sesungguhnya mereka mengetahuinya, mengingat kepercayaan kalian kepada ulama kitab Taurat dan Injil lebih kuat daripada kepercayaan kaum Mukminin kepada Muhammad.",[["وَمَآ","Dan tidak"],["أَرْسَلْنَا","Kami utus"],["قَبْلَكَ","sebelum kamu"],["إِلَّا","kecuali"],["رِجَالًۭا","lelaki"],["نُّوحِىٓ","Kami mendedahkan"],["إِلَيْهِمْ ۖ","kepada mereka"],["فَسْـَٔلُوٓا۟","Jadi tanyalah"],["أَهْلَ","kaum"],["ٱلذِّكْرِ","(dari) Peringatan"],["إِن","jika"],["كُنتُمْ","kamu"],["لَا","jangan"],["تَعْلَمُونَ","mengetahui"]]],"2491":["(Dan tidaklah Kami jadikan mereka) para rasul itu (tubuh-tubuh) lafal Jasadun sekalipun kata tunggal tetapi maknanya jamak (yang tiada memakan makanan) tetapi justru mereka memakannya (dan tidak pula mereka itu orang-orang yang kekal) hidup di dunia.",[["وَمَا","Dan tidak"],["جَعَلْنَـٰهُمْ","Kami membuatnya"],["جَسَدًۭا","badan"],["لَّا","tidak"],["يَأْكُلُونَ","makan"],["ٱلطَّعَامَ","makanan itu"],["وَمَا","dan bukan"],["كَانُوا۟","mereka adalah"],["خَـٰلِدِينَ","abadi"]]],"2492":["(Kemudian Kami tepati janji kepada mereka) yaitu untuk menyelamatkan mereka (maka Kami selamatkan mereka dan orang-orang yang Kami kehendaki) yakni orang-orang yang beriman kepada para rasul itu (dan Kami binasakan orang-orang yang melampaui batas) yaitu orang-orang yang mendustakan para rasul.",[["ثُمَّ","Kemudian"],["صَدَقْنَـٰهُمُ","Kami penuhi (untuk) mereka"],["ٱلْوَعْدَ","janji itu"],["فَأَنجَيْنَـٰهُمْ","dan Kami selamatkan mereka"],["وَمَن","dan siapa"],["نَّشَآءُ","Kami berkehendak"],["وَأَهْلَكْنَا","dan Kami binasakan"],["ٱلْمُسْرِفِينَ","orang yang melampaui batas"]]],"2493":["(Sesungguhnya telah Kami turunkan kepada kalian) hai orang-orang Quraisy (sebuah Kitab yang di dalamnya disebutkan diri kalian) disebabkan ia memakai bahasa kalian sendiri. (Maka apakah kalian tiada memahaminya?) lalu beriman kepadanya.",[["لَقَدْ","Sesungguhnya"],["أَنزَلْنَآ","Kami (telah) menurunkan"],["إِلَيْكُمْ","kepada kamu"],["كِتَـٰبًۭا","sebuah Buku"],["فِيهِ","di dalamnya"],["ذِكْرُكُمْ ۖ","(adalah) sebutan kamu"],["أَفَلَا","Kemudian tidak akan"],["تَعْقِلُونَ","kamu menggunakan alasan"]]],"2494":["(Dan berapa banyaknya Kami telah binasakan) kami hancurkan (beberapa negeri) yakni penduduk-penduduknya (yang penduduknya zalim) berbuat kekafiran (dan Kami adakan sesudah mereka itu kaum yang lain).",[["وَكَمْ","Dan berapa banyak"],["قَصَمْنَا","Kami (telah) hancur"],["مِن","daripada"],["قَرْيَةٍۢ","sebuah bandar"],["كَانَتْ","(itu) adalah"],["ظَالِمَةًۭ","tidak adil"],["وَأَنشَأْنَا","dan Kami hasilkan"],["بَعْدَهَا","selepas mereka"],["قَوْمًا","orang lain"],["ءَاخَرِينَ","orang lain"]]],"2495":["(Maka tatkala mereka merasakan azab Kami) penduduk negeri-negeri tersebut merasakan kebinasaannya telah dekat (tiba-tiba mereka lari tergesa-gesa daripadanya) mereka berupaya melarikan diri secepatnya.",[["فَلَمَّآ","Kemudian apabila"],["أَحَسُّوا۟","mereka anggap"],["بَأْسَنَآ","azab kita"],["إِذَا","lihatlah"],["هُم","mereka"],["مِّنْهَا","daripadanya"],["يَرْكُضُونَ","sedang melarikan diri"]]],"2496":["Kemudian berkatalah para Malaikat pembawa azab kepada mereka dengan nada mengejek, (\"Janganlah kalian lari tergesa-gesa, kembalilah kalian kepada kemewahan yang telah kalian rasakan) kepada nikmat yang telah diberikan kepada kalian (dan kepada tempat-tempat kediaman kalian, supaya kalian ditanya\") tentang sesuatu dari keduniaan milik kalian, sebagaimana biasanya.",[["لَا","Jangan lari"],["تَرْكُضُوا۟","Jangan lari"],["وَٱرْجِعُوٓا۟","tapi balik"],["إِلَىٰ","kepada"],["مَآ","apa"],["أُتْرِفْتُمْ","kamu diberi kemewahan"],["فِيهِ","di dalamnya"],["وَمَسَـٰكِنِكُمْ","dan ke rumah kamu"],["لَعَلَّكُمْ","supaya kamu"],["تُسْـَٔلُونَ","dipersoalkan"]]],"2497":["(Mereka berkata, \"Aduhai) huruf Ya di sini menunjukkan makna penyesalan (celakalah kami) binasalah kami (sesungguhnya kami adalah orang-orang yang zalim\") disebabkan kami kafir.",[["قَالُوا۟","Mereka berkata"],["يَـٰوَيْلَنَآ","Wahai celaka kami"],["إِنَّا","Sesungguhnya, [kami]"],["كُنَّا","kami"],["ظَـٰلِمِينَ","orang yang zalim"]]],"2498":["(Maka tetaplah demikian) kalimat-kalimat itu sebagai (keluhan mereka) yang mereka serukan dan mereka ulang-ulang (sehingga Kami jadikan mereka sebagai tanaman yang telah dituai) bagaikan tanaman yang dipanen dengan sabit; seumpamanya mereka dibunuh dengan memakai pedang (yang tidak dapat hidup lagi) mereka mati bagaikan padamnya nyala api bila dimatikan.",[["فَمَا","Kemudian tidak"],["زَالَت","terhenti"],["تِّلْكَ","[ini]"],["دَعْوَىٰهُمْ","tangisan mereka"],["حَتَّىٰ","sehingga"],["جَعَلْنَـٰهُمْ","Kami membuatnya"],["حَصِيدًا","dituai"],["خَـٰمِدِينَ","pupus"]]],"2499":["(Dan tidaklah Kami ciptakan langit dan bumi dan segala yang ada di antara keduanya dengan bermain-main) tiada gunanya, tetapi justru hal ini menjadi bukti yang menunjukkan kekuasaan Kami dan sekaligus sebagai manfaat buat hamba-hamba Kami.",[["وَمَا","Dan tidak"],["خَلَقْنَا","Kami mencipta"],["ٱلسَّمَآءَ","langit"],["وَٱلْأَرْضَ","dan bumi"],["وَمَا","dan apa"],["بَيْنَهُمَا","(adalah) di antara mereka"],["لَـٰعِبِينَ","(untuk) bermain"]]],"2500":["(Sekiranya Kami hendak membuat sesuatu permainan) hal-hal yang dapat dijadikan hiburan seperti istri dan anak (tentulah Kami membuatnya dari sisi Kami) para bidadari dan para Malaikat. (Jika Kami menghendaki berbuat) demikian, tetapi Kami tidak akan memperbuatnya dan tidak menghendakinya.",[["لَوْ","Jika"],["أَرَدْنَآ","Kami berniat"],["أَن","bahawa"],["نَّتَّخِذَ","Kami ambil"],["لَهْوًۭا","satu hobi"],["لَّٱتَّخَذْنَـٰهُ","sesungguhnya Kami (boleh) mengambilnya"],["مِن","daripada"],["لَّدُنَّآ","Kami"],["إِن","jika"],["كُنَّا","Kami"],["فَـٰعِلِينَ","pelaku"]]],"2501":["(Sebenarnya Kami melontarkan) yakni melemparkan (yang hak) iman (kepada yang batil) yakni kekafiran (lalu yang hak itu menghancurkannya) yakni melenyapkan yang batil (maka dengan serta merta yang batil itu lenyap) hilang. Asal makna lafal Damaghahu adalah menimpakan pukulan pada otak, yaitu tempat yang mematikan. (Dan bagi kalian) hai orang-orang kafir Mekah (kecelakaan) azab yang keras (disebabkan apa yang kalian sifatkan itu) bahwa Allah mempunyai istri atau anak.",[["بَلْ","Bahkan"],["نَقْذِفُ","Kami melontar"],["بِٱلْحَقِّ","kebenaran"],["عَلَى","terhadap"],["ٱلْبَـٰطِلِ","[yang] kebatilan"],["فَيَدْمَغُهُۥ","dan ia memecahkan kepalanya"],["فَإِذَا","lihatlah"],["هُوَ","ia (adalah)"],["زَاهِقٌۭ ۚ","lenyap"],["وَلَكُمُ","Dan untuk kamu"],["ٱلْوَيْلُ","(adalah) kemusnahan"],["مِمَّا","bagi apa"],["تَصِفُونَ","kamu menganggap"]]],"2502":["(Dan kepunyaan-Nyalah) kepunyaan Allahlah (segala yang di langit dan di bumi) sebagai milik-Nya (dan makhluk yang di sisi-Nya) yakni para malaikat. Jumlah kalimat ayat ini menjadi Mubtada, sedangkan Khabarnya ialah (mereka tiada mempunyai rasa angkuh untuk menyembah-Nya dan tiada pula merasa letih) tiada merasa payah dalam menyembah-Nya.",[["وَلَهُۥ","Dan kepunyaan-Nya"],["مَن","sesiapa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["وَمَنْ","Dan (mereka) yang"],["عِندَهُۥ","(berada) dekat-Nya"],["لَا","tidak"],["يَسْتَكْبِرُونَ","mereka sombong"],["عَنْ","kepada"],["عِبَادَتِهِۦ","menyembah Dia"],["وَلَا","dan bukan"],["يَسْتَحْسِرُونَ","mereka penat"]]],"2503":["(Mereka selalu bertasbih malam dan siang dengan tiada henti-hentinya) bertasbih bagi mereka bagaikan nafas dalam diri kita; tiada sesuatu pun yang mengganggunya.",[["يُسَبِّحُونَ","Mereka bertasbih (kepada-Nya)"],["ٱلَّيْلَ","malam itu"],["وَٱلنَّهَارَ","dan hari itu"],["لَا","tidak"],["يَفْتُرُونَ","mereka kendur"]]],"2504":["(Apakah) makna lafal Am di sini sama dengan lafal Bal, artinya akan tetapi. Sedangkan Hamzah Istifhamnya menunjukkan makna ingkar (mereka mengambil tuhan-tuhan) yang diadakan (dari bumi) seperti dari batu, emas dan perak (yang mereka) yakni tuhan-tuhan itu (dapat menghidupkan) orang-orang yang telah mati? Tentu saja tidak dapat; bukanlah Tuhan melainkan yang dapat menghidupkan orang-orang yang mati.",[["أَمِ","Atau"],["ٱتَّخَذُوٓا۟","(ada) mereka ambil"],["ءَالِهَةًۭ","tuhan"],["مِّنَ","daripada"],["ٱلْأَرْضِ","bumi"],["هُمْ","mereka"],["يُنشِرُونَ","bangkitkan (orang mati)"]]],"2505":["(Sekiranya ada pada keduanya) di langit dan di bumi (tuhan-tuhan selain Allah tentulah keduanya itu telah rusak binasa) maksudnya akan menyimpang daripada tatanan biasanya sebagaimana yang kita saksikan sekarang, hal itu disebabkan adanya persaingan di antara dua kekuasaan yang satu sama lain tiada bersesuaian, yang satu mempunyai ketentuan sendiri dan yang lainnya demikian pula. (Maka Maha Suci) yakni sucilah (Allah Rabb) Pencipta (Arasy) yakni singgasana atau Al Kursi (daripada apa yang mereka sifatkan) dari apa yang disifatkan oleh orang-orang kafir terhadap Allah swt. seperti mempunyai sekutu dan lain sebagainya.",[["لَوْ","Jika"],["كَانَ","(ada) ada"],["فِيهِمَآ","dalam kedua-duanya"],["ءَالِهَةٌ","tuhan"],["إِلَّا","selain"],["ٱللَّهُ","Allah"],["لَفَسَدَتَا ۚ","sesungguhnya mereka telah binasa"],["فَسُبْحَـٰنَ","Begitu dimuliakan"],["ٱللَّهِ","(ialah) Allah"],["رَبِّ","Tuhan"],["ٱلْعَرْشِ","(dari) Arasy"],["عَمَّا","(di atas) apa"],["يَصِفُونَ","mereka sifatkan"]]],"2506":["(Dia tidak ditanya tentang apa yang diperbuat-Nya dan merekalah yang akan ditanyai) tentang perbuatan-perbuatan mereka.",[["لَا","Tidak"],["يُسْـَٔلُ","Dia (boleh) disoal"],["عَمَّا","tentang apa"],["يَفْعَلُ","Dia buat"],["وَهُمْ","tetapi mereka"],["يُسْـَٔلُونَ","akan dipersoalkan"]]],"2507":["(Apakah mereka mengambil selain daripada-Nya) selain dari Allah (sebagai tuhan-tuhan) kata tanya atau Istifham di sini mengandung makna ejekan (Katakanlah, \"Unjukkanlah bukti kalian!\") yang menunjukkan kebenaran dugaan kalian itu. Dan sekali-kali kalian tidak akan dapat melakukannya. (Ini adalah peringatan bagi orang-orang yang bersamaku) yakni umatku; yang dimaksud \"ini\" adalah Alquran, (dan peringatan bagi orang-orang yang sebelumku) umat-umat sebelumku, yang dimaksud adalah kitab Taurat, Injil dan kitab-kitab Allah yang lainnya: Tidak ada satu pun kitab-kitab itu yang mengatakan, bahwa ada Tuhan di samping Allah, sebagaimana yang dikatakan mereka; Maha Suci Allah dari hal tersebut. (Sebenarnya kebanyakan mereka tiada mengetahui yang hak) tidak mengetahui keesaan Allah (karena itu mereka berpaling) dari memikirkan hal-hal yang dapat mengantarkan mereka kepada ajaran tauhid.",[["أَمِ","Atau"],["ٱتَّخَذُوا۟","(ada) mereka ambil"],["مِن","selain Dia"],["دُونِهِۦٓ","selain Dia"],["ءَالِهَةًۭ ۖ","tuhan"],["قُلْ","Katakanlah"],["هَاتُوا۟","bawa"],["بُرْهَـٰنَكُمْ ۖ","bukti kamu"],["هَـٰذَا","Ini"],["ذِكْرُ","(adalah) Peringatan"],["مَن","(bagi mereka) yang"],["مَّعِىَ","(ada) dengan aku"],["وَذِكْرُ","dan Peringatan"],["مَن","(bagi mereka) yang"],["قَبْلِى ۗ","(ada) sebelum aku"],["بَلْ","Tetapi"],["أَكْثَرُهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"],["ٱلْحَقَّ ۖ","kebenaran"],["فَهُم","jadi mereka"],["مُّعْرِضُونَ","(ada) enggan"]]],"2508":["(Dan Kami tidak mengutus seorang rasul pun sebelum kamu, melainkan Kami wahyukan) dalam satu qiraat lafal Nuuhii dibaca Yuuhaa (kepadanya, \"Bahwasanya tidak ada Tuhan melainkan Aku, maka sembahlah Aku olehmu sekalian\") artinya tauhidkanlah atau esakanlah Aku.",[["وَمَآ","Dan tidak"],["أَرْسَلْنَا","Kami utus"],["مِن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["مِن","sebarang"],["رَّسُولٍ","Utusan"],["إِلَّا","tetapi"],["نُوحِىٓ","Kami mendedahkan(ed)"],["إِلَيْهِ","kepadanya"],["أَنَّهُۥ","bahawa [Dia]"],["لَآ","(Ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّآ","kecuali"],["أَنَا۠","aku"],["فَٱعْبُدُونِ","maka sembahlah Aku"]]],"2509":["(Dan mereka berkata, \"Tuhan Yang Maha Pemurah telah mengambil anak\") berupa Malaikat-malaikat (Maha Suci Allah. Sebenarnya) para malaikat itu (adalah hamba-hamba Allah yang dimuliakan) di sisi-Nya; dan pengertian kehambaan ini jelas bertentangan dengan pengertian keanakan.",[["وَقَالُوا۟","Dan mereka berkata"],["ٱتَّخَذَ","Telah mengambil"],["ٱلرَّحْمَـٰنُ","Yang Maha Pemurah"],["وَلَدًۭا ۗ","seorang anak lelaki"],["سُبْحَـٰنَهُۥ ۚ","Maha Suci Dia"],["بَلْ","Bahkan"],["عِبَادٌۭ","(mereka adalah) hamba"],["مُّكْرَمُونَ","dihormati"]]],"2510":["(Mereka tidak mendahului-Nya dengan perkataan) mereka sama sekali tidak pernah berkata melainkan setelah ada firman-Nya (dan mereka mengerjakan perintah-perintah-Nya) yakni setelah diperintahkan oleh-Nya.",[["لَا","Tidak"],["يَسْبِقُونَهُۥ","mereka (boleh) mendahului-Nya"],["بِٱلْقَوْلِ","dalam perkataan"],["وَهُم","dan mereka"],["بِأَمْرِهِۦ","dengan perintahNya"],["يَعْمَلُونَ","bertindak"]]],"2511":["(Allah mengetahui segala sesuatu yang di hadapan mereka dan yang di belakang mereka) apa yang telah mereka kerjakan dan yang sedang mereka kerjakan (dan mereka tiada memberi syafaat melainkan kepada orang yang diridai) oleh Allah swt. untuk mendapatkannya (dan mereka karena takut kepada-Nya) kepada Allah swt. (selalu berhati-hati) selalu takut kepada-Nya.",[["يَعْلَمُ","Dia tahu"],["مَا","apa"],["بَيْنَ","(ada) di hadapan mereka"],["أَيْدِيهِمْ","(ada) di hadapan mereka"],["وَمَا","dan apa"],["خَلْفَهُمْ","(ada) di belakang mereka"],["وَلَا","dan bukan"],["يَشْفَعُونَ","mereka (boleh) memberi syafaat"],["إِلَّا","kecuali"],["لِمَنِ","untuk siapa"],["ٱرْتَضَىٰ","Dia meluluskan"],["وَهُم","Dan mereka"],["مِّنْ","daripada"],["خَشْيَتِهِۦ","takut kepadaNya"],["مُشْفِقُونَ","berdiri dengan kagum"]]],"2512":["(Dan barang siapa di antara mereka mengatakan, \"Sesungguhnya aku adalah tuhan selain daripada-Nya\") selain daripada Allah swt., dia adalah iblis yang menganjurkan manusia untuk menyembah dan taat kepada perintahnya (maka orang itu Kami beri balasan dengan Jahanam, demikianlah) sebagaimana Kami memberikan balasan kepada iblis (Kami memberikan pembalasan kepada orang-orang yang zalim) yakni orang-orang yang musyrik.",[["۞ وَمَن","Dan sesiapa"],["يَقُلْ","berkata"],["مِنْهُمْ","daripada mereka"],["إِنِّىٓ","Memang aku"],["إِلَـٰهٌۭ","tuhan"],["مِّن","selain Dia"],["دُونِهِۦ","selain Dia"],["فَذَٰلِكَ","Kemudian itu"],["نَجْزِيهِ","Kami akan membalasnya"],["جَهَنَّمَ ۚ","(dengan) Neraka"],["كَذَٰلِكَ","Demikianlah"],["نَجْزِى","Kami membalas"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"2513":["(Apakah tidak) dapat dibaca Awalam atau Alam (melihat) mengetahui (orang-orang yang kafir itu, bahwasanya langit dan bumi itu keduanya dahulu merupakan suatu yang padu) bersatu (kemudian Kami pisahkan) Kami jadikan langit tujuh lapis dan bumi tujuh lapis pula. Kemudian langit itu dibuka sehingga dapat menurunkan hujan yang sebelumnya tidak dapat menurunkan hujan. Kami buka pula bumi itu sehingga dapat menumbuhkan tetumbuhan, yang sebelumnya tidak dapat menumbuhkannya. (Dan daripada air Kami jadikan) air yang turun dari langit dan yang keluar dari mata air di bumi (segala sesuatu yang hidup) tumbuh-tumbuhan dan lain-lainnya, maksudnya airlah penyebab bagi kehidupannya. (Maka mengapakah mereka tiada juga beriman?) kepada keesaan-Ku.",[["أَوَلَمْ","Jangan"],["يَرَ","lihat"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["أَنَّ","bahawa"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["كَانَتَا","adalah"],["رَتْقًۭا","entiti yang bergabung"],["فَفَتَقْنَـٰهُمَا ۖ","kemudian Kami pisahkan mereka"],["وَجَعَلْنَا","dan Kami jadikan"],["مِنَ","daripada"],["ٱلْمَآءِ","air itu"],["كُلَّ","setiap"],["شَىْءٍ","benda hidup"],["حَىٍّ ۖ","benda hidup"],["أَفَلَا","Kemudian tidak akan"],["يُؤْمِنُونَ","mereka beriman"]]],"2514":["(Dan telah Kami jadikan di bumi ini berpatok-patok) yakni gunung-gunung yang kokoh (supaya) tidak (goncang ia) yakni, bumi (bersama mereka dan telah Kami jadikan pula padanya) di gunung-gunung itu (celah-celah) yang dapat ditempuh (sebagai jalan-jalan) lafal Subulan ini menjadi Badal dari lafal Fijaajan, artinya jalan-jalan yang luas dan dapat ditempuh (agar mereka mendapat petunjuk) untuk sampai pada tujuan-tujuan mereka dalam bepergian.",[["وَجَعَلْنَا","Dan Kami (telah) meletakkan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["رَوَٰسِىَ","gunung yang kukuh"],["أَن","jangan-jangan"],["تَمِيدَ","ia (harus) goncang"],["بِهِمْ","bersama mereka"],["وَجَعَلْنَا","dan Kami jadikan"],["فِيهَا","di dalamnya"],["فِجَاجًۭا","laluan luas"],["سُبُلًۭا","(sebagai) cara"],["لَّعَلَّهُمْ","supaya mereka boleh"],["يَهْتَدُونَ","(dibimbing)."]]],"2515":["(Dan Kami menjadikan langit itu sebagai atap) bagi bumi, sebagaimana atap yang menaungi rumah (yang terpelihara) tidak sampai ambruk (sedang mereka dari segala tanda-tanda yang ada padanya) berupa matahari, bulan dan bintang-bintang (berpaling) mereka yakni orang kafir tidak mau memikirkan hal itu hingga mereka mengetahui, bahwa pencipta kesemuanya itu tiada sekutu bagi-Nya.",[["وَجَعَلْنَا","Dan Kami jadikan"],["ٱلسَّمَآءَ","langit"],["سَقْفًۭا","sebuah bumbung"],["مَّحْفُوظًۭا ۖ","dilindungi"],["وَهُمْ","Tetapi mereka"],["عَنْ","daripada"],["ءَايَـٰتِهَا","Tanda-tandanya"],["مُعْرِضُونَ","berpaling"]]],"2516":["(Dan Dialah yang telah menciptakan malam dan siang, matahari dan bulan. Masing-masing dari semua itu) lafal Kullun ini tanwinnya merupakan pergantian daripada Mudhaf ilaih, maksudnya masing-masing daripada matahari, bulan dan bintang-bintang lainnya (di dalam garis edarnya) pada garis edarnya yang bulat di angkasa bagaikan bundaran batu penggilingan gandum (beredar) maksudnya semua berjalan dengan cepat sebagaimana berenang di atas air. Disebabkan ungkapan ini memakai Tasybih, maka didatangkanlah Dhamir bagi orang-orang yang berakal; yakni keadaan semua yang beredar pada garis edarnya itu bagaikan orang-orang yang berenang di dalam air.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["خَلَقَ","dicipta"],["ٱلَّيْلَ","malam"],["وَٱلنَّهَارَ","dan hari"],["وَٱلشَّمْسَ","dan matahari"],["وَٱلْقَمَرَ ۖ","dan bulan"],["كُلٌّۭ","setiap satu"],["فِى","dalam"],["فَلَكٍۢ","sebuah orbit"],["يَسْبَحُونَ","terapung"]]],"2517":["Ayat ini diturunkan ketika orang-orang kafir berkata, bahwa sesungguhnya Muhammad itu pasti akan mati (Kami tidak menjadikan hidup kekal bagi seorang manusia pun sebelum kamu) hidup abadi di dunia (maka jika kamu mati, apakah mereka akan kekal?) di dunia? Tentu saja tidak. Jumlah kalimat yang terakhir inilah yang mengandung pengertian ingkar.",[["وَمَا","Dan tidak"],["جَعَلْنَا","Kami buat"],["لِبَشَرٍۢ","untuk mana-mana lelaki"],["مِّن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["ٱلْخُلْدَ ۖ","[the] keabadian"],["أَفَإِي۟ن","jadi jika"],["مِّتَّ","kamu mati"],["فَهُمُ","maka (akan) mereka"],["ٱلْخَـٰلِدُونَ","hidup selamanya"]]],"2518":["(Tiap-tiap yang berjiwa itu akan merasakan mati) di dunia (dan Kami akan menguji kalian) mencoba kalian (dengan keburukan dan kebaikan) seperti miskin, kaya, sakit dan sehat (sebagai cobaan) kalimat ini menjadi Maf'ul Lah, maksudnya supaya Kami melihat, apakah mereka bersabar dan bersyukur ataukah tidak. (Dan hanya kepada Kamilah kalian dikembalikan) kemudian Kami akan membalas kalian.",[["كُلُّ","Setiap"],["نَفْسٍۢ","jiwa"],["ذَآئِقَةُ","(akan) rasa"],["ٱلْمَوْتِ ۗ","[the] kematian"],["وَنَبْلُوكُم","Dan Kami menguji kamu"],["بِٱلشَّرِّ","dengan [yang] buruk"],["وَٱلْخَيْرِ","dan [yang] baik"],["فِتْنَةًۭ ۖ","(sebagai) percubaan"],["وَإِلَيْنَا","dan kepada Kami"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"2519":["(Dan apabila orang-orang kafir itu melihat kamu tidaklah mereka menjadikanmu melainkan hanyalah sebagai bahan perolokan) yakni mereka memperolok-olok kamu seraya mengatakan, (\"Apakah ini orang yang mencela tuhan-tuhan kalian?\") orang yang mencaci maki tuhan-tuhan kalian. (Dan mereka adalah orang-orang yang bila disebutkan nama Tuhan Yang Maha Pemurah) kepada mereka (maka mereka) lafal ini berfungsi menjadi taukid (ingkar) kepada-Nya, karena mereka menjawab, \"Kami tidak mengetahui-Nya.\"",[["وَإِذَا","Dan apabila"],["رَءَاكَ","mereka melihat kamu"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["إِن","tidak"],["يَتَّخِذُونَكَ","mereka membawa kamu"],["إِلَّا","kecuali"],["هُزُوًا","(dalam) ejekan"],["أَهَـٰذَا","Adakah ini"],["ٱلَّذِى","orang yang"],["يَذْكُرُ","menyebut"],["ءَالِهَتَكُمْ","tuhan-tuhan kamu"],["وَهُم","Dan mereka"],["بِذِكْرِ","pada (the) sebutan"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["هُمْ","[mereka]"],["كَـٰفِرُونَ","(adalah) orang-orang kafir"]]],"2520":["Ayat ini diturunkan sewaktu mereka meminta disegerakan turunnya azab atas mereka. (Manusia telah dijadikan dari tergesa-gesa) disebabkan manusia itu bertabiat tergesa-gesa di dalam semua tindakannya, maka seolah-olah ia diciptakan daripadanya. (Kelak Aku akan perlihatkan kepada kalian tanda-tanda azab-Ku) yakni ketentuan waktu bagi azab-Ku (maka janganlah kalian minta kepada-Ku mendatangkannya dengan segera) kemudian Allah memperlihatkan kepada mereka turunnya azab itu, yaitu dengan dibunuhnya mereka dalam perang Badar.",[["خُلِقَ","Dicipta"],["ٱلْإِنسَـٰنُ","lelaki itu"],["مِنْ","daripada"],["عَجَلٍۢ ۚ","tergesa-gesa"],["سَأُو۟رِيكُمْ","Aku akan tunjukkan kepada kamu"],["ءَايَـٰتِى","Tanda-tanda Aku"],["فَلَا","jadi (jangan)"],["تَسْتَعْجِلُونِ","mintalah Aku menyegerakan"]]],"2521":["(Mereka berkata, \"Kapankah janji itu akan datang) yang dimaksud kiamat itu (jika kamu sekalian adalah orang-orang yang benar?\") tentang adanya janji itu.",[["وَيَقُولُونَ","Dan mereka berkata"],["مَتَىٰ","Bilakah (akan dipenuhi)"],["هَـٰذَا","ini"],["ٱلْوَعْدُ","janji"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"2522":["Allah berfirman (Andaikata orang-orang kafir itu mengetahui waktu mereka tidak dapat mengelakkan) di waktu mereka tidak mampu menolak (api neraka dari muka mereka dan tidak pula dari punggung mereka sedangkan mereka tidak pula mendapat pertolongan) yang dapat mencegah diri mereka daripada api neraka itu, di hari kiamat nanti. Jawab dari pada lafal Lau tidak disebutkan, yaitu, niscaya mereka tidak akan mengeluarkan perkataan tersebut.",[["لَوْ","Jika"],["يَعْلَمُ","tahu"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["حِينَ","(masa)."],["لَا","(apabila) tidak"],["يَكُفُّونَ","mereka akan mengelak"],["عَن","daripada"],["وُجُوهِهِمُ","muka mereka"],["ٱلنَّارَ","neraka"],["وَلَا","dan bukan"],["عَن","daripada"],["ظُهُورِهِمْ","belakang mereka"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يُنصَرُونَ","akan dibantu"]]],"2523":["(Sebenarnya akan mendatangi mereka) hari kiamat itu (dengan sekonyong-konyong lalu membuat mereka menjadi panik) menjadi bingung dan panik (maka mereka tidak sanggup menolaknya dan tidak pula mereka diberi tangguh) ditangguhkan untuk bertobat atau meminta ampunan.",[["بَلْ","Bahkan"],["تَأْتِيهِم","ia akan datang kepada mereka"],["بَغْتَةًۭ","tanpa diduga"],["فَتَبْهَتُهُمْ","dan membingungkan mereka"],["فَلَا","maka tidak"],["يَسْتَطِيعُونَ","mereka akan dapat"],["رَدَّهَا","untuk menolaknya"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يُنظَرُونَ","akan diberi tangguh"]]],"2524":["(Dan sungguh telah diperolok-olok beberapa orang rasul sebelum kamu) ayat ini mengandung hiburan yang ditujukan kepada Nabi saw. (maka turunlah) yakni menimpa (kepada orang-orang yang mencemoohkan rasul-rasul itu apa yang selalu mereka perolok-olokkan) yaitu berupa azab; demikian pula orang-orang yang memperolok-olokkan dirimu akan tertimpa azab yang sama seperti mereka.",[["وَلَقَدِ","Dan sesungguhnya"],["ٱسْتُهْزِئَ","diejek"],["بِرُسُلٍۢ","Utusan"],["مِّن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["فَحَاقَ","kemudian dikelilingi"],["بِٱلَّذِينَ","orang yang"],["سَخِرُوا۟","diejek"],["مِنْهُم","daripada mereka"],["مَّا","apa"],["كَانُوا۟","mereka gunakan"],["بِهِۦ","padanya"],["يَسْتَهْزِءُونَ","(untuk) mengejek"]]],"2525":["(Katakanlah) kepada mereka, (\"Siapakah yang dapat memelihara kalian) yang dapat menjaga diri kalian (di waktu malam dan siang hari daripada Tuhan Yang Maha Pemurah\") daripada azab-Nya, jika azab itu turun kepada kalian. Maksudnya, tentu saja tidak ada seorang pun yang dapat melakukan hal itu. Orang-orang yang diajak bicara oleh ayat ini tidak merasa takut kepada azab Allah, disebabkan mereka ingkar kepada-Nya atau tidak percaya kepada adanya azab itu. (Sebenarnya mereka terhadap peringatan Rabb mereka) yakni Alquran (adalah orang-orang yang berpaling) tidak mau memikirkan tentangnya.",[["قُلْ","Katakanlah"],["مَن","Siapa"],["يَكْلَؤُكُم","(boleh) melindungi kamu"],["بِٱلَّيْلِ","pada waktu malam"],["وَٱلنَّهَارِ","dan hari"],["مِنَ","daripada"],["ٱلرَّحْمَـٰنِ ۗ","Yang Maha Pemurah"],["بَلْ","Namun"],["هُمْ","mereka"],["عَن","daripada"],["ذِكْرِ","(the) zikir"],["رَبِّهِم","(dari) Tuhan mereka"],["مُّعْرِضُونَ","berpaling"]]],"2526":["(Atau) di dalam kalimat ini terkandung makna ingkar, maksudnya, apakah (mereka mempunyai tuhan-tuhan yang dapat memelihara diri mereka) dari apa-apa yang mencelakakan diri mereka (selain dari Kami) maksudnya apakah mereka mempunyai tuhan-tuhan selain Kami yang dapat mencegah diri mereka dari azab Allah? Tentu saja tidak (mereka pasti tidak akan sanggup) yakni tuhan-tuhan itu (menolong diri mereka sendiri) maka mereka tidak dapat menolongnya (dan tidak pula mereka) orang-orang kafir itu (dari Kami) yakni dari azab Kami (dilindungi) mendapat perlindungan. Asal katanya ialah dari kalimat Shahabakallaahu artinya mudah-mudahan Allah memelihara dan melindungimu.",[["أَمْ","Atau"],["لَهُمْ","mempunyai mereka"],["ءَالِهَةٌۭ","tuhan"],["تَمْنَعُهُم","(untuk) membela mereka"],["مِّن","daripada"],["دُونِنَا ۚ","Kami"],["لَا","Tidak"],["يَسْتَطِيعُونَ","mereka mampu"],["نَصْرَ","(untuk) menolong"],["أَنفُسِهِمْ","diri mereka"],["وَلَا","dan bukan"],["هُم","mereka"],["مِّنَّا","daripada Kami"],["يُصْحَبُونَ","boleh dilindungi"]]],"2527":["(Sebenarnya Kami telah memberi mereka dan bapak-bapak mereka kenikmatan) melalui yang Kami anugerahkan kepada mereka (sehingga panjanglah umur mereka) oleh karenanya mereka menjadi lupa daratan. (Maka apakah mereka tidak melihat bahwasanya Kami mendatangi negeri) mereka, yakni Kami menuju ke negeri orang-orang kafir (lalu Kami kurangi luasnya dari segala penjurunya) melalui penaklukkan yang dilakukan oleh Nabi saw. (Maka apakah mereka yang menang?) tentu saja tidak, tetapi Nabi dan sahabat-sahabatnyalah yang menang.",[["بَلْ","Bahkan"],["مَتَّعْنَا","Kami memberi peruntukan"],["هَـٰٓؤُلَآءِ","(kepada) ini"],["وَءَابَآءَهُمْ","dan bapa mereka"],["حَتَّىٰ","sehingga"],["طَالَ","bertambah panjang"],["عَلَيْهِمُ","bagi mereka"],["ٱلْعُمُرُ ۗ","kehidupan"],["أَفَلَا","Kemudian jangan"],["يَرَوْنَ","mereka lihat"],["أَنَّا","bahawa Kami"],["نَأْتِى","Kami datang"],["ٱلْأَرْضَ","(ke) tanah"],["نَنقُصُهَا","Kita kurangkan"],["مِنْ","daripada"],["أَطْرَافِهَآ ۚ","sempadannya"],["أَفَهُمُ","Begitu juga mereka"],["ٱلْغَـٰلِبُونَ","(yang akan) mengatasi"]]],"2528":["(Katakanlah) kepada mereka, (\"Sesungguhnya aku hanya memberi peringatan kepada kamu sekalian dengan wahyu) dari Allah swt. bukannya dari diriku sendiri (dan tiadalah orang-orang yang tuli mendengar seruan, apabila) dapat dibaca dengan menyatakan kedua Hamzahnya dan dengan meringankan bacaan Hamzah yang kedua, yaitu antara ucapan Hamzah dan Ya (mereka diberi peringatan\") disebabkan mereka tidak mau mengamalkan apa yang telah mereka dengar dari peringatan-peringatan, sehingga mereka disamakan dengan orang-orang yang tuli.",[["قُلْ","Katakanlah"],["إِنَّمَآ","Hanya"],["أُنذِرُكُم","Aku memberi amaran kepada kamu"],["بِٱلْوَحْىِ ۚ","oleh wahyu"],["وَلَا","Tetapi tidak"],["يَسْمَعُ","dengar"],["ٱلصُّمُّ","yang pekak"],["ٱلدُّعَآءَ","panggilan itu"],["إِذَا","apabila"],["مَا","apabila"],["يُنذَرُونَ","mereka diberi amaran"]]],"2529":["(Dan sesungguhnya jika mereka ditimpa sedikit saja) barang sedikit (dari azab Rabbmu, pastilah mereka berkata, \"Aduhai) menunjukkan makna penyesalan (celakalah kami) binasalah kami (bahwasanya kami adalah orang yang menganiaya diri sendiri\") disebabkan kami musyrik dan mendustakan Muhammad.",[["وَلَئِن","Dan jika"],["مَّسَّتْهُمْ","menyentuh mereka"],["نَفْحَةٌۭ","sedutan"],["مِّنْ","daripada"],["عَذَابِ","azab"],["رَبِّكَ","Tuhanmu"],["لَيَقُولُنَّ","pasti mereka akan berkata"],["يَـٰوَيْلَنَآ","Wahai celaka kami"],["إِنَّا","Sesungguhnya kami"],["كُنَّا","[kami] dulu"],["ظَـٰلِمِينَ","orang yang zalim"]]],"2530":["(Kami akan memasang timbangan yang tepat) timbangan yang adil (pada hari kiamat) pada hari itu (maka tiadalah dirugikan seseorang barang sedikit pun) dengan dikurangi pahala kebaikannya atau ditambahkan dosa keburukannya. (Dan jika) amalan itu (hanya seberat) sama beratnya dengan (biji sawi Kami mendatangkannya) yakni pahalanya. (Dan cukuplah Kami menjadi penghisab) segala sesuatu, yakni yang menghitungnya.",[["وَنَضَعُ","Dan Kami tetapkan"],["ٱلْمَوَٰزِينَ","penimbang"],["ٱلْقِسْطَ","(dari) keadilan"],["لِيَوْمِ","untuk (hari) itu"],["ٱلْقِيَـٰمَةِ","Kiamat"],["فَلَا","jadi tidak"],["تُظْلَمُ","akan dizalimi"],["نَفْسٌۭ","mana-mana jiwa"],["شَيْـًۭٔا ۖ","(dalam) apa-apa"],["وَإِن","Dan jika"],["كَانَ","(ada) ada"],["مِثْقَالَ","berat badan"],["حَبَّةٍۢ","(dari) benih"],["مِّنْ","daripada"],["خَرْدَلٍ","sebiji sawi"],["أَتَيْنَا","Kami akan bawa"],["بِهَا ۗ","[dengan] itu"],["وَكَفَىٰ","Dan mencukupi"],["بِنَا","(adalah) Kami"],["حَـٰسِبِينَ","(sebagai) Penghitung"]]],"2531":["(Dan sesungguhnya Kami telah berikan kepada Musa dan Harun kitab Taurat) kitab yang memisahkan antara perkara yang hak dan perkara yang batil dan antara perkara yang halal dan perkara yang haram (dan penerangan) sebagai penerang (serta pengajaran) sebagai pengajaran (bagi semua orang yang bertakwa).",[["وَلَقَدْ","Dan sesungguhnya"],["ءَاتَيْنَا","Kami memberi"],["مُوسَىٰ","Musa"],["وَهَـٰرُونَ","dan Harun"],["ٱلْفُرْقَانَ","Kriteria"],["وَضِيَآءًۭ","dan cahaya"],["وَذِكْرًۭا","dan Peringatan"],["لِّلْمُتَّقِينَ","untuk orang yang soleh"]]],"2532":["(Yaitu orang-orang yang takut kepada Rabb mereka sekalipun mereka menyendiri) jauh dari khalayak ramai, (dan mereka terhadap hari kiamat) yakni kengerian-kengeriannya (merasa takut) mereka merasa khawatir.",[["ٱلَّذِينَ","Orang yang"],["يَخْشَوْنَ","bertakwa"],["رَبَّهُم","Tuhan mereka"],["بِٱلْغَيْبِ","dalam ghaib"],["وَهُم","dan mereka"],["مِّنَ","daripada"],["ٱلسَّاعَةِ","Jam itu"],["مُشْفِقُونَ","(ada) takut"]]],"2533":["(Dan ini) yakni Alquran ini (adalah suatu kitab peringatan yang mempunyai berkah yang telah Kami turunkan. Maka mengapa kalian mengingkarinya?) Istifham atau kata tanya di sini mengandung pengertian mencemoohkan.",[["وَهَـٰذَا","Dan ini"],["ذِكْرٌۭ","(adalah) Peringatan"],["مُّبَارَكٌ","diberkati"],["أَنزَلْنَـٰهُ ۚ","yang Kami (telah) turunkan"],["أَفَأَنتُمْ","Kemudian adakah kamu"],["لَهُۥ","daripadanya"],["مُنكِرُونَ","penolakan"]]],"2534":["(Dan sesungguhnya telah Kami anugerahkan kepada Ibrahim hidayah kebenaran sebelumnya) sebelum ia mencapai umur balig (dan adalah Kami mengetahuinya) bahwa dia layak untuk menerima hal tersebut.",[["۞ وَلَقَدْ","Dan sesungguhnya"],["ءَاتَيْنَآ","Kami memberi"],["إِبْرَٰهِيمَ","Ibrahim"],["رُشْدَهُۥ","bimbingannya"],["مِن","sebelum"],["قَبْلُ","sebelum"],["وَكُنَّا","dan Kami"],["بِهِۦ","tentang dia"],["عَـٰلِمِينَ","Maha Mengetahui"]]],"2535":["(Yaitu ketika Ibrahim berkata kepada bapaknya dan kaumnya, \"Patung-patung apakah ini) maksudnya, apa kegunaan berhala-berhala ini (yang kalian tekun beribadah kepadanya?\") kalian dengan tekun menyembahnya.",[["إِذْ","Apabila"],["قَالَ","dia berkata"],["لِأَبِيهِ","kepada bapanya"],["وَقَوْمِهِۦ","dan umatnya"],["مَا","Apa"],["هَـٰذِهِ","(adalah) ini"],["ٱلتَّمَاثِيلُ","[the] patung-patung"],["ٱلَّتِىٓ","yang"],["أَنتُمْ","kamu"],["لَهَا","kepadanya"],["عَـٰكِفُونَ","(adalah) berbakti"]]],"2536":["(Mereka menjawab, \"Kami mendapatkan bapak-bapak kami menyembahnya\") maka kami mengikuti mereka.",[["قَالُوا۟","Mereka berkata"],["وَجَدْنَآ","Kami jumpa"],["ءَابَآءَنَا","nenek moyang kita"],["لَهَا","daripada mereka"],["عَـٰبِدِينَ","ahli ibadah"]]],"2537":["(Ibrahim berkata) kepada mereka, (\"Sesungguhnya kalian dan bapak-bapak kalian) disebabkan menyembah berhala-berhala itu (berada dalam kesesatan yang nyata\") yakni jelas sesatnya.",[["قَالَ","Dia berkata"],["لَقَدْ","Sesungguhnya"],["كُنتُمْ","kamu"],["أَنتُمْ","[kamu]"],["وَءَابَآؤُكُمْ","dan nenek moyang kamu"],["فِى","(berada) dalam"],["ضَلَـٰلٍۢ","satu kesilapan"],["مُّبِينٍۢ","nyata"]]],"2538":["(Mereka menjawab, \"Apakah kamu datang kepada kami dengan sungguh-sungguh) apakah perkataanmu yang demikian itu sungguh-sungguh (atau apakah kamu termasuk orang yang bermain-main?\") di dalam perkataanmu itu.",[["قَالُوٓا۟","Mereka berkata"],["أَجِئْتَنَا","Adakah kamu datang kepada kami"],["بِٱلْحَقِّ","dengan kebenaran"],["أَمْ","atau"],["أَنتَ","kamu"],["مِنَ","(adalah) daripada"],["ٱللَّـٰعِبِينَ","mereka yang bermain"]]],"2539":["(Ibrahim berkata, \"Sebenarnya Rabb kalian) yang berhak untuk disembah (ialah Rabb) yang memiliki (langit dan bumi yang telah menciptakannya) tanpa contoh sebelumnya (dan aku atas yang demikian itu) yang telah aku katakan sekarang ini (termasuk orang-orang yang menyaksikan\") nya.",[["قَالَ","Dia berkata"],["بَل","Bahkan"],["رَّبُّكُمْ","Tuhanmu"],["رَبُّ","(ialah) Tuhan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["ٱلَّذِى","yang Esa"],["فَطَرَهُنَّ","mencipta mereka"],["وَأَنَا۠","dan aku"],["عَلَىٰ","kepada"],["ذَٰلِكُم","bahawa"],["مِّنَ","daripada"],["ٱلشَّـٰهِدِينَ","para saksi"]]],"2540":["(Demi Allah, sesungguhnya aku akan melakukan tipu daya terhadap berhala-berhala kalian sesudah kalian pergi meninggalkannya).",[["وَتَٱللَّهِ","Dan demi Allah"],["لَأَكِيدَنَّ","pasti, aku akan merancang"],["أَصْنَـٰمَكُم","(terhadap) berhala-berhala kamu"],["بَعْدَ","selepas"],["أَن","[bahawa]"],["تُوَلُّوا۟","kamu pergi"],["مُدْبِرِينَ","membelakangkan (kamu)."]]],"2541":["(Maka Ibrahim membuat berhala-berhala itu) sesudah mereka pergi meninggalkannya menuju ke tempat pertemuan di hari raya mereka (menjadi puing-puing) dapat dibaca Judzaadzan dan Jidzaadzan, artinya hancur terpotong-potong di kapak oleh Nabi Ibrahim (kecuali yang terbesar dari mereka) lalu Nabi Ibrahim menggantungkan kapaknya ke pundak berhala yang terbesar itu (agar mereka kepadanya) yakni kepada berhala yang terbesar itu (menanyakannya) maka mereka akan melihat apa yang ia perbuat terhadap berhala-berhala yang lain.",[["فَجَعَلَهُمْ","Jadi dia membuat mereka"],["جُذَٰذًا","(menjadi) kepingan"],["إِلَّا","kecuali"],["كَبِيرًۭا","besar (satu)"],["لَّهُمْ","daripada mereka"],["لَعَلَّهُمْ","supaya mereka boleh"],["إِلَيْهِ","kepadanya"],["يَرْجِعُونَ","kembali"]]],"2542":["(Mereka berkata) setelah kembali dan melihat apa yang telah diperbuat terhadap berhala-berhala mereka, (\"Siapakah yang melakukan perbuatan ini terhadap tuhan-tuhan kami, sesungguhnya dia termasuk orang-orang yang zalim\") di dalam perbuatannya ini.",[["قَالُوا۟","Mereka berkata"],["مَن","Siapa"],["فَعَلَ","(telah) dilakukan"],["هَـٰذَا","ini"],["بِـَٔالِهَتِنَآ","kepada tuhan-tuhan kita"],["إِنَّهُۥ","Sesungguhnya dia"],["لَمِنَ","(adalah) daripada"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"2543":["(Mereka berkata) sebagian dari mereka kepada yang lain, (\"Kami dengar ada seorang pemuda yang menyebut-nyebut mereka) yakni yang mencaci maki berhala-berhala itu (yang bernama Ibrahim\")",[["قَالُوا۟","Mereka berkata"],["سَمِعْنَا","Kami dengar"],["فَتًۭى","seorang pemuda"],["يَذْكُرُهُمْ","menyebut mereka"],["يُقَالُ","dia dipanggil"],["لَهُۥٓ","dia dipanggil"],["إِبْرَٰهِيمُ","Ibrahim"]]],"2544":["(Mereka berkata, \"Kalau demikian, bawalah dia ke hadapan orang banyak) perlihatkanlah dia kepada mereka (agar mereka menyaksikan\") bahwasanya dialah yang telah melakukan semuanya ini.",[["قَالُوا۟","Mereka berkata"],["فَأْتُوا۟","Kemudian bawa"],["بِهِۦ","dia"],["عَلَىٰٓ","sebelum"],["أَعْيُنِ","(mata)."],["ٱلنَّاسِ","(daripada) rakyat"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَشْهَدُونَ","menjadi saksi"]]],"2545":["(Mereka bertanya) setelah menghadirkan Ibrahim, (\"Apakah kamu) dapat dibaca A'anta dan A-anta (yang melakukan perbuatan ini terhadap tuhan-tuhan kami, hai Ibrahim?\")",[["قَالُوٓا۟","Mereka berkata"],["ءَأَنتَ","Adakah kamu"],["فَعَلْتَ","selesai"],["هَـٰذَا","ini"],["بِـَٔالِهَتِنَا","kepada tuhan-tuhan kita"],["يَـٰٓإِبْرَٰهِيمُ","Wahai Ibrahim"]]],"2546":["(Ibrahim menjawab) seraya menyembunyikan apa yang sebenarnya telah ia lakukan, (\"Sebenarnya patung yang besar itulah yang melakukannya, maka tanyakanlah kepada berhala-berhala itu) siapakah pelakunya (jika mereka dapat berbicara\") Jawab syarat dari kalimat ayat ini telah didahulukan dan kalimat yang sebelumnya merupakan sindiran bagi para penyembah berhala, bahwa berhala-berhala yang telah dimaklumi ketidakmampuannya untuk berbuat itu bukan tuhan.",[["قَالَ","Dia berkata"],["بَلْ","Bahkan"],["فَعَلَهُۥ","(beberapa pelaku) melakukannya"],["كَبِيرُهُمْ","ketua mereka"],["هَـٰذَا","(adalah) ini"],["فَسْـَٔلُوهُمْ","Jadi tanya mereka"],["إِن","jika"],["كَانُوا۟","mereka (boleh)"],["يَنطِقُونَ","bercakap"]]],"2547":["(Maka mereka telah kembali kepada kesadaran mereka) setelah berpikir (lalu berkata) kepada diri mereka sendiri, (\"Sesungguhnya kalian adalah orang-orang yang berbuat aniaya\") disebabkan kalian menyembah berhala yang tidak dapat berbicara.",[["فَرَجَعُوٓا۟","Jadi mereka kembali"],["إِلَىٰٓ","kepada"],["أَنفُسِهِمْ","diri mereka"],["فَقَالُوٓا۟","dan berkata"],["إِنَّكُمْ","Sesungguhnya kamu"],["أَنتُمُ","[kamu]"],["ٱلظَّـٰلِمُونَ","(adalah) orang-orang yang zalim"]]],"2548":["(Kemudian mereka menundukkan) karena malu kepada Allah (kepala mereka) karena kekafirannya telah dinyatakan, maka mereka berkata, \"Demi Allah! (Sesungguhnya kamu telah mengetahui, bahwa berhala-berhala itu tidak dapat berbicara\") mengapa kamu menyuruh kami bertanya kepada mereka.",[["ثُمَّ","Kemudian"],["نُكِسُوا۟","mereka berpaling"],["عَلَىٰ","pada"],["رُءُوسِهِمْ","kepala mereka"],["لَقَدْ","Sesungguhnya"],["عَلِمْتَ","kamu tahu"],["مَا","tidak"],["هَـٰٓؤُلَآءِ","ini"],["يَنطِقُونَ","(boleh) bercakap"]]],"2549":["(Ibrahim berkata, \"Maka mengapakah kalian menyembah selain Allah) sebagai ganti dari-Nya untuk kalian sembah (sesuatu yang tidak dapat memberi manfaat sedikit pun kepada kalian) berupa rezeki dan lain-lainnya (dan tidak pula memberi mudarat kepada kalian?\") barang sedikit pun, jika kalian tidak menyembahnya.",[["قَالَ","Dia berkata"],["أَفَتَعْبُدُونَ","Kemudian adakah kamu beribadat"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["مَا","apa"],["لَا","tidak"],["يَنفَعُكُمْ","memberi manfaat kepada kamu"],["شَيْـًۭٔا","(dalam) apa-apa"],["وَلَا","dan bukan"],["يَضُرُّكُمْ","membahayakan kamu"]]],"2550":["(Ah, alangkah buruknya) lafal Uffin atau Uffan ini bermakna Mashdar, artinya busuklah (kalian beserta apa yang kalian sembah selain Allah. Maka apakah kalian tidak memahami?) bahwa berhala-berhala itu tidak berhak untuk disembah dan tidak layak untuk dijadikan sesembahan, karena sesungguhnya yang berhak disembah itu hanyalah Allah semata.",[["أُفٍّۢ","Uff"],["لَّكُمْ","kepada kamu"],["وَلِمَا","dan ke apa"],["تَعْبُدُونَ","kamu menyembah"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ ۖ","Allah"],["أَفَلَا","Kemudian tidak akan"],["تَعْقِلُونَ","kamu menggunakan alasan"]]],"2551":["(Mereka berkata, \"Bakarlah dia) yakni Nabi Ibrahim (dan bantulah tuhan-tuhan kalian) dengan membakar Ibrahim (jika kalian benar-benar hendak bertindak\") untuk menolong tuhan-tuhan kalian. Mereka segera mengumpulkan kayu-kayu yang banyak sekali, lalu mereka menyalakannya. Mereka mengikat Nabi Ibrahim, kemudian menaruhnya pada Manjaniq atau alat pelontar yang besar, lalu Nabi Ibrahim dilemparkan ke dalam api yang besar itu. Allah berfirman:",[["قَالُوا۟","Mereka berkata"],["حَرِّقُوهُ","Bakar dia"],["وَٱنصُرُوٓا۟","dan sokongan"],["ءَالِهَتَكُمْ","tuhan-tuhan kamu"],["إِن","jika"],["كُنتُمْ","kamu"],["فَـٰعِلِينَ","pelaku"]]],"2552":["(Kami berfirman, \"Hai api! Menjadi dinginlah dan menjadi keselamatanlah bagi Ibrahim\") maka api itu tidak membakarnya selain pada tali-tali pengikatnya saja dan lenyaplah panas api itu, yang tinggal hanyalah cahayanya saja, hal ini berkat perintah Allah, 'Salaaman' yakni menjadi keselamatan bagi Ibrahim, akhirnya Nabi Ibrahim selamat dari kematian karena api itu dingin.",[["قُلْنَا","Kami berkata"],["يَـٰنَارُ","Wahai api"],["كُونِى","Jadilah"],["بَرْدًۭا","kesejukan"],["وَسَلَـٰمًا","dan selamat[ty]"],["عَلَىٰٓ","bagi"],["إِبْرَٰهِيمَ","Ibrahim"]]],"2553":["(Mereka hendak berbuat makar terhadap Ibrahim) yaitu dengan membakarnya (maka Kami menjadikan mereka itu orang-orang yang paling merugi) di dalam tujuan mereka.",[["وَأَرَادُوا۟","Dan mereka berniat"],["بِهِۦ","baginya"],["كَيْدًۭا","sesuatu rancangan"],["فَجَعَلْنَـٰهُمُ","tetapi Kami jadikan mereka"],["ٱلْأَخْسَرِينَ","paling rugi"]]],"2554":["(Dan Kami selamatkan Ibrahim dan Luth) anak saudara Nabi Ibrahim yang bernama Haran yang tinggal di negeri Iraq (ke sebuah negeri yang Kami telah memberkahinya untuk sekalian manusia) dengan menjadikan sungai-sungai dan pohon-pohon yang banyak padanya, yaitu negeri Syam. Nabi Ibrahim tinggal di negeri Palestina sedangkan Nabi Luth di Mu'tafikah; jarak antara kedua negeri itu dapat ditempuh dalam sehari.",[["وَنَجَّيْنَـٰهُ","Dan Kami selamatkan dia"],["وَلُوطًا","dan Lut"],["إِلَى","kepada"],["ٱلْأَرْضِ","bumi"],["ٱلَّتِى","yang"],["بَـٰرَكْنَا","Kami (telah) memberkati"],["فِيهَا","[di dalamnya]"],["لِلْعَـٰلَمِينَ","untuk dunia"]]],"2555":["(Dan Kami telah memberikan kepadanya) kepada Ibrahim, yang sebelumnya selalu mendambakan mempunyai seorang anak, sebagaimana yang disebutkan di dalam surah Ash-Shaffat (Ishak dan Yakub sebagai suatu anugerah) dari Kami, yaitu anugerah yang lebih daripada apa yang dimintanya. Atau yang dimaksud dengan Naafilah adalah cucu (Dan masing-masingnya) Nabi Ibrahim dan kedua anaknya itu (Kami jadikan orang-orang yang saleh) yakni menjadi nabi semuanya.",[["وَوَهَبْنَا","Dan Kami kurniakan"],["لَهُۥٓ","pada dia"],["إِسْحَـٰقَ","Ishak"],["وَيَعْقُوبَ","dan Yaqub"],["نَافِلَةًۭ ۖ","(dalam) tambahan"],["وَكُلًّۭا","dan semua"],["جَعَلْنَا","Kami buat"],["صَـٰلِحِينَ","soleh"]]],"2556":["(Kami telah menjadikan mereka itu sebagian pemimpin-pemimpin) dapat dibaca A-immatan atau Ayimmatan, yakni pemimpin yang menjadi teladan dalam kebaikan (yang memberi petunjuk) kepada manusia (dengan perintah Kami) memberi petunjuk kepada mereka untuk memeluk agama Kami (dan telah Kami wahyukan kepada mereka mengerjakan kebajikan, mendirikan salat, menunaikan zakat) hendaknya mereka dan orang-orang yang mengikuti mereka mengerjakan semuanya itu. Huruf Ha dari lafal Iqaamah dibuang demi untuk meringankan bunyi, sehingga menjadi Iqaamash Shalaati bukan Iqaamatish Shalaati (dan hanya kepada Kamilah mereka selalu menyembah).",[["وَجَعَلْنَـٰهُمْ","Dan Kami jadikan mereka"],["أَئِمَّةًۭ","pemimpin"],["يَهْدُونَ","mereka membimbing"],["بِأَمْرِنَا","dengan Perintah Kami"],["وَأَوْحَيْنَآ","Dan Kami ilhamkan"],["إِلَيْهِمْ","kepada mereka"],["فِعْلَ","(yang) melakukan"],["ٱلْخَيْرَٰتِ","(dari) perbuatan baik"],["وَإِقَامَ","dan penubuhan"],["ٱلصَّلَوٰةِ","(dari) solat"],["وَإِيتَآءَ","dan memberi"],["ٱلزَّكَوٰةِ ۖ","(dari) zakat"],["وَكَانُوا۟","dan mereka"],["لَنَا","daripada Kami"],["عَـٰبِدِينَ","ahli ibadah"]]],"2557":["(Dan kepada Luth, Kami telah berikan hukum) yang memutuskan di antara orang-orang yang bersengketa (dan ilmu dan telah Kami selamatkan dia dari azab yang telah menimpa kota yang penduduknya mengerjakan) perbuatan-perbuatan (keji) yaitu seperti liwath atau homosex, main dadu, menebak nasib dengan burung dan lain sebagainya. (Sesungguhnya mereka adalah kaum yang jahat) lafal Sau-in adalah bentuk Mashdar dari lafal Saa-a lawan kata dari Sarra, artinya jahat atau buruk (lagi fasik).",[["وَلُوطًا","Dan (kepada) Lut"],["ءَاتَيْنَـٰهُ","Kami beri dia"],["حُكْمًۭا","penghakiman"],["وَعِلْمًۭا","dan pengetahuan"],["وَنَجَّيْنَـٰهُ","dan Kami selamatkan dia"],["مِنَ","daripada"],["ٱلْقَرْيَةِ","bandar itu"],["ٱلَّتِى","yang"],["كَانَت","adalah"],["تَّعْمَلُ","melakukan"],["ٱلْخَبَـٰٓئِثَ ۗ","perbuatan jahat"],["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوا۟","adalah"],["قَوْمَ","suatu kaum"],["سَوْءٍۢ","jahat"],["فَـٰسِقِينَ","membangkang menderhaka"]]],"2558":["(Dan Kami masukkan dia ke dalam rahmat Kami) yang antara lain dia Kami selamatkan dari kaumnya. (Karena sesungguhnya dia termasuk orang-orang yang saleh).",[["وَأَدْخَلْنَـٰهُ","Dan Kami masukkan dia"],["فِى","ke dalam"],["رَحْمَتِنَآ ۖ","Kerahiman Kami"],["إِنَّهُۥ","Sesungguhnya dia"],["مِنَ","(adalah) daripada"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"2559":["(Dan) ingatlah kisah (Nuh) kalimat yang sesudahnya merupakan Badal atau kata ganti daripadanya (ketika dia berdoa) yakni berdoa bagi kebinasaan kaumnya, sebagaimana yang disitir oleh ayat lain, yaitu firman-Nya, \"Ya Rabbku! Janganlah Engkau biarkan seorang pun di antara orang-orang kafir itu tinggal di atas bumi.\" (Q.S. Nuh, 26). (sebelum itu) sebelum Nabi Ibrahim dan Nabi Luth (dan Kami memperkenankan doanya, lalu Kami selamatkan dia beserta keluarganya) beserta orang-orang yang ada di dalam bahteranya (dari bencana yang besar) dari bencana tenggelam dan permusuhan kaumnya yang mendustakannya.",[["وَنُوحًا","Dan Nuh"],["إِذْ","apabila"],["نَادَىٰ","dia panggil"],["مِن","sebelum"],["قَبْلُ","sebelum"],["فَٱسْتَجَبْنَا","jadi Kami menjawab"],["لَهُۥ","kepadanya"],["فَنَجَّيْنَـٰهُ","dan Kami selamatkan dia"],["وَأَهْلَهُۥ","dan keluarganya"],["مِنَ","daripada"],["ٱلْكَرْبِ","penderitaan itu"],["ٱلْعَظِيمِ","[yang] hebat"]]],"2560":["(Dan Kami telah menolongnya) Kami pelihara dia (dari kaum yang telah mendustakan ayat-ayat Kami) yang menunjukkan kerasulannya, hingga mereka tidak dapat menimpakan keburukan kepadanya (Sesungguhnya mereka adalah kaum yang jahat, maka Kami tenggelamkan mereka semuanya).",[["وَنَصَرْنَـٰهُ","Dan Kami menolongnya"],["مِنَ","daripada"],["ٱلْقَوْمِ","manusia"],["ٱلَّذِينَ","yang"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَآ ۚ","Tanda-Tanda Kami"],["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوا۟","adalah"],["قَوْمَ","suatu kaum"],["سَوْءٍۢ","jahat"],["فَأَغْرَقْنَـٰهُمْ","maka Kami tenggelamkan mereka"],["أَجْمَعِينَ","semua"]]],"2561":["(Dan) ingatlah (Daud dan Sulaiman) yakni kisah keduanya, dijelaskan oleh ayat selanjutnya (di waktu keduanya memberikan keputusan mengenai tanaman) berupa ladang atau pohon anggur (karena tanaman itu dirusak oleh kambing-kambing kepunyaan kaumnya) kambing-kambing itu memakannya dan merusaknya di waktu malam hari tanpa ada penggembalanya, karena kambing-kambing itu lepas dengan sendirinya dari kandangnya. (Dan adalah Kami menyaksikan keputusan yang diberikan oleh mereka itu) Dhamir jamak dalam ayat ini menunjukkan makna untuk dua orang, yaitu Nabi Daud dan Nabi Sulaiman. Lalu Nabi Daud berkata, \"Pemilik ladang itu berhak untuk memiliki kambing-kambing yang telah merusak ladangnya\". Akan tetapi Nabi Sulaiman memutuskan, \"Pemilik kebun hanya diperbolehkan memanfaatkan air susu, anak-anak dan bulu-bulunya, sampai tanaman ladang kembali seperti semula, diperbaiki oleh pemilik kambing, setelah itu ia diharuskan mengembalikan kambing-kambing itu kepada pemiliknya\".",[["وَدَاوُۥدَ","Dan Daud"],["وَسُلَيْمَـٰنَ","dan Sulaiman"],["إِذْ","apabila"],["يَحْكُمَانِ","mereka menilai"],["فِى","tentang"],["ٱلْحَرْثِ","padang"],["إِذْ","apabila"],["نَفَشَتْ","digembala"],["فِيهِ","di dalamnya"],["غَنَمُ","biri-biri"],["ٱلْقَوْمِ","(dari) suatu kaum"],["وَكُنَّا","dan Kami"],["لِحُكْمِهِمْ","kepada penghakiman mereka"],["شَـٰهِدِينَ","saksi"]]],"2562":["(Maka Kami telah memberikan pengertian tentang hukum) yakni keputusan yang adil dan tepat (kepada Sulaiman) keputusan yang dilakukan oleh keduanya itu berdasarkan ijtihad masing-masing, kemudian Nabi Daud mentarjihkan atau menguatkan keputusan yang diambil oleh Nabi Sulaiman. Menurut suatu pendapat dikatakan, bahwa keputusan keduanya itu berdasarkan wahyu dari Allah dan keputusan yang kedua yaitu yang telah diambil oleh Nabi Sulaiman berfungsi memansukh hukum yang pertama, yakni hukum Nabi Daud (dan kepada masing-masing) daripada keduanya (Kami berikan) kepadanya (hikmah) kenabian (dan ilmu) tentang masalah-masalah agama (dan telah Kami tundukkan gunung-gunung dan burung-burung, semua bertasbih bersama Daud) demikianlah gunung-gunung dan burung-burung itu ditundukkan untuk bertasbih bersama Nabi Daud. Nabi Daud memerintahkan gunung-gunung dan burung-burung untuk ikut bertasbih bersamanya bila ia mengalami kelesuan, hingga ia menjadi semangat lagi dalam bertasbih. (Dan Kamilah yang melakukannya) yakni Kamilah yang menundukkan keduanya dapat bertasbih bersama Daud, sekalipun hal ini menurut kalian merupakan hal yang ajaib dan aneh yaitu tunduk dan patuhnya gunung-gunung dan burung-burung kepada perintah Nabi Daud.",[["فَفَهَّمْنَـٰهَا","Dan Kami berikan kefahaman tentangnya"],["سُلَيْمَـٰنَ ۚ","(kepada) Sulaiman"],["وَكُلًّا","dan (kepada) setiap satu"],["ءَاتَيْنَا","Kami memberi"],["حُكْمًۭا","penghakiman"],["وَعِلْمًۭا ۚ","dan pengetahuan"],["وَسَخَّرْنَا","Dan Kami tundukkan"],["مَعَ","dengan"],["دَاوُۥدَ","Dawud"],["ٱلْجِبَالَ","pergunungan"],["يُسَبِّحْنَ","(untuk) bertasbih dengan memuji Kami"],["وَٱلطَّيْرَ ۚ","dan burung"],["وَكُنَّا","Dan Kami"],["فَـٰعِلِينَ","para Pelaku"]]],"2563":["(Dan Kami ajarkan kepada Daud membuat baju besi) yaitu baju yang terbuat dari besi, dialah orang pertama yang menciptakannya dan sebelumnya hanyalah berupa lempengan-lempengan besi saja (untuk kalian) yakni untuk segolongan manusia (guna melindungi diri kalian) jika dibaca Linuhshinakum, maka Dhamirnya kembali kepada Allah, maksudnya, supaya Kami melindungi kalian. Dan jika ia dibaca Lituhshinahum, maka Dhamirnya kembali kepada baju besi, maksudnya, supaya baju besi itu melindungi diri kalian. Jika dibaca Liyuhshinakum, maka Dhamirnya kembali kepada Nabi Daud, maksudnya, supaya dia melindungi kalian (dalam peperangan kalian) melawan musuh-musuh kalian. (Maka hendaklah kalian) hai penduduk Mekah (bersyukur) atas nikmat karunia-Ku itu, yaitu dengan percaya kepada Rasulullah. Maksudnya bersyukurlah kalian atas hal tersebut kepada-Ku.",[["وَعَلَّمْنَـٰهُ","Dan Kami ajarkan kepadanya"],["صَنْعَةَ","(yang) membuat"],["لَبُوسٍۢ","(dari) perisai"],["لَّكُمْ","bagi kamu"],["لِتُحْصِنَكُم","untuk melindungi kamu"],["مِّنۢ","daripada"],["بَأْسِكُمْ ۖ","pertempuran kamu"],["فَهَلْ","Kemudian akan"],["أَنتُمْ","kamu"],["شَـٰكِرُونَ","(bersyukur)."]]],"2564":["(Dan) telah Kami tundukkan (untuk Sulaiman angin yang sangat kencang tiupannya) dan pada ayat yang lain disebutkan Rukha-an, artinya angin yang sangat kencang dan pelan tiupannya, kesemuanya itu sesuai dengan kehendak Nabi Sulaiman (yang berhembus dengan perintahnya ke negeri yang kami telah memberkatinya) yakni negeri Syam. (Dan adalah Kami Maha Mengetahui segala sesuatu) antara lain ilmu Allah yang telah diberikan kepada Sulaiman itu akan mendorongnya tunduk patuh kepada Rabbnya. Allah melakukan hal itu sesuai dengan ilmu-Nya yang maha mengetahui segala sesuatu.",[["وَلِسُلَيْمَـٰنَ","Dan kepada Sulaiman"],["ٱلرِّيحَ","angin"],["عَاصِفَةًۭ","secara paksa"],["تَجْرِى","meniup"],["بِأَمْرِهِۦٓ","dengan perintahnya"],["إِلَى","kepada"],["ٱلْأَرْضِ","bumi"],["ٱلَّتِى","yang"],["بَـٰرَكْنَا","Kami memberkati"],["فِيهَا ۚ","[di dalamnya]"],["وَكُنَّا","Dan Kami"],["بِكُلِّ","daripada setiap"],["شَىْءٍ","perkara"],["عَـٰلِمِينَ","Orang yang tahu"]]],"2565":["(Dan) telah Kami tundukkan pula kepadanya (segolongan setan-setan yang menyelam untuknya) mereka menyelam ke dalam laut, lalu mereka mengeluarkan batu-batu permata dari dalamnya untuk Nabi Sulaiman (dan mereka mengerjakan pekerjaan selain daripada itu) selain menyelam, yaitu seperti membangun bangunan dan pekerjaan-pekerjaan berat lainnya (dan adalah Kami memelihara mereka) supaya mereka jangan merusak lagi pekerjaan-pekerjaan yang telah mereka perbuat. Karena watak setan itu bilamana selesai dari suatu pekerjaan sebelum malam tiba, mereka merusaknya kembali, jika mereka tidak disuruh mengerjakan pekerjaan yang lain.",[["وَمِنَ","Dan daripada"],["ٱلشَّيَـٰطِينِ","syaitan"],["مَن","(adalah beberapa) yang"],["يَغُوصُونَ","akan menyelam"],["لَهُۥ","baginya"],["وَيَعْمَلُونَ","dan akan lakukan"],["عَمَلًۭا","kerja"],["دُونَ","selain daripada"],["ذَٰلِكَ ۖ","bahawa"],["وَكُنَّا","Dan Kami"],["لَهُمْ","daripada mereka"],["حَـٰفِظِينَ","Penjaga"]]],"2566":["(Dan) ingatlah kisah (Ayub,) kemudian dijelaskan oleh Badalnya, yaitu (ketika ia menyeru Rabbnya) pada saat itu dia mendapat cobaan dari-Nya; semua harta bendanya lenyap dan semua anak-anaknya mati serta badannya sendiri tercabik-cabik oleh penyakit, semua orang menjauhinya kecuali istrinya. Hal ini dialaminya selama tiga belas tahun, ada yang mengatakan tujuh belas tahun dan ada pula yang mengatakan delapan belas tahun. Selama itu penghidupan Nabi Ayub sangat sulit dan sengsara (\"Sesungguhnya aku) asal kata Annii adalah Bi-ann (telah ditimpa kemudaratan) yakni hidup sengsara (dan Engkau adalah Yang Maha Penyayang di antara semua penyayang\").",[["۞ وَأَيُّوبَ","Dan Ayub"],["إِذْ","apabila"],["نَادَىٰ","dia panggil"],["رَبَّهُۥٓ","(kepada) Tuhannya"],["أَنِّى","Sesungguhnya, [aku]"],["مَسَّنِىَ","telah menyentuh aku"],["ٱلضُّرُّ","kesusahan itu"],["وَأَنتَ","dan kamu"],["أَرْحَمُ","(adalah) Maha Penyayang"],["ٱلرَّٰحِمِينَ","(dari) Yang Maha Pemurah"]]],"2567":["(Maka Kami pun memperkenankan seruannya) doanya (lalu Kami lenyapkan penyakit yang ada padanya dan Kami kembalikan keluarganya kepadanya) yakni semua anak-anaknya baik yang laki-laki maupun yang perempuan, dengan cara menghidupkan mereka kembali. Jumlah anaknya ada tiga atau tujuh orang (dan Kami lipat gandakan bilangan mereka) bilangan anak-anaknya yang dilahirkan dari istrinya dan istrinya pun dimudakan-Nya. Nabi Ayub mempunyai dua buah lumbung; yang satu untuk tempat gandum dan yang satu lagi untuk tempat jewawut. Kemudian Allah mengirimkan dua kelompok awan; yang satu menurunkan hujan emas pada lumbung tempat gandum dan yang satunya lagi menurunkan hujan perak pada lumbung tempat jewawut, sehingga kedua lumbung itu penuh dengan emas dan perak (sebagai suatu rahmat) lafal Rahmatan ini menjadi Maf'ul Lah (dari sisi Kami) lafal Min 'Indinaa ini berkedudukan menjadi kata sifat (dan untuk menjadi peringatan bagi semua yang menyembah Allah) supaya mereka bersabar, yang karenanya mereka akan mendapatkan pahala.",[["فَٱسْتَجَبْنَا","Maka Kami menjawab"],["لَهُۥ","kepadanya"],["فَكَشَفْنَا","dan Kami hapuskan"],["مَا","apa"],["بِهِۦ","(ada) padanya"],["مِن","daripada"],["ضُرٍّۢ ۖ","(the) kesusahan"],["وَءَاتَيْنَـٰهُ","Dan Kami berikan kepadanya"],["أَهْلَهُۥ","keluarganya"],["وَمِثْلَهُم","dan (yang) seumpamanya"],["مَّعَهُمْ","bersama mereka"],["رَحْمَةًۭ","(sebagai) Rahmat"],["مِّنْ","daripada Diri Kami"],["عِندِنَا","daripada Diri Kami"],["وَذِكْرَىٰ","dan peringatan"],["لِلْعَـٰبِدِينَ","untuk orang yang beribadat"]]],"2568":["(Dan) ingatlah kisah (Ismail, Idris dan Zulkifli. Semua mereka termasuk orang-orang yang sabar) di dalam menjalankan ketaatan kepada Allah dan menjauhi kedurhakaan kepada-Nya.",[["وَإِسْمَـٰعِيلَ","Dan Ismail"],["وَإِدْرِيسَ","dan Idris"],["وَذَا","dan Dzulkifli"],["ٱلْكِفْلِ ۖ","dan Dzulkifli"],["كُلٌّۭ","semua"],["مِّنَ","(adalah) daripada"],["ٱلصَّـٰبِرِينَ","yang sabar"]]],"2569":["(Kami telah memasukkan mereka ke dalam rahmat Kami) yakni kenabian. (Sesungguhnya mereka termasuk orang-orang yang saleh) orang-orang yang mensyukuri rahmat Kami. Dinamakan Zulkifli karena ia telah menyanggupi akan melakukan puasa di siang hari dan beribadah pada malam harinya, serta ia berjanji akan memutuskan peradilan di antara orang-orang dan tidak akan marah. Kemudian ternyata ia memenuhi apa yang telah dijanjikannya itu. Menurut suatu pendapat dikatakan bahwa ia bukan seorang nabi, akan tetapi hanya orang saleh atau wali Allah saja.",[["وَأَدْخَلْنَـٰهُمْ","Dan Kami mengakui mereka"],["فِى","dalam"],["رَحْمَتِنَآ ۖ","Kerahiman Kami"],["إِنَّهُم","Sesungguhnya mereka"],["مِّنَ","(adalah) daripada"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"2570":["(Dan) ingatlah kisah (Dzun Nun) yaitu orang yang mempunyai ikan yang besar, dia adalah Nabi Yunus bin Mataa. Kemudian dijelaskan kalimat Dzun Nun ini oleh Badalnya pada ayat selanjutnya, yaitu (ketika ia pergi dalam keadaan marah) terhadap kaumnya, disebabkan perlakuan kaumnya yang menyakitkan dirinya, sedangkan Nabi Yunus belum mendapat izin dari Allah untuk pergi (lalu ia menyangka bahwa Kami tidak akan mampu untuk menjangkaunya) menghukumnya sesuai dengan apa yang telah Kami pastikan baginya, yaitu menahannya di dalam perut ikan paus, atau menyulitkan dirinya disebabkan hal tersebut (maka ia menyeru dalam tempat yang gelap gulita) gelapnya malam dan gelapnya laut serta gelapnya suasana dalam perut ikan paus (\"bahwa) asal kata An adalah Bi-an, artinya, bahwasanya (tiada Tuhan selain Engkau, Maha Suci Engkau, sesungguhnya aku adalah termasuk orang-orang yang zalim\") karena pergi dari kaumku tanpa seizin Allah.",[["وَذَا","Dan Dhun-Nun"],["ٱلنُّونِ","Dan Dhun-Nun"],["إِذ","apabila"],["ذَّهَبَ","dia pergi"],["مُغَـٰضِبًۭا","(sambil) marah"],["فَظَنَّ","dan berfikir"],["أَن","bahawa"],["لَّن","tidak pernah"],["نَّقْدِرَ","Kami akan dekri"],["عَلَيْهِ","atasnya"],["فَنَادَىٰ","Kemudian dia menelefon"],["فِى","dalam"],["ٱلظُّلُمَـٰتِ","kegelapan (es)"],["أَن","bahawa"],["لَّآ","(Ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّآ","kecuali"],["أَنتَ","kamu"],["سُبْحَـٰنَكَ","Maha Suci Engkau"],["إِنِّى","Sesungguhnya, [aku]"],["كُنتُ","aku"],["مِنَ","daripada"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"2571":["(Maka Kami telah memperkenankan doanya dan menyelamatkannya daripada kedukaan) disebabkan kalimat-kalimat tersebut. (Dan demikianlah) sebagaimana Kami menyelamatkan dia (Kami selamatkan orang-orang yang beriman) daripada malapetaka yang menimpa mereka, jika mereka meminta tolong kepada Kami seraya berdoa.",[["فَٱسْتَجَبْنَا","Maka Kami menjawab"],["لَهُۥ","kepadanya"],["وَنَجَّيْنَـٰهُ","dan Kami selamatkan dia"],["مِنَ","daripada"],["ٱلْغَمِّ ۚ","kesusahan itu"],["وَكَذَٰلِكَ","Dan dengan demikian"],["نُـۨجِى","Kita jimat"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"2572":["(Dan) ingatlah kisah (Zakaria) kemudian dijelaskan oleh Badalnya pada ayat selanjutnya (tatkala ia menyeru Rabbnya) melalui doanya yang mengatakan, (\"Ya Rabbku! Janganlah Engkau membiarkan aku hidup seorang diri) tanpa anak yang kelak akan mewarisiku (dan Engkaulah Waris Yang Paling Baik\") yang tetap abadi sesudah semua makhluk-Mu musnah.",[["وَزَكَرِيَّآ","Dan Zakariya"],["إِذْ","apabila"],["نَادَىٰ","dia panggil"],["رَبَّهُۥ","(kepada) Tuhannya"],["رَبِّ","Tuhanku"],["لَا","Jangan"],["تَذَرْنِى","tinggalkan aku"],["فَرْدًۭا","bersendirian"],["وَأَنتَ","manakala Engkau"],["خَيْرُ","(adalah) [yang] Terbaik"],["ٱلْوَٰرِثِينَ","(dari) ahli waris"]]],"2573":["(Maka Kami memperkenankan doanya) yakni seruannya itu (dan Kami anugerahkan kepadanya Yahya) sebagai anaknya (dan Kami jadikan istrinya dapat mengandung) sehingga dapat melahirkan anak, padahal sebelumnya ia mandul. (Sesungguhnya mereka) para Nabi yang telah disebutkan tadi (adalah orang-orang yang selalu bersegera) mereka selalu bergegas-gegas (di dalam kebaikan-kebaikan) mengerjakan amal-amal ketaatan (dan mereka berdoa kepada Kami dengan mengharapkan) rahmat Kami (dan takut) kepada azab Kami. (Dan mereka adalah orang-orang yang khusyuk kepada Kami) yakni merendahkan diri dan patuh di dalam beribadah.",[["فَٱسْتَجَبْنَا","Maka Kami menjawab"],["لَهُۥ","kepadanya"],["وَوَهَبْنَا","dan Kami kurniakan"],["لَهُۥ","pada dia"],["يَحْيَىٰ","Yahya"],["وَأَصْلَحْنَا","dan Kami menyembuhkan"],["لَهُۥ","baginya"],["زَوْجَهُۥٓ ۚ","isterinya"],["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوا۟","digunakan (untuk)"],["يُسَـٰرِعُونَ","cepatkan"],["فِى","dalam"],["ٱلْخَيْرَٰتِ","perbuatan baik"],["وَيَدْعُونَنَا","dan mereka berdoa kepada Kami"],["رَغَبًۭا","(dalam) harapan"],["وَرَهَبًۭا ۖ","dan ketakutan"],["وَكَانُوا۟","dan mereka"],["لَنَا","kepada Kami"],["خَـٰشِعِينَ","tunduk dengan rendah hati"]]],"2574":["(Dan) ingatlah kisah Maryam (yang telah memelihara kehormatannya) ia memeliharanya supaya tidak dinodai (lalu Kami tiupkan ke dalam tubuhnya roh dari Kami) malaikat Jibril; dialah yang meniup ke dalam baju kurungnya, lalu Maryam mengandung Isa (dan Kami jadikan dia dan anaknya sebagai tanda yang besar bagi semesta alam) yakni manusia, jin dan malaikat, karena ia dapat mengandung tanpa lelaki.",[["وَٱلَّتِىٓ","Dan dia yang"],["أَحْصَنَتْ","terjaga"],["فَرْجَهَا","kesuciannya"],["فَنَفَخْنَا","jadi Kami bernafas"],["فِيهَا","ke dalam dia"],["مِن","daripada"],["رُّوحِنَا","Roh kita"],["وَجَعَلْنَـٰهَا","dan Kami jadikan dia"],["وَٱبْنَهَآ","dan anaknya"],["ءَايَةًۭ","satu tanda"],["لِّلْعَـٰلَمِينَ","untuk dunia"]]],"2575":["(Sesungguhnya ini) agama Islam atau agama tauhid ini (adalah agama kalian) hai orang-orang yang diajak berbicara. Maksudnya, kalian wajib memeluknya (agama yang satu) lafal ayat ini berkedudukan menjadi Hal yang bersifat tetap (dan Aku adalah Rabb kalian, maka sembahlah Aku) tauhidkan atau esakanlah Aku.",[["إِنَّ","Sesungguhnya"],["هَـٰذِهِۦٓ","ini"],["أُمَّتُكُمْ","(ialah) agama kamu"],["أُمَّةًۭ","agama"],["وَٰحِدَةًۭ","satu"],["وَأَنَا۠","dan Aku"],["رَبُّكُمْ","Tuhanmu"],["فَٱعْبُدُونِ","maka sembahlah Aku"]]],"2576":["(Dan mereka telah memotong-motong) sebagian daripada orang-orang yang diajak bicara itu (urusan agama mereka di antara mereka) yakni mereka memecah belah perkara agama mereka; sebagian dari mereka bertentangan dengan sebagian yang lain di dalam masalah agama. Mereka adalah sekte-sekte dari agama Yahudi dan Nasrani. Lalu Allah berfirman, (\"Kepada Kamilah masing-masing golongan itu akan kembali) kemudian Kami akan membalas amal perbuatan mereka.",[["وَتَقَطَّعُوٓا۟","Tetapi mereka memotong"],["أَمْرَهُم","urusan mereka"],["بَيْنَهُمْ ۖ","sesama mereka"],["كُلٌّ","semua"],["إِلَيْنَا","kepada Kami"],["رَٰجِعُونَ","(akan) kembali"]]],"2577":["(Maka barang siapa mengerjakan amal saleh, sedang ia beriman, maka tidak ada pengingkaran) tidak diingkari (terhadap amalannya dan sesungguhnya Kami menuliskan amalannya itu untuknya) Kami perintahkan Malaikat-malaikat penulis amal untuk menuliskannya, kemudian akan Kami balas amal perbuatan itu.",[["فَمَن","Kemudian sesiapa sahaja"],["يَعْمَلْ","tidak"],["مِنَ","[daripada]"],["ٱلصَّـٰلِحَـٰتِ","[yang] amal soleh"],["وَهُوَ","sedangkan dia"],["مُؤْمِنٌۭ","(adalah) seorang yang beriman"],["فَلَا","maka tidak"],["كُفْرَانَ","(akan) ditolak"],["لِسَعْيِهِۦ","[dari] usahanya"],["وَإِنَّا","Dan sesungguhnya, Kami"],["لَهُۥ","daripadanya"],["كَـٰتِبُونَ","(adalah) Perakam"]]],"2578":["(Sungguh tidak mungkin atas suatu negeri yang telah Kami binasakan) yang dimaksud adalah penduduknya (bahwa mereka) huruf La di sini Zaidah yakni tidak ada maknanya (akan kembali) maksudnya mereka tidak mungkin akan dapat hidup kembali ke dunia.",[["وَحَرَٰمٌ","Dan (ada) larangan"],["عَلَىٰ","ke atas"],["قَرْيَةٍ","sebuah bandar"],["أَهْلَكْنَـٰهَآ","yang telah Kami binasakan"],["أَنَّهُمْ","bahawa mereka"],["لَا","tidak"],["يَرْجِعُونَ","akan kembali"]]],"2579":["(Hingga) lafal Hattaa ini menunjukkan batas waktu bagi terlarangnya mereka untuk dapat hidup kembali (apabila dibukakan) dapat dibaca Futihat dan Futtihat (Yakjuj dan Makjuj) dapat dibaca Yakjuj wa Makjuj dan Yajuj wa Majuj, keduanya adalah nama bagi dua kabilah 'Ajam. Sebelum kalimat ini diperkirakan adanya Mudhaf, maksudnya tembok yang mengurung Yakjuj dan Makjuj; hal itu akan terjadi bila hari kiamat sudah dekat (dan mereka dari seluruh tempat-tempat yang tinggi) yakni dataran-dataran tinggi (turun dengan cepatnya) artinya, mereka turun dengan sangat cepat.",[["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["فُتِحَتْ","telah dibuka"],["يَأْجُوجُ","(untuk) Yajuj"],["وَمَأْجُوجُ","dan Majuj"],["وَهُم","dan mereka"],["مِّن","daripada"],["كُلِّ","setiap"],["حَدَبٍۢ","ketinggian"],["يَنسِلُونَ","turun"]]],"2580":["(Dan telah dekatlah kedatangan janji yang benar) yakni hari kiamat (maka tiba-tiba) kisah kenyataannya (terbelalaklah mata orang-orang yang kafir) pada hari tersebut disebabkan sangat ngeri melihatnya, seraya mengatakan, (\"Aduhai\") ya di sini menunjukkan makna penyesalan (celakalah kami) binasalah kami (sesungguhnya kami) sewaktu hidup di dunia (adalah dalam kelalaian tentang ini) tentang hari kiamat (bahkan kami adalah orang-orang yang zalim) yakni menganiaya diri kami sendiri, disebabkan kami mendustakan para Rasul.",[["وَٱقْتَرَبَ","Dan telah menghampiri"],["ٱلْوَعْدُ","janji itu"],["ٱلْحَقُّ","[yang] benar"],["فَإِذَا","maka lihatlah"],["هِىَ","[ia]"],["شَـٰخِصَةٌ","(sedang) merenung"],["أَبْصَـٰرُ","(mata)."],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["يَـٰوَيْلَنَا","Wahai celaka kami"],["قَدْ","Sesungguhnya"],["كُنَّا","kami telah"],["فِى","dalam"],["غَفْلَةٍۢ","kelalaian"],["مِّنْ","daripada"],["هَـٰذَا","ini"],["بَلْ","tidak"],["كُنَّا","kami"],["ظَـٰلِمِينَ","orang yang zalim"]]],"2581":["(Sesungguhnya kalian) hai penduduk Mekah (dan apa yang kalian sembah selain Allah) yaitu berhala-berhala (adalah makanan Jahanam) maksudnya sebagai bahan bakar (kalian pasti masuk ke dalamnya) pasti memasukinya.",[["إِنَّكُمْ","Sesungguhnya kamu"],["وَمَا","dan apa"],["تَعْبُدُونَ","kamu menyembah"],["مِن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["حَصَبُ","(adalah) kayu api"],["جَهَنَّمَ","(dari) Neraka"],["أَنتُمْ","kamu"],["لَهَا","kepadanya"],["وَٰرِدُونَ","akan datang"]]],"2582":["(Andaikata mereka itu) yakni berhala-berhala itu (adalah tuhan-tuhan) sebagaimana sangkaan kalian (tentulah mereka tidak masuk neraka) mereka tidak akan memasukinya. (Dan semuanya) yakni orang-orang yang menyembah berhala bersama berhala-berhala sesembahan mereka (akal kekal di dalamnya).",[["لَوْ","Jika"],["كَانَ","adalah"],["هَـٰٓؤُلَآءِ","ini"],["ءَالِهَةًۭ","tuhan"],["مَّا","tidak"],["وَرَدُوهَا ۖ","mereka (akan) datang kepadanya"],["وَكُلٌّۭ","Dan semua"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","akan kekal selama-lamanya"]]],"2583":["(Mereka) yakni keadaan para penyembah berhala itu (merintih di dalam api dan mereka di dalamnya tidak dapat mendengar) sesuatu pun karena gemuruhnya api Jahanam yang sangat kuat. Ayat ini diturunkan sewaktu Ibnu Zaba'ri mengatakan, bahwa penyembah Uzair, Al Masih dan para Malaikat, mereka semuanya dimasukkan ke dalam neraka, sebagaimana kisah yang telah disebutkan tadi.",[["لَهُمْ","Untuk mereka"],["فِيهَا","di dalamnya"],["زَفِيرٌۭ","(sedang) mengeluh"],["وَهُمْ","dan mereka"],["فِيهَا","di dalamnya"],["لَا","tidak"],["يَسْمَعُونَ","akan mendengar"]]],"2584":["(Sesungguhnya orang-orang yang telah ada untuk mereka ketetapan dari Kami) yakni kedudukan (yang baik) antara lain adalah para nabi yang telah disebutkan tadi (mereka itu dijauhkan dari neraka Jahanam).",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","mereka"],["سَبَقَتْ","telah keluar"],["لَهُم","bagi mereka"],["مِّنَّا","daripada Kami"],["ٱلْحُسْنَىٰٓ","yang baik"],["أُو۟لَـٰٓئِكَ","mereka"],["عَنْهَا","daripadanya"],["مُبْعَدُونَ","(akan) dikeluarkan jauh"]]],"2585":["(Mereka tidak mendengar sedikit pun suaranya) yakni suara gemuruh api neraka itu (dan mereka dalam menikmati apa yang diingini oleh mereka) yakni berupa nikmat surga (hidup kekal).",[["لَا","Tidak"],["يَسْمَعُونَ","mereka akan mendengar"],["حَسِيسَهَا ۖ","(sedikit) bunyinya"],["وَهُمْ","dan mereka"],["فِى","dalam"],["مَا","apa"],["ٱشْتَهَتْ","keinginan"],["أَنفُسُهُمْ","jiwa mereka"],["خَـٰلِدُونَ","akan kekal selama-lamanya"]]],"2586":["(Mereka tidak disusahkan oleh kedahsyatan yang besar) yaitu perintah yang menyuruh hamba Allah dimasukkan ke dalam neraka (dan mereka disambut) dijemput (oleh para Malaikat) sewaktu mereka keluar dari kuburannya masing-masing, seraya berkata kepada mereka, (\"Inilah hari kalian yang telah dijanjikan kepada kalian\") sewaktu kalian hidup di dunia.",[["لَا","Tidak"],["يَحْزُنُهُمُ","akan menyedihkan mereka"],["ٱلْفَزَعُ","keganasan itu"],["ٱلْأَكْبَرُ","[yang] terhebat"],["وَتَتَلَقَّىٰهُمُ","dan akan bertemu dengan mereka"],["ٱلْمَلَـٰٓئِكَةُ","para Malaikat"],["هَـٰذَا","Ini"],["يَوْمُكُمُ","(ialah) hari kamu"],["ٱلَّذِى","yang"],["كُنتُمْ","kamu dahulu"],["تُوعَدُونَ","dijanjikan"]]],"2587":["(Yaitu pada hari) ia dinashabkan oleh lafal Udzkur yang diperkirakan sebelumnya (Kami gulung langit seperti menggulungnya malaikat Sijil) lafal As Sijilli ini adalah nama malaikat pencatat amal perbuatan (terhadap kitab) catatan amal perbuatan anak Adam, sewaktu anak Adam yang bersangkutan mati. Huruf Lam pada lafal Lil Kutubi adalah Zaidah atau tambahan. Atau yang dimaksud dengan As Sijilli adalah lembaran-lembaran, sedangkan yang dimaksud Al Kitab adalah barang yang ditulis atau kertas dan huruf Lamnya bermakna 'Ala. Artinya: sebagaimana tergulungnya lembaran-lembaran kertas. Dan menurut qiraat yang lain lafal Lil Kitabi dibaca Lil Kutubi dalam bentuk jamak, yakni kitab-kitab atau kertas-kertas. (Sebagaimana Kami telah memulai penciptaan pertama) yakni mulai dari alam ketiadaan (begitulah Kami akan mengulanginya) yakni sesudah penciptaan itu ditiadakan. Huruf Kaf di sini berta'alluq kepada lafal Nu'iiduhu dan Dhamir Hu lafal Nu'iiduhu kembali kepada lafal Awwal dan huruf Ma pada lafal Kama adalah Mashdariyah (Itulah suatu janji yang pasti Kami tepati) Lafal Wa'dan dinashabkan oleh lafal Wa'dunaa yang keberadaannya diperkirakan pada sebelumnya, sedangkan lafal Wa'dan ini berfungsi mengukuhkan makna dari lafal yang diperkirakan sebelumnya (sesungguhnya Kamilah yang akan melaksanakannya) yaitu melaksanakan janji yang telah Kami tetapkan.",[["يَوْمَ","(The) Hari"],["نَطْوِى","Kami akan lipat"],["ٱلسَّمَآءَ","syurga itu"],["كَطَىِّ","seperti (yang) lipatan"],["ٱلسِّجِلِّ","(dari) sebuah skrol"],["لِلْكُتُبِ ۚ","untuk rekod"],["كَمَا","Sebagai"],["بَدَأْنَآ","Kami mula"],["أَوَّلَ","(yang) pertama"],["خَلْقٍۢ","ciptaan"],["نُّعِيدُهُۥ ۚ","Kami akan mengulanginya"],["وَعْدًا","sebuah janji"],["عَلَيْنَآ ۚ","atas Kami"],["إِنَّا","Sesungguhnya Kami"],["كُنَّا","Kami"],["فَـٰعِلِينَ","(para) Pelaku"]]],"2588":["(Dan sungguh telah Kami tulis di dalam Zabur) yakni kitab Zabur yang telah diturunkan oleh Allah (sesudah adanya peringatan) yang dimaksud adalah Ummul Kitab atau Alquran yang telah ada di sisi Allah, yakni di Lohmahfuz (bahwasanya bumi ini) yakni bumi surga (diwariskan kepada hamba-hamba-Ku yang saleh) yakni siapa saja di antara hamba-hamba-Ku yang saleh.",[["وَلَقَدْ","Dan sesungguhnya"],["كَتَبْنَا","Kami telah menulis"],["فِى","dalam"],["ٱلزَّبُورِ","Kitab Suci"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["ٱلذِّكْرِ","sebutan itu"],["أَنَّ","bahawa"],["ٱلْأَرْضَ","bumi"],["يَرِثُهَا","akan mewarisinya"],["عِبَادِىَ","budak-budak aku"],["ٱلصَّـٰلِحُونَ","orang yang soleh"]]],"2589":["(Sesungguhnya apa yang disebutkan di dalam kitab ini) yakni Alquran (benar-benar menjadi bekal) yakni kecukupan untuk masuk surga (bagi kaum yang menyembah Allah) yakni bagi mereka yang mengamalkannya.",[["إِنَّ","Sesungguhnya"],["فِى","dalam"],["هَـٰذَا","ini"],["لَبَلَـٰغًۭا","sesungguhnya adalah satu Mesej"],["لِّقَوْمٍ","bagi kaum"],["عَـٰبِدِينَ","ahli ibadah"]]],"2590":["(Dan tiadalah Kami mengutus kamu) hai Muhammad! (melainkan untuk menjadi rahmat) yakni merupakan rahmat (bagi semesta alam) manusia dan jin melalui kerasulanmu.",[["وَمَآ","Dan tidak"],["أَرْسَلْنَـٰكَ","Kami telah menghantar kamu"],["إِلَّا","tetapi"],["رَحْمَةًۭ","(sebagai) rahmat"],["لِّلْعَـٰلَمِينَ","untuk dunia"]]],"2591":["(Katakanlah, \"Sesungguhnya yang diwahyukan kepadaku adalah bahwasanya Tuhan kalian adalah Tuhan Yang Maha Esa) tiada diwahyukan kepadaku sehubungan dengan perkara Tuhan, melainkan keesaan-Nya (maka hendaklah kalian berserah diri) taat kepada apa yang diwahyukan kepadaku, yaitu mentauhidkan Tuhan. Istifham di sini mengandung makna perintah.",[["قُلْ","Katakanlah"],["إِنَّمَا","Hanya"],["يُوحَىٰٓ","ia didedahkan"],["إِلَىَّ","kepada aku"],["أَنَّمَآ","bahawa"],["إِلَـٰهُكُمْ","tuhan kamu"],["إِلَـٰهٌۭ","(ialah) Tuhan"],["وَٰحِدٌۭ ۖ","satu"],["فَهَلْ","begitu juga"],["أَنتُم","kamu"],["مُّسْلِمُونَ","berserah diri (kepadaNya)"]]],"2592":["(Jika mereka berpaling) dari hal tersebut (maka katakanlah, \"Aku telah menyerukan kepada kalian) maksudnya telah memberitahukan kepada kalian untuk berperang (dalam keadaan sama) lafal 'Alaa Sawaa-in ini menjadi Hal dari Fa'il dan Maf'ul. Maksudnya, antara kami dan kalian sama-sama mengetahui maklumat ini, aku tidak memaksakan kalian untuk berperang, tetapi kalian sendirilah yang mengajaknya, maka bersiap-siaplah kalian (dan tidaklah) yakni tiadalah (aku mengetahui, apakah yang diancamkan kepada kalian itu sudah dekat atau masih jauh\") maksudnya azab atau kiamat yang juga di dalamnya mengandung azab, akan tetapi sesungguhnya yang mengetahui hal itu hanyalah Allah semata.",[["فَإِن","Tetapi jika"],["تَوَلَّوْا۟","mereka berpaling"],["فَقُلْ","kemudian berkata"],["ءَاذَنتُكُمْ","Aku (telah) mengumumkan kepada kamu"],["عَلَىٰ","sama-sama"],["سَوَآءٍۢ ۖ","sama-sama"],["وَإِنْ","Dan tidak"],["أَدْرِىٓ","aku tahu"],["أَقَرِيبٌ","sama ada dekat"],["أَم","atau"],["بَعِيدٌۭ","jauh"],["مَّا","apa"],["تُوعَدُونَ","kamu dijanjikan"]]],"2593":["(Sesungguhnya Dia) Allah swt. (mengetahui perkataan yang terang-terangan) dan juga perbuatan kalian dan orang-orang selain kalian (dan Dia mengetahui apa yang kalian rahasiakan) yang dirahasiakan kalian dan selain kalian.",[["إِنَّهُۥ","Sesungguhnya Dia"],["يَعْلَمُ","mengetahui"],["ٱلْجَهْرَ","yang diisytiharkan"],["مِنَ","[daripada]"],["ٱلْقَوْلِ","[the] ucapan"],["وَيَعْلَمُ","dan Dia mengetahui"],["مَا","apa"],["تَكْتُمُونَ","kamu sembunyikan"]]],"2594":["(Dan tidaklah) (aku mengetahui, barangkali hal itu) apa yang telah aku beritahukan kepada kalian dan belum diketahui saatnya (sebagai cobaan) ujian (bagi kalian) supaya dapat dilihat, apakah yang diperbuat oleh kalian dan kesenangan) yakni bersenang-senang (sampai kepada suatu waktu) maksudnya sampai habisnya umur kalian. Pengertian ayat ini hanya bersifat kebalikan daripada hal yang diharapkan dengan memakai ungkapan La'alla, akan tetapi bukan subjek daripada harapan tersebut.",[["وَإِنْ","Dan tidak"],["أَدْرِى","aku tahu"],["لَعَلَّهُۥ","mungkin boleh jadi"],["فِتْنَةٌۭ","perbicaraan"],["لَّكُمْ","bagi kamu"],["وَمَتَـٰعٌ","dan satu kenikmatan"],["إِلَىٰ","bagi"],["حِينٍۢ","suatu masa"]]],"2595":["(Muhammad berkata) qaala menurut suatu qiraat dibaca Qul, yakni katakanlah hai Muhammad, (\"Ya Rabbku! Berilah keputusan) antara aku dan orang-orang yang mendustakan aku (dengan adil) yakni azab bagi mereka atau pertolongan-Mu di dalam menghadapi mereka. Maka akhirnya mereka diazab di dalam perang Badar, Uhud, Hunain, Ahzab dan Khandaq, Nabi saw. mendapat kemenangan atas mereka. (Dan Rabb kami ialah Tuhan Yang Maha Pemurah lagi Yang dimohonkan pertolongan-Nya terhadap apa yang kalian katakan itu\") kedustaan perkataan kalian kepada Allah: kalian telah mengatakan-Nya, bahwa Allah mempunyai anak. Perkataan kalian kepadaku, bahwa aku ini adalah seorang penyihir. Perkataan kalian terhadap Alquran, bahwa ia adalah syair semata.",[["قَـٰلَ","Dia berkata"],["رَبِّ","Tuhanku"],["ٱحْكُم","hakim"],["بِٱلْحَقِّ ۗ","dalam kebenaran"],["وَرَبُّنَا","Dan Tuhan kami"],["ٱلرَّحْمَـٰنُ","(adalah) Yang Maha Pemurah"],["ٱلْمُسْتَعَانُ","yang dipohon pertolongan-Nya"],["عَلَىٰ","terhadap"],["مَا","apa"],["تَصِفُونَ","kamu sifatkan"]]],"2596":["(Hai manusia!) yakni penduduk Mekah dan selainnya (Bertakwalah kepada Rabb kalian) takutlah kalian akan azab-Nya, yaitu dengan taat kepada-Nya (sesungguhnya keguncangan hari kiamat itu) yakni saat gempa yang amat dahsyat menimpa bumi, lalu disusul dengan terbitnya matahari dari tempat terbenamnya, itulah pertanda kiamat telah di ambang pintu (adalah suatu kejadian yang sangat besar) sangat mengejutkan manusia hal ini merupakan semacam azab.",[["يَـٰٓأَيُّهَا","Wahai umat manusia"],["ٱلنَّاسُ","Wahai umat manusia"],["ٱتَّقُوا۟","Takut"],["رَبَّكُمْ ۚ","Tuhanmu"],["إِنَّ","Sesungguhnya"],["زَلْزَلَةَ","(the) sawan"],["ٱلسَّاعَةِ","(dari) hari kiamat"],["شَىْءٌ","(adalah) sesuatu"],["عَظِيمٌۭ","yang besar"]]],"2597":["(Pada hari kalian melihat keguncangan itu lalailah) disebabkannya (semua wanita yang menyusui anaknya) yang sebenarnya (dari anak yang disusukannya) ia melupakannya (dan gugurlah dari semua wanita yang sedang mengandung) yakni sedang hamil (kandungannya dan kamu lihat manusia dalam keadaan mabuk) disebabkan tercekam perasaan takut yang amat hebat (padahal sebenarnya mereka tidak mabuk) disebabkan minuman keras (akan tetapi azab Allah itu sangat keras) maka mereka takut kepada azab itu.",[["يَوْمَ","(The) Hari"],["تَرَوْنَهَا","kamu akan melihatnya"],["تَذْهَلُ","akan lupa"],["كُلُّ","setiap"],["مُرْضِعَةٍ","ibu menyusu"],["عَمَّآ","itu yang"],["أَرْضَعَتْ","dia menyusu"],["وَتَضَعُ","dan akan menyampaikan"],["كُلُّ","setiap"],["ذَاتِ","wanita hamil"],["حَمْلٍ","wanita hamil"],["حَمْلَهَا","beban dia"],["وَتَرَى","dan kamu akan melihat"],["ٱلنَّاسَ","[the] manusia"],["سُكَـٰرَىٰ","mabuk"],["وَمَا","manakala tidak"],["هُم","mereka"],["بِسُكَـٰرَىٰ","(sedang) mabuk"],["وَلَـٰكِنَّ","tetapi"],["عَذَابَ","azab"],["ٱللَّهِ","(milik) Allah"],["شَدِيدٌۭ","(akan) teruk"]]],"2598":["Ayat berikut ini diturunkan berkenaan dengan Nadhr bin Harits dan para pengikutnya. (Di antara manusia ada orang yang membantah tentang Allah tanpa ilmu pengetahuan) mereka mengatakan, bahwa para Malaikat itu adalah anak-anak perempuan Allah. Alquran adalah dongengan orang-orang dahulu dan mereka mengingkari adanya hari berbangkit serta dihidupkan-Nya kembali manusia yang telah menjadi tanah (dan mengikuti) di dalam bantahannya itu (setiap setan yang sangat jahat) yaitu sangat membangkang.",[["وَمِنَ","Dan antara"],["ٱلنَّاسِ","umat manusia"],["مَن","(adakah dia) siapa"],["يُجَـٰدِلُ","pertikaian"],["فِى","tentang"],["ٱللَّهِ","Allah"],["بِغَيْرِ","tanpa"],["عِلْمٍۢ","pengetahuan"],["وَيَتَّبِعُ","dan mengikuti"],["كُلَّ","setiap"],["شَيْطَـٰنٍۢ","syaitan"],["مَّرِيدٍۢ","memberontak"]]],"2599":["(Yang telah ditetapkan terhadap setan itu) telah diputuskan terhadapnya (bahwa barang siapa yang berkawan dengan dia) mengikutinya (tentu dia akan menyesatkannya dan membawanya) menjerumuskannya (ke azab neraka) yang apinya berkobar-kobar.",[["كُتِبَ","Ia telah diputuskan"],["عَلَيْهِ","baginya"],["أَنَّهُۥ","bahawa dia"],["مَن","yang"],["تَوَلَّاهُ","berkawan dengan dia"],["فَأَنَّهُۥ","maka sesungguhnya, dia"],["يُضِلُّهُۥ","akan menyesatkan dia"],["وَيَهْدِيهِ","dan akan membimbingnya"],["إِلَىٰ","kepada"],["عَذَابِ","azab"],["ٱلسَّعِيرِ","(dari) Api"]]],"2600":["(Hai manusia) yakni penduduk Mekah (jika kalian dalam keraguan) kalian meragukan (tentang hari berbangkit, sesungguhnya Kami telah menciptakan kalian) bapak moyang kalian, yaitu Adam (dari tanah, kemudian) Kami ciptakan anak cucunya (dari setetes nuthfah) air mani (kemudian dari segumpal darah) darah yang kental (kemudian dari segumpal daging) daging yang besarnya sekepal tangan (yang sempurna kejadiannya) telah diberi bentuk berupa makhluk yang sempurna (dan yang tidak sempurna) masih belum sempurna bentuknya (agar Kami jelaskan kepada kalian) kemahasempurnaan kekuasaan Kami, yaitu supaya kalian dapat mengambil kesimpulan daripadanya, bahwa Allah yang memulai penciptaan dapat mengembalikan ciptaan itu kepada asalnya. (Dan Kami tetapkan) kalimat ayat ini merupakan kalimat baru (di dalam rahim, apa yang Kami kehendaki sampai waktu yang sudah ditentukan) hingga ia keluar (kemudian Kami keluarkan kalian) dari perut ibu-ibu kalian (sebagai bayi) lafal Thiflan sekalipun berbentuk tunggal tetapi makna yang dimaksud adalah jamak (kemudian) Kami memberi kalian umur secara berangsur-angsur (hingga sampailah kalian kepada kedewasaan) dewasa dan kuat, yaitu di antara umur tiga puluh tahun sampai empat puluh tahun (dan di antara kalian ada yang diwafatkan) yakni mati sebelum mencapai usia dewasa (dan ada pula di antara kalian yang dipanjangkan umurnya sampai pikun) amat tua sehingga menjadi pikun (supaya dia tidak mengetahui lagi sesuatu pun yang dahulunya telah diketahuinya). Sehubungan dengan hal ini Ikrimah mengatakan, \"Barang siapa yang biasa membaca Alquran, niscaya ia tidak akan mengalami nasib yang demikian itu, yakni terlalu tua dan pikun.\" (Dan kalian lihat bumi ini kering) gersang (kemudian apabila telah Kami turunkan air atasnya, hiduplah bumi itu) menjadi hidup (dan suburlah ia) hidup dengan suburnya (serta dapat menumbuhkan) huruf Min adalah huruf Zaidah (berbagai macam tumbuh-tumbuhan) beraneka ragam tumbuhan (yang indah) yakni yang baik.",[["يَـٰٓأَيُّهَا","Wahai umat manusia"],["ٱلنَّاسُ","Wahai umat manusia"],["إِن","Jika"],["كُنتُمْ","kamu"],["فِى","dalam"],["رَيْبٍۢ","keraguan"],["مِّنَ","tentang"],["ٱلْبَعْثِ","kebangkitan"],["فَإِنَّا","maka sesungguhnya Kami"],["خَلَقْنَـٰكُم","Kami mencipta kamu"],["مِّن","daripada"],["تُرَابٍۢ","habuk"],["ثُمَّ","kemudian"],["مِن","daripada"],["نُّطْفَةٍۢ","titisan air mani"],["ثُمَّ","kemudian"],["مِنْ","daripada"],["عَلَقَةٍۢ","bahan yang melekat"],["ثُمَّ","kemudian"],["مِن","daripada"],["مُّضْغَةٍۢ","ketulan embrio"],["مُّخَلَّقَةٍۢ","terbentuk"],["وَغَيْرِ","dan tidak berbentuk"],["مُخَلَّقَةٍۢ","dan tidak berbentuk"],["لِّنُبَيِّنَ","supaya Kami jelaskan"],["لَكُمْ ۚ","kepada kamu"],["وَنُقِرُّ","Dan Kami kekalkan"],["فِى","dalam"],["ٱلْأَرْحَامِ","rahim"],["مَا","apa"],["نَشَآءُ","Kami akan"],["إِلَىٰٓ","bagi"],["أَجَلٍۢ","satu istilah"],["مُّسَمًّۭى","dilantik"],["ثُمَّ","kemudian"],["نُخْرِجُكُمْ","Kami bawa kamu keluar"],["طِفْلًۭا","(sebagai) kanak-kanak"],["ثُمَّ","[kemudian]"],["لِتَبْلُغُوٓا۟","yang boleh kamu capai"],["أَشُدَّكُمْ ۖ","kematangan [kamu]"],["وَمِنكُم","Dan di antara kamu"],["مَّن","(adakah dia) siapa"],["يُتَوَفَّىٰ","mati"],["وَمِنكُم","dan di antara kamu"],["مَّن","(adakah dia) siapa"],["يُرَدُّ","dikembalikan"],["إِلَىٰٓ","kepada"],["أَرْذَلِ","yang paling hina"],["ٱلْعُمُرِ","umur"],["لِكَيْلَا","supaya tidak"],["يَعْلَمَ","dia tahu"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["عِلْمٍۢ","setelah mengetahui"],["شَيْـًۭٔا ۚ","sesuatu"],["وَتَرَى","Dan kamu lihat"],["ٱلْأَرْضَ","bumi"],["هَامِدَةًۭ","mandul"],["فَإِذَآ","kemudian apabila"],["أَنزَلْنَا","Kami hantar turun"],["عَلَيْهَا","di atasnya"],["ٱلْمَآءَ","air"],["ٱهْتَزَّتْ","ia akan dikacau"],["وَرَبَتْ","dan ia membengkak"],["وَأَنۢبَتَتْ","dan berkembang"],["مِن","daripada"],["كُلِّ","setiap"],["زَوْجٍۭ","baik hati"],["بَهِيجٍۢ","cantik"]]],"2601":["(Yang demikian itu) yakni hal-hal yang telah disebutkan itu mulai dari permulaan kejadian manusia hingga dihidupkannya bumi menjadi subur (karena sesungguhnya) disebabkan bahwa (Allah Dialah yang hak) Yang Tetap dan Abadi (dan sesungguhnya Dialah yang menghidupkan segala yang mati dan sesungguhnya Allah Maha Kuasa atas segala sesuatu).",[["ذَٰلِكَ","Itu"],["بِأَنَّ","(adalah) kerana"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلْحَقُّ","(adalah) Kebenaran"],["وَأَنَّهُۥ","Dan bahawa Dia"],["يُحْىِ","[Dia] memberi kehidupan"],["ٱلْمَوْتَىٰ","(kepada) orang mati"],["وَأَنَّهُۥ","dan bahawa Dia"],["عَلَىٰ","(sudah) tamat"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"]]],"2602":["(Dan sesungguhnya hari kiamat itu pastilah datang, tak ada keraguan) tidak diragukan lagi (padanya; dan bahwasanya Allah membangkitkan semua orang di dalam kubur).",[["وَأَنَّ","Dan bahawa"],["ٱلسَّاعَةَ","Jam itu"],["ءَاتِيَةٌۭ","akan datang"],["لَّا","(ada) tidak"],["رَيْبَ","keraguan"],["فِيهَا","mengenainya"],["وَأَنَّ","dan bahawa"],["ٱللَّهَ","Allah"],["يَبْعَثُ","akan dibangkitkan"],["مَن","(mereka) yang"],["فِى","(ada) dalam"],["ٱلْقُبُورِ","kubur"]]],"2603":["Ayat berikut ini diturunkan berkenaan dengan Abu Jahal, yaitu: (Dan di antara manusia ada orang-orang yang membantah tentang Allah tanpa ilmu pengetahuan dan tanpa petunjuk) yang menjadi pegangannya (dan tanpa kitab yang bercahaya) kitab yang menjadi pegangannya dan yang dapat menunjukinya.",[["وَمِنَ","Dan antara"],["ٱلنَّاسِ","manusia"],["مَن","(adakah dia) siapa"],["يُجَـٰدِلُ","pertikaian"],["فِى","tentang"],["ٱللَّهِ","Allah"],["بِغَيْرِ","tanpa"],["عِلْمٍۢ","sebarang pengetahuan"],["وَلَا","dan bukan"],["هُدًۭى","sebarang bimbingan"],["وَلَا","dan bukan"],["كِتَـٰبٍۢ","sebuah Buku"],["مُّنِيرٍۢ","pencerahan"]]],"2604":["(Dengan memalingkan lambungnya) Lafal ayat ini berkedudukan menjadi Hal atau keterangan keadaan, maksudnya orang yang membantah itu memalingkan lehernya dengan penuh kesombongan karena tidak mau beriman. Pengertian berpaling di sini adalah baik ke kanan maupun ke kiri sama saja (untuk menyesatkan) dapat dibaca Liyadhilla dan Liyudhilla, untuk menyesatkan manusia (dari jalan Allah) yakni dari agama-Nya. (Ia mendapat kehinaan di dunia) azab di dunia, akhirnya ia terbunuh dalam perang Badar (dan di hari kiamat Kami merasakan kepadanya azab neraka yang membakar) ia akan dibakar oleh api neraka, lalu dikatakan kepadanya,",[["ثَانِىَ","Memusing"],["عِطْفِهِۦ","lehernya"],["لِيُضِلَّ","untuk mengelirukan"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ ۖ","(milik) Allah"],["لَهُۥ","Untuk dia"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["خِزْىٌۭ ۖ","(adalah) aib"],["وَنُذِيقُهُۥ","dan Kami akan rasakan dia"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","(dari) Kebangkitan"],["عَذَابَ","azab"],["ٱلْحَرِيقِ","(dari) Api yang Menyala"]]],"2605":["(\"Yang demikian itu, adalah disebabkan perbuatan yang dikerjakan oleh kedua tanganmu dahulu) yakni perbuatan kamu dahulu. Diungkapkan demikian mengingat, bahwa kebanyakan pekerjaan itu dilakukan oleh kedua tangan (dan sesungguhnya Allah sekali-kali bukanlah penganiaya) suka menganiaya (hamba-hamba-Nya\") dengan mengazab mereka tanpa dosa.",[["ذَٰلِكَ","Itu"],["بِمَا","(adalah) untuk apa"],["قَدَّمَتْ","telah menghantar"],["يَدَاكَ","tangan kamu"],["وَأَنَّ","dan bahawa"],["ٱللَّهَ","Allah"],["لَيْسَ","bukan"],["بِظَلَّـٰمٍۢ","tidak adil"],["لِّلْعَبِيدِ","kepada hamba-hamba-Nya"]]],"2606":["(Dan di antara manusia ada orang yang menyembah Allah dengan berada di tepi) ia ragu di dalam ibadahnya itu. Keadaannya diserupakan dengan seseorang yang berada di tepi bukit, yakni ia tidak dapat berdiri dengan tetap dan mantap (maka jika ia memperoleh kebaikan) maksudnya kesehatan dan kesejahteraan pada diri dan harta bendanya (tetaplah ia dalam keadaan itu dan jika ia ditimpa oleh suatu bencana) cobaan pada hartanya dan penyakit pada dirinya (berbaliklah ia ke belakang) ia kembali menjadi kafir. (Rugilah ia di dunia) disebabkan terlepasnya semua apa yang ia harapkan dari dunia (dan di akhirat) disebabkan kekafirannya itu. (Yang demikian itu adalah kerugian yang nyata) jelas ruginya.",[["وَمِنَ","Dan antara"],["ٱلنَّاسِ","umat manusia"],["مَن","(adakah dia) siapa"],["يَعْبُدُ","beribadat"],["ٱللَّهَ","Allah"],["عَلَىٰ","pada"],["حَرْفٍۢ ۖ","satu tepi"],["فَإِنْ","Dan jika"],["أَصَابَهُۥ","menimpanya"],["خَيْرٌ","kebaikan"],["ٱطْمَأَنَّ","dia redha"],["بِهِۦ ۖ","dengannya"],["وَإِنْ","dan jika"],["أَصَابَتْهُ","menimpanya"],["فِتْنَةٌ","perbicaraan"],["ٱنقَلَبَ","dia berpaling"],["عَلَىٰ","pada"],["وَجْهِهِۦ","mukanya"],["خَسِرَ","Dia telah kalah"],["ٱلدُّنْيَا","dunia"],["وَٱلْـَٔاخِرَةَ ۚ","dan akhirat"],["ذَٰلِكَ","Itu"],["هُوَ","[ia]"],["ٱلْخُسْرَانُ","(ialah) kerugian"],["ٱلْمُبِينُ","yang nyata"]]],"2607":["(Ia menyeru) menyembah (selain Allah) yakni berhala-berhala (sesuatu yang tidak dapat memberi mudarat kepada dirinya) jika ia tidak menyembahnya (dan pula tidak dapat memberi manfaat kepada dirinya) jika ia menyembahnya. (Yang demikian itu) penyembahan itu (adalah kesesatan yang jauh) sekali dari kebenaran.",[["يَدْعُوا۟","Dia memanggil"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["مَا","apa"],["لَا","tidak"],["يَضُرُّهُۥ","memudaratkan dia"],["وَمَا","dan apa"],["لَا","tidak"],["يَنفَعُهُۥ ۚ","memberi manfaat kepadanya"],["ذَٰلِكَ","Itu"],["هُوَ","[ia]"],["ٱلضَّلَـٰلُ","(ialah) yang sesat"],["ٱلْبَعِيدُ","jauh sekali"]]],"2608":["(Ia menyeru sesuatu) huruf Lam adalah Zaidah (yang sebenarnya mudaratnya) jika ia menyembahnya (lebih dekat dari manfaatnya) jika menurut khayalannya ia dapat memberikan manfaat. (Sesungguhnya sejahat-jahat penolong) adalah sesembahan itu (dan sejahat-jahat kawan) adalah dia pula. Sesudah Allah swt. menyebutkan tentang orang-orang yang ragu dengan akibatnya yaitu kerugian, kemudian Allah mengiringinya dengan kisah mengenai orang-orang Mukmin dengan akibatnya, yaitu mendapatkan pahala dari-Nya. Untuk itu Allah swt. berfirman:",[["يَدْعُوا۟","Dia memanggil"],["لَمَن","(satu) siapa"],["ضَرُّهُۥٓ","kemudaratannya"],["أَقْرَبُ","(adalah) lebih dekat"],["مِن","daripada"],["نَّفْعِهِۦ ۚ","faedahnya"],["لَبِئْسَ","Sudah tentu, kejahatan"],["ٱلْمَوْلَىٰ","pelindung"],["وَلَبِئْسَ","dan sesungguhnya kejahatan"],["ٱلْعَشِيرُ","kawan"]]],"2609":["(Sesungguhnya Allah memasukkan orang-orang yang beriman dan mengerjakan amal saleh) amal fardu dan sunah semuanya (ke dalam surga-surga yang di bawahnya mengalir sungai-sungai. Sesungguhnya Allah berbuat apa saja yang Dia kehendaki) termasuk memuliakan orang yang taat kepada-Nya dan menghinakan orang yang durhaka kepada-Nya.",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُدْخِلُ","akan mengaku"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","perbuatan yang soleh"],["جَنَّـٰتٍۢ","(ke) Taman"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ ۚ","sungai-sungai"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يَفْعَلُ","tidak"],["مَا","apa"],["يُرِيدُ","Dia berniat"]]],"2610":["(Barang siapa yang menyangka bahwa Allah sekali-kali tiada menolongnya) menolong Nabi Muhammad saw. (di dunia dan akhirat, maka hendaklah ia merentangkan tali) tambang (ke langit) yang dimaksud adalah atap rumahnya, kemudian tali itu diikatkan ke atap rumah dan ke lehernya (kemudian hendaklah ia memutuskan tali itu) yakni mencekik dirinya dengan tali itu, maksudnya menggantung diri. Demikianlah sebagaimana yang disebutkan di dalam hadis-hadis sahih (kemudian hendaklah ia pikirkan, apakah tipu dayanya itu sungguh dapat melenyapkan) dalam hal tidak ditolongnya nabi (apa yang menyakitkan hatinya) apa yang membuat ia sakit hati. Maksudnya, hendaklah ia tercekik oleh kejengkelannya, karena sesungguhnya Allah pasti akan menolong nabi-Nya.",[["مَن","Siapa pun"],["كَانَ","[adalah]"],["يَظُنُّ","berfikir"],["أَن","bahawa"],["لَّن","tidak"],["يَنصُرَهُ","Allah akan menolongnya"],["ٱللَّهُ","Allah akan menolongnya"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["وَٱلْـَٔاخِرَةِ","dan akhirat"],["فَلْيَمْدُدْ","maka hendaklah dia memanjangkan"],["بِسَبَبٍ","seutas tali"],["إِلَى","kepada"],["ٱلسَّمَآءِ","langit"],["ثُمَّ","kemudian"],["لْيَقْطَعْ","biar dia potong"],["فَلْيَنظُرْ","kemudian biarkan dia melihat"],["هَلْ","sama ada"],["يُذْهِبَنَّ","akan mengeluarkan"],["كَيْدُهُۥ","rancangannya"],["مَا","apa"],["يَغِيظُ","marah"]]],"2611":["(Dan demikianlah) sebagaimana Kami turunkan ayat tadi (Kami telah menurunkan dia) ayat-ayat Alquran selanjutnya (yang merupakan ayat-ayat yang nyata) lafal Bayyinatin berkedudukan menjadi Hal, artinya ayat-ayat yang jelas (dan bahwasanya Allah memberikan petunjuk kepada siapa yang Dia kehendaki) untuk mendapatkan petunjuk-Nya; bagian ayat ini di'athafkan kepada dhamir Ha yang terdapat pada lafal Anzalnaahu.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["أَنزَلْنَـٰهُ","Kami menurunkannya"],["ءَايَـٰتٍۭ","(as) Ayat yang jelas"],["بَيِّنَـٰتٍۢ","(as) Ayat yang jelas"],["وَأَنَّ","dan bahawa"],["ٱللَّهَ","Allah"],["يَهْدِى","panduan"],["مَن","yang"],["يُرِيدُ","Dia berniat"]]],"2612":["(Sesungguhnya orang-orang yang beriman, orang-orang Yahudi) mereka adalah pemeluk agama Yahudi (orang-orang Shabi'in) salah satu sekte dari orang-orang Yahudi (orang-orang Nasrani, orang-orang Majusi dan orang-orang Musyrik, Allah akan memberi keputusan di antara mereka pada hari kiamat) yaitu dengan memasukkan orang-orang yang beriman ke dalam surga dan mencampakkan orang-orang selain mereka ke dalam neraka. (Sesungguhnya Allah terhadap segala sesuatu) yang diperbuat mereka (Maha Menyaksikan) mengetahuinya secara nyata.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","telah beriman"],["وَٱلَّذِينَ","dan orang yang"],["هَادُوا۟","adalah orang Yahudi"],["وَٱلصَّـٰبِـِٔينَ","dan golongan Sabian"],["وَٱلنَّصَـٰرَىٰ","dan orang Kristian"],["وَٱلْمَجُوسَ","dan orang Majusi"],["وَٱلَّذِينَ","dan orang yang"],["أَشْرَكُوٓا۟","(adalah) orang musyrik"],["إِنَّ","sesungguhnya"],["ٱللَّهَ","Allah"],["يَفْصِلُ","akan menilai"],["بَيْنَهُمْ","antara mereka"],["يَوْمَ","(pada) hari itu"],["ٱلْقِيَـٰمَةِ ۚ","Kiamat"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلَىٰ","atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["شَهِيدٌ","(adalah) seorang Saksi"]]],"2613":["(Apakah kamu tiada melihat) tiada mengetahui (bahwa kepada Allah bersujud makhluk yang ada di langit dan makhluk yang ada di bumi dan matahari, bulan, bintang-bintang, gunung-gunung, pohon-pohon dan hewan-hewan yang melata) semuanya tunduk dan patuh menuruti apa yang dikehendaki-Nya (dan sebagian besar daripada manusia?) adalah orang-orang Mukmin, yaitu dengan bertambah perasaan rendah diri dalam sujud salat mereka. (Dan banyak di antara manusia yang telah ditetapkan azab atasnya) mereka adalah orang-orang kafir, karena mereka membangkang tidak mau bersujud, sedangkan sujud itu adalah pertanda iman. (Dan barang siapa yang dihinakan Allah) disengsarakan-Nya (maka tidak seorang pun yang memuliakannya) yang akan membahagiakannya. (Sesungguhnya Allah berbuat apa yang Dia kehendaki) seperti menghinakan dan memuliakan.",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["أَنَّ","bahawa"],["ٱللَّهَ","(kepada) Allah"],["يَسْجُدُ","sujud"],["لَهُۥ","kepada-Nya"],["مَن","sesiapa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَن","dan sesiapa"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["وَٱلشَّمْسُ","dan matahari"],["وَٱلْقَمَرُ","dan bulan"],["وَٱلنُّجُومُ","dan bintang"],["وَٱلْجِبَالُ","dan pergunungan"],["وَٱلشَّجَرُ","dan pokok-pokok"],["وَٱلدَّوَآبُّ","dan makhluk yang bergerak"],["وَكَثِيرٌۭ","dan banyak"],["مِّنَ","daripada"],["ٱلنَّاسِ ۖ","manusia"],["وَكَثِيرٌ","Tetapi ramai"],["حَقَّ","(adalah) wajar"],["عَلَيْهِ","pada dia"],["ٱلْعَذَابُ ۗ","azab"],["وَمَن","Dan sesiapa"],["يُهِنِ","Allah menghinakan"],["ٱللَّهُ","Allah menghinakan"],["فَمَا","maka tidak"],["لَهُۥ","baginya"],["مِن","sebarang"],["مُّكْرِمٍ ۚ","pemberi kehormatan"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يَفْعَلُ","tidak"],["مَا","apa"],["يَشَآءُ ۩","Dia kehendaki"]]],"2614":["(Inilah dua golongan yang bertengkar) yaitu golongan orang-orang Mukmin di satu pihak dan di pihak lain lima golongan orang-orang kafir yang disebutkan dalam ayat 17=Lafal Khashmun ini dapat diartikan untuk tunggal dan jamak (mereka saling bertengkar mengenai Rabb mereka) dalam urusan agama mereka. (Maka orang-orang kafir akan dibuatkan untuk mereka pakaian-pakaian dari api neraka) yang kemudian mereka pakai, maksudnya mereka diliputi oleh api neraka. (Disiramkan air yang sedang mendidih ke atas kepala mereka) yaitu air yang sangat panas.",[["۞ هَـٰذَانِ","dua ini"],["خَصْمَانِ","pihak lawan"],["ٱخْتَصَمُوا۟","pertikaian"],["فِى","tentang"],["رَبِّهِمْ ۖ","Tuhan mereka"],["فَٱلَّذِينَ","Tetapi mereka yang"],["كَفَرُوا۟","kufur"],["قُطِّعَتْ","akan dipotong"],["لَهُمْ","bagi mereka"],["ثِيَابٌۭ","pakaian"],["مِّن","daripada"],["نَّارٍۢ","kebakaran"],["يُصَبُّ","Akan dicurahkan"],["مِن","atas"],["فَوْقِ","atas"],["رُءُوسِهِمُ","kepala mereka"],["ٱلْحَمِيمُ","air yang mendidih"]]],"2615":["(Dihancur leburkan) diluluhkan (dengan air itu apa yang ada dalam perut mereka) yakni lemak dan lain-lainnya (dan) terpangganglah disebabkan panasnya air itu (kulit) mereka.",[["يُصْهَرُ","Akan cair"],["بِهِۦ","dengannya"],["مَا","apa"],["فِى","(berada) dalam"],["بُطُونِهِمْ","perut mereka"],["وَٱلْجُلُودُ","dan kulit"]]],"2616":["(Dan untuk mereka palu-palu dari besi) untuk memukul kepala mereka.",[["وَلَهُم","Dan untuk mereka"],["مَّقَـٰمِعُ","(adalah) batang kait"],["مِنْ","daripada"],["حَدِيدٍۢ","besi"]]],"2617":["(Setiap kali mereka hendak keluar dari neraka) tempat mereka diazab (lantaran kesengsaraan mereka) yang menekan diri mereka di dalam neraka (niscaya mereka dikembalikan ke dalamnya) mereka dipukuli dengan palu-palu besi supaya kembali lagi ke neraka. (Dan) dikatakan kepada mereka, (\"Rasailah azab yang membakar ini\") azab yang sangat membakar ini.",[["كُلَّمَآ","setiap masa"],["أَرَادُوٓا۟","mereka mahu"],["أَن","kepada"],["يَخْرُجُوا۟","keluar"],["مِنْهَا","daripadanya"],["مِنْ","daripada"],["غَمٍّ","keperitan"],["أُعِيدُوا۟","mereka akan dikembalikan"],["فِيهَا","di dalamnya"],["وَذُوقُوا۟","rasa"],["عَذَابَ","azab"],["ٱلْحَرِيقِ","(dari) Api yang Menyala"]]],"2618":["Allah swt. berfirman kepada orang-orang Mukmin, (\"Sesungguhnya Allah memasukkan orang-orang yang beriman dan mengerjakan amal saleh ke dalam surga-surga yang di bawahnya mengalir sungai-sungai. Di surga itu mereka diberi perhiasan dengan gelang-gelang dari emas dan mutiara) kalau dibaca Lu-luin maka artinya perhiasan itu terdiri dari emas dan mutiara, atau emas itu dihiasi dengan mutiara. Jika dibaca Lu-luan berarti ia di'athafkan secara Mahall kepada lafal Min Asaawira. (Dan pakaian mereka adalah sutera) yaitu pakaian yang diharamkan bagi kaum lelaki di dunia.",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُدْخِلُ","akan mengaku"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","perbuatan yang soleh"],["جَنَّـٰتٍۢ","(ke) Taman"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["يُحَلَّوْنَ","Mereka akan berhias"],["فِيهَا","di dalamnya"],["مِنْ","dengan"],["أَسَاوِرَ","gelang tangan"],["مِن","daripada"],["ذَهَبٍۢ","emas"],["وَلُؤْلُؤًۭا ۖ","dan mutiara"],["وَلِبَاسُهُمْ","dan pakaian mereka"],["فِيهَا","di dalamnya"],["حَرِيرٌۭ","(akan daripada) sutera"]]],"2619":["(Dan mereka diberi petunjuk) di dunia (kepada ucapan-ucapan yang baik) yaitu kalimat La Ilaaha Illallaah/ tidak ada Tuhan selain Allah (dan mereka ditunjuki pula kepada jalan yang terpuji) yakni jalan Allah yang terpuji dan agama-Nya.",[["وَهُدُوٓا۟","Dan mereka telah mendapat petunjuk"],["إِلَى","kepada"],["ٱلطَّيِّبِ","yang baik"],["مِنَ","daripada"],["ٱلْقَوْلِ","ucapan itu"],["وَهُدُوٓا۟","dan mereka telah mendapat petunjuk"],["إِلَىٰ","kepada"],["صِرَٰطِ","(jalan)."],["ٱلْحَمِيدِ","(dari) Yang Maha Terpuji"]]],"2620":["(Sesungguhnya orang-orang yang kafir dan menghalangi manusia dari jalan Allah) dari ketaatan kepada-Nya (dan) dari (Masjidilharam yang telah Kami jadikan ia) sebagai manasik dan tempat beribadah (untuk semua manusia, baik yang bermukim) yang tinggal (di situ maupun di padang pasir) yakni pendatang (dan siapa yang bermaksud di dalamnya melakukan kejahatan) huruf Ba di sini adalah Zaidah (secara zalim) yang menyebabkan orang yang bersangkutan zalim, seumpamanya ia mengerjakan perbuatan yang terlarang, sekalipun dalam bentuk mencaci pelayan (niscaya akan Kami rasakan kepadanya sebagian siksa yang pedih)\" yang menyakitkan. Berdasarkan pengertian ini maka Khabar Inna diambil daripadanya. Maksudnya, sesungguhnya orang-orang yang kafir dan menghalangi manusia dari jalan Allah dan dari Masjidilharam, niscaya Kami akan rasakan kepada mereka sebagian siksa yang pedih.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["وَيَصُدُّونَ","dan menghalang"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["وَٱلْمَسْجِدِ","dan Al-Masjid Al-Haraam"],["ٱلْحَرَامِ","dan Al-Masjid Al-Haraam"],["ٱلَّذِى","yang"],["جَعَلْنَـٰهُ","Kami berjaya"],["لِلنَّاسِ","untuk umat manusia"],["سَوَآءً","sama rata"],["ٱلْعَـٰكِفُ","(adalah) pemastautin"],["فِيهِ","di dalamnya"],["وَٱلْبَادِ ۚ","dan pelawat"],["وَمَن","dan sesiapa"],["يُرِدْ","berniat"],["فِيهِ","di dalamnya"],["بِإِلْحَادٍۭ","daripada penyelewengan"],["بِظُلْمٍۢ","(atau) salah laku"],["نُّذِقْهُ","Kita akan buat dia rasa"],["مِنْ","daripada"],["عَذَابٍ","azab"],["أَلِيمٍۢ","yang pedih"]]],"2621":["(Dan) ingatlah (ketika Kami jelaskan) Kami terangkan (kepada Ibrahim tempat Baitullah) supaya ia membangunnya kembali karena Baitullah itu telah diangkat sejak zaman banjir besar yakni zamannya Nabi Nuh, kemudian Kami perintahkan kepada Ibrahim, (\"Janganlah kamu menyekutukan Aku dengan sesuatu pun dan sucikanlah rumah-Ku ini) dari berhala-berhala (bagi orang-orang yang tawaf dan orang-orang yang bermukim) yakni orang-orang yang tinggal di sekitarnya (dan orang-orang yang rukuk dan sujud\") Rukka'is-sujuud adalah bentuk jamak dari kata Raaki 'iin dan Saajidin, maksudnya adalah orang-orang yang salat.",[["وَإِذْ","Dan apabila"],["بَوَّأْنَا","Kami ditugaskan"],["لِإِبْرَٰهِيمَ","kepada Ibrahim"],["مَكَانَ","(tapak) itu"],["ٱلْبَيْتِ","(dari) Dewan"],["أَن","Itu"],["لَّا","jangan"],["تُشْرِكْ","bersekutu"],["بِى","dengan Aku"],["شَيْـًۭٔا","sesuatu"],["وَطَهِّرْ","dan menyucikan"],["بَيْتِىَ","Rumah Aku"],["لِلطَّآئِفِينَ","bagi mereka yang tawaf"],["وَٱلْقَآئِمِينَ","dan mereka yang berdiri"],["وَٱلرُّكَّعِ","dan mereka yang rukuk"],["ٱلسُّجُودِ","(dan) orang-orang yang sujud"]]],"2622":["(Dan berserulah) serukanlah (kepada manusia untuk mengerjakan haji) kemudian Nabi Ibrahim naik ke puncak bukit Abu Qubais, lalu ia berseru, \"Hai manusia! Sesungguhnya Rabb kalian telah membangun Baitullah dan Dia telah mewajibkan kalian untuk melakukan haji, maka sambutlah seruan Rabb kalian ini\". Lalu Nabi Ibrahim menolehkan wajahnya ke kanan dan ke kiri serta ke arah Timur dan ke arah Barat. Maka menjawablah semua orang yang telah ditentukan baginya dapat berhaji dari tulang-tulang sulbi kaum lelaki dan rahim-rahim kaum wanita, seraya mengatakan, \"Labbaik allaahumma Labbaika\", artinya: Ya Allah, kami penuhi panggilan-Mu, Ya Allah, kami penuhi panggilan-Mu. Sedangkan Jawab dari Amar yang di muka tadi ialah (niscaya mereka akan datang kepadamu dengan berjalan kaki) lafal Rijaalan adalah bentuk jamak dari lafal Raajilun, wazannya sama dengan lafal Qaaimun yang bentuk jamaknya adalah Qiyaamun; artinya berjalan kaki (dan) dengan berkendaraan (dengan menaiki unta yang kurus) karena lamanya perjalanan; lafal Dhamirin dapat ditujukan kepada jenis jantan dan betina (mereka datang) yakni unta-unta kurus itu yang dimaksud adalah orang-orang yang mengendarainya (dari segenap penjuru yang jauh) dari daerah yang perjalanannya sangat jauh.",[["وَأَذِّن","Dan mengisytiharkan"],["فِى","kepada"],["ٱلنَّاسِ","[the] manusia"],["بِٱلْحَجِّ","[dari] Haji"],["يَأْتُوكَ","mereka akan datang kepada kamu"],["رِجَالًۭا","(berjalan) kaki"],["وَعَلَىٰ","dan seterusnya"],["كُلِّ","setiap"],["ضَامِرٍۢ","unta kurus"],["يَأْتِينَ","mereka akan datang"],["مِن","daripada"],["كُلِّ","setiap"],["فَجٍّ","lebuh raya gunung"],["عَمِيقٍۢ","jauh"]]],"2623":["(Supaya mereka mempersaksikan) yakni mendatangi (berbagai manfaat untuk mereka) dalam urusan dunia mereka melalui berdagang, atau urusan akhirat atau untuk keduanya. Sehubungan dengan masalah ini ada berbagai pendapat mengenainya (dan supaya mereka menyebut nama Allah pada hari-hari yang telah ditentukan) yakni tanggal sepuluh Zulhijah, atau hari Arafah, atau hari berkurban hingga akhir hari-hari Tasyriq; mengenai masalah ini pun ada beberapa pendapat (atas rezeki yang telah Allah berikan kepada mereka berupa binatang ternak) unta, sapi dan kambing yang disembelih pada hari raya kurban dan ternak-ternak yang disembelih sesudahnya sebagai kurban. (Maka makanlah sebagian daripadanya) jika kalian menyukainya (dan berikanlah untuk dimakan orang-orang yang sengsara lagi fakir) yakni sangat miskin.",[["لِّيَشْهَدُوا۟","Supaya mereka menyaksikan"],["مَنَـٰفِعَ","faedah"],["لَهُمْ","bagi mereka"],["وَيَذْكُرُوا۟","dan menyebut"],["ٱسْمَ","(nama)"],["ٱللَّهِ","(milik) Allah"],["فِىٓ","pada"],["أَيَّامٍۢ","hari"],["مَّعْلُومَـٰتٍ","diketahui"],["عَلَىٰ","atas"],["مَا","apa"],["رَزَقَهُم","Dia telah menyediakan mereka"],["مِّنۢ","daripada"],["بَهِيمَةِ","(the) binatang"],["ٱلْأَنْعَـٰمِ ۖ","(daripada) lembu"],["فَكُلُوا۟","Jadi makan"],["مِنْهَا","daripada mereka"],["وَأَطْعِمُوا۟","dan suapan"],["ٱلْبَآئِسَ","yang sengsara"],["ٱلْفَقِيرَ","orang miskin"]]],"2624":["(Kemudian hendaklah mereka menghilangkan kotoran yang ada pada badan mereka) maksudnya hendaklah mereka merapihkan ketidakrapihan diri mereka seperti memotong rambut dan kuku yang panjang (dan hendaklah mereka menunaikan) dapat dibaca Walyuufuu dan Walyuwaffuu (nazar-nazar mereka) dengan menyembelih hewan ternak sebagai hewan kurban (dan hendaklah mereka melakukan tawaf) tawaf ifadah (sekeliling rumah yang tua itu) yakni rumah kuno, karena ia adalah rumah pertama yang dibuat untuk ibadah manusia.",[["ثُمَّ","Kemudian"],["لْيَقْضُوا۟","biarkan mereka berakhir"],["تَفَثَهُمْ","tugas mereka yang ditetapkan"],["وَلْيُوفُوا۟","dan penuhi"],["نُذُورَهُمْ","nazar mereka"],["وَلْيَطَّوَّفُوا۟","dan tawaf"],["بِٱلْبَيْتِ","Dewan"],["ٱلْعَتِيقِ","[yang] Purba"]]],"2625":["(Demikianlah) menjadi Khabar dari Mubtada yang keberadaannya diperkirakan sebelumnya, yakni perintah Allah itu sebagaimana yang telah disebutkan (dan barang siapa mengagungkan apa-apa yang terhormat di sisi Allah) yaitu hal-hal yang tidak boleh dirusak (maka itu adalah) mengagungkannya (lebih baik baginya di sisi Rabbnya) di akhirat kelak. (Dan telah dihalalkan bagi kamu sekalian binatang ternak) untuk memakannya sesudah disembelih terlebih dahulu (kecuali yang diterangkan kepada kalian) keharamannya di dalam firman yang lainnya yaitu, \"Diharamkan bagi kalian memakan bangkai...\" (Q.S. Al-Maidah, 3). Dengan demikian berarti Istitsna di sini bersifat Munqathi'. Dan dapat pula dikatakan Muttashil, sedangkan barang yang diharamkan adalah ditujukan kepada hewan yang mati dengan sendirinya dan oleh penyebab-penyebab lainnya (maka jauhilah oleh kalian berhala-berhala yang najis itu) huruf Min di sini menunjukkan arti Bayan atau keterangan, maksudnya barang yang najis itu adalah berhala-berhala (dan jauhilah perkataan-perkataan dusta) perkataan yang mengandung kemusyrikan terhadap Allah di dalam bacaan Talbiyah kalian, atau yang dimaksud adalah kesaksian palsu.",[["ذَٰلِكَ","Itu"],["وَمَن","dan sesiapa"],["يُعَظِّمْ","penghormatan"],["حُرُمَـٰتِ","(the) upacara suci"],["ٱللَّهِ","(milik) Allah"],["فَهُوَ","kemudian ia"],["خَيْرٌۭ","(adalah) terbaik"],["لَّهُۥ","baginya"],["عِندَ","dekat"],["رَبِّهِۦ ۗ","Tuhannya"],["وَأُحِلَّتْ","Dan dihalalkan"],["لَكُمُ","kepada kamu"],["ٱلْأَنْعَـٰمُ","lembu itu"],["إِلَّا","kecuali"],["مَا","apa"],["يُتْلَىٰ","dibacakan"],["عَلَيْكُمْ ۖ","kepada kamu"],["فَٱجْتَنِبُوا۟","Jadi elakkan"],["ٱلرِّجْسَ","kekejian itu"],["مِنَ","daripada"],["ٱلْأَوْثَـٰنِ","berhala"],["وَٱجْتَنِبُوا۟","dan elakkan"],["قَوْلَ","(perkataan)."],["ٱلزُّورِ","palsu"]]],"2626":["(Dengan ikhlas kepada Allah) yakni berserah diri kepada-Nya serta berpaling dari semua agama selain dari agama-Nya (tidak mempersekutukan sesuatu dengan Dia) kalimat ayat ini mengukuhkan makna kalimat yang sebelumnya dan keduanya itu merupakan Hal atau kata keterangan dari dhamir Wawu. (Barang siapa mempersekutukan sesuatu dengan Allah, maka adalah ia seolah-olah terjungkal) yakni jatuh (dari langit lalu disambar oleh burung) diambil dengan cepat (atau diterbangkan oleh angin yang melemparkannya) yang menjatuhkannya (ke tempat yang jauh sekali) sangat jauh sehingga tidak dapat diharapkan lagi keselamatannya.",[["حُنَفَآءَ","Berdiri tegak"],["لِلَّهِ","kepada Allah"],["غَيْرَ","tidak"],["مُشْرِكِينَ","rakan kongsi bersekutu"],["بِهِۦ ۚ","dengan Dia"],["وَمَن","Dan sesiapa"],["يُشْرِكْ","rakan kongsi bersekutu"],["بِٱللَّهِ","dengan Allah"],["فَكَأَنَّمَا","maka (ia) seolah-olah"],["خَرَّ","dia telah jatuh"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["فَتَخْطَفُهُ","dan (telah) merampasnya"],["ٱلطَّيْرُ","burung-burung itu"],["أَوْ","atau"],["تَهْوِى","telah ditiup"],["بِهِ","dia"],["ٱلرِّيحُ","angin"],["فِى","kepada"],["مَكَانٍۢ","sebuah tempat"],["سَحِيقٍۢ","jauh sekali"]]],"2627":["(Demikianlah) perintah itu (dan barang siapa mengagungkan syiar-syiar Allah, maka sesungguhnya hal itu) mengagungkan syiar-syiar Allah, yaitu menyembelih hewan kurban untuk tanah suci, seumpamanya hewan kurban itu dipilih yang baik dan digemukkan terlebih dahulu (timbul dari ketakwaan hati) dalam diri mereka. Hewan-hewan kurban itu dinamakan Sya'aair disebabkan kesyiarannya yakni kesemarakannya, disebabkan hewan-hewan tersebut telah diberi tanda yang menunjukkan, bahwa mereka untuk dikurbankan, yaitu seperti dicap dengan besi panas pada punggungnya, sehingga menambah semaraknya suasana hari raya.",[["ذَٰلِكَ","Itu"],["وَمَن","dan sesiapa"],["يُعَظِّمْ","penghormatan"],["شَعَـٰٓئِرَ","(the) Simbol"],["ٱللَّهِ","(milik) Allah"],["فَإِنَّهَا","maka sesungguhnya, ia"],["مِن","(adalah) daripada"],["تَقْوَى","(yang) takwa"],["ٱلْقُلُوبِ","(dari) hati"]]],"2628":["(Bagi kalian pada binatang-binatang hadyu itu ada beberapa manfaat) seperti menjadikannya sebagai hewan kendaraan dan untuk mengangkut barang-barang selagi hal itu tidak membuatnya bahaya atau cacat (sampai pada waktu yang ditentukan) yaitu waktu disembelih sebagai hewan kurban (kemudian tempat wajib serta akhir masa penyembelihannya) tempat diperbolehkan menyembelihnya (ialah setelah sampai ke Baitul Atiq) yaitu maksudnya di semua tanah suci.",[["لَكُمْ","Untuk kamu"],["فِيهَا","di dalamnya"],["مَنَـٰفِعُ","(adalah) faedah"],["إِلَىٰٓ","bagi"],["أَجَلٍۢ","satu istilah"],["مُّسَمًّۭى","dilantik"],["ثُمَّ","kemudian"],["مَحِلُّهَآ","tempat korban mereka"],["إِلَى","(adalah) pada"],["ٱلْبَيْتِ","Dewan"],["ٱلْعَتِيقِ","yang Purba"]]],"2629":["(Dan bagi tiap-tiap umat) golongan orang-orang yang beriman yang telah mendahului kalian (telah Kami syariatkan penyembelihan kurban) kalau dibaca Mansakan adalah Mashdar dan kalau dibaca Minsakan berarti isim makan atau nama tempat. Maksudnya menyembelih kurban atau tempat penyembelihannya (supaya mereka menyebut nama Allah terhadap binatang ternak yang telah direzekikan Allah kepada mereka) sewaktu mereka menyembelihnya. (Maka Tuhan kalian adalah Tuhan Yang Maha Esa, karena itu berserah dirilah kalian kepada-Nya) taat dan patuhlah kalian kepada-Nya. (Dan berilah kabar gembira kepada orang-orang yang tunduk patuh kepada Allah) orang-orang yang taat dan merendahkan diri kepada-Nya.",[["وَلِكُلِّ","Dan untuk setiap"],["أُمَّةٍۢ","bangsa"],["جَعَلْنَا","Kami telah melantik"],["مَنسَكًۭا","satu upacara"],["لِّيَذْكُرُوا۟","yang boleh mereka sebutkan"],["ٱسْمَ","(nama)"],["ٱللَّهِ","(milik) Allah"],["عَلَىٰ","atas"],["مَا","apa"],["رَزَقَهُم","Dia (telah) menyediakan mereka"],["مِّنۢ","daripada"],["بَهِيمَةِ","(the) binatang"],["ٱلْأَنْعَـٰمِ ۗ","(daripada) lembu"],["فَإِلَـٰهُكُمْ","Dan Tuhanmu"],["إِلَـٰهٌۭ","(ialah) Tuhan"],["وَٰحِدٌۭ","satu"],["فَلَهُۥٓ","demikian kepada-Nya"],["أَسْلِمُوا۟ ۗ","menyerahkan"],["وَبَشِّرِ","Dan sampaikanlah berita gembira"],["ٱلْمُخْبِتِينَ","(kepada) orang-orang yang hina"]]],"2630":["(Yaitu orang-orang yang apabila disebutkan nama Allah gemetarlah) yakni takutlah (hati mereka, orang-orang yang sabar terhadap apa yang menimpa mereka) berupa musibah dan malapetaka (orang-orang yang mendirikan salat) yang mengerjakan salat pada waktu-waktunya (dan orang-orang yang menafkahkan sebagian dari apa yang telah Kami rezekikan kepada mereka) mereka menyedekahkannya.",[["ٱلَّذِينَ","Mereka itu"],["إِذَا","apabila"],["ذُكِرَ","disebut"],["ٱللَّهُ","Allah"],["وَجِلَتْ","bertakwa"],["قُلُوبُهُمْ","hati mereka"],["وَٱلصَّـٰبِرِينَ","dan orang-orang yang sabar"],["عَلَىٰ","atas"],["مَآ","apa sahaja"],["أَصَابَهُمْ","telah menimpa mereka"],["وَٱلْمُقِيمِى","dan mereka yang mendirikan"],["ٱلصَّلَوٰةِ","solat"],["وَمِمَّا","dan daripada apa"],["رَزَقْنَـٰهُمْ","Kami telah menyediakan mereka"],["يُنفِقُونَ","mereka belanjakan"]]],"2631":["(Dan unta-unta itu) al Budna adalah bentuk jamak dari lafal Badanah, yaitu hewan unta (Kami jadikan untuk kalian sebagian syiar Allah) pertanda-pertanda bagi agama-Nya (kalian memperoleh kebaikan yang banyak padanya) kemanfaatan duniawi sebagaimana yang telah disebutkan tadi dan pahala di akhirat (maka sebutlah oleh kalian nama Allah ketika kalian menyembelihnya) sewaktu menyembelihnya (dalam keadaan berdiri) dengan kaki yang terikat. (Kemudian apabila telah roboh) sesudah disembelih, yaitu telah mati dan sudah waktunya untuk dapat dimakan (maka makanlah sebagiannya) jika kalian suka (dan beri makanlah orang yang rela dengan apa yang ada padanya) maksudnya orang-orang yang menerima dengan apa yang diberikan oleh Allah kepadanya dan ia tidak meminta-minta serta tidak pernah memamerkan dirinya miskin (dan orang yang meminta) yaitu orang yang meminta-minta dan orang yang menampakkan kemiskinannya. (Demikianlah) sebagaimana penundukan tadi (Kami telah menundukkan unta-unta itu kepada kalian) sehingga mereka dapat disembelih dan dapat dinaiki, jika tidak Kami tundukkan maka niscaya kalian tidak akan mampu terhadapnya (mudah-mudahan kalian bersyukur) atas nikmat-Ku kepada kalian.",[["وَٱلْبُدْنَ","Dan unta dan lembu"],["جَعَلْنَـٰهَا","Kami telah membuat mereka"],["لَكُم","bagi kamu"],["مِّن","antara"],["شَعَـٰٓئِرِ","(the) Simbol"],["ٱللَّهِ","(milik) Allah"],["لَكُمْ","bagi kamu"],["فِيهَا","di dalamnya"],["خَيْرٌۭ ۖ","(adalah) baik"],["فَٱذْكُرُوا۟","Jadi sebut"],["ٱسْمَ","(nama)"],["ٱللَّهِ","(milik) Allah"],["عَلَيْهَا","atas mereka"],["صَوَآفَّ ۖ","(apabila) berbaris"],["فَإِذَا","dan apabila"],["وَجَبَتْ","sedang turun"],["جُنُوبُهَا","pihak mereka"],["فَكُلُوا۟","kemudian makan"],["مِنْهَا","daripada mereka"],["وَأَطْعِمُوا۟","dan suapan"],["ٱلْقَانِعَ","yang memerlukan yang tidak meminta"],["وَٱلْمُعْتَرَّ ۚ","dan orang miskin yang meminta"],["كَذَٰلِكَ","Demikianlah"],["سَخَّرْنَـٰهَا","Kami telah menundukkan mereka"],["لَكُمْ","kepada kamu"],["لَعَلَّكُمْ","supaya kamu"],["تَشْكُرُونَ","bersyukurlah"]]],"2632":["(Daging-daging unta dan darahnya itu sekali-kali tidak dapat mencapai keridaan Allah) tidak dapat diterima di sisi-Nya (tetapi ketakwaan daripada kalianlah yang dapat mencapai keridaan-Nya) yaitu yang dapat sampai kepada-Nya hanyalah amal saleh yang ikhlas disertai iman. (Demikianlah Allah telah menundukkannya untuk kalian supaya kalian mengagungkan Allah terhadap hidayah-Nya) yakni atas petunjuk-Nya yang telah membimbing kalian sehingga dapat mengetahui pertanda-pertanda agama dan manasik-manasik haji-Nya. (Dan berilah kabar gembira kepada orang-orang yang berbuat baik) yaitu orang-orang yang mentauhidkan Allah.",[["لَن","tidak akan"],["يَنَالَ","capai"],["ٱللَّهَ","Allah"],["لُحُومُهَا","daging mereka"],["وَلَا","dan bukan"],["دِمَآؤُهَا","darah mereka"],["وَلَـٰكِن","tetapi"],["يَنَالُهُ","sampai kepada-Nya"],["ٱلتَّقْوَىٰ","ketakwaan itu"],["مِنكُمْ ۚ","daripada kamu"],["كَذَٰلِكَ","Demikianlah"],["سَخَّرَهَا","Dia menundukkan mereka"],["لَكُمْ","kepada kamu"],["لِتُكَبِّرُوا۟","supaya kamu membesarkan"],["ٱللَّهَ","Allah"],["عَلَىٰ","bagi"],["مَا","apa"],["هَدَىٰكُمْ ۗ","Dia telah membimbing kamu"],["وَبَشِّرِ","Dan sampaikanlah berita gembira"],["ٱلْمُحْسِنِينَ","(kepada) orang-orang yang berbuat baik"]]],"2633":["(Sesungguhnya Allah membela orang-orang yang telah beriman) daripada perbuatan-perbuatan kaum musyrikin. (Sesungguhnya Allah tidak menyukai tiap-tiap orang yang berkhianat) di dalam amanat yang dititipkan kepadanya (lagi mengingkari nikmat) ingkar terhadap nikmat-nikmat-Nya; mereka adalah orang-orang musyrik. Makna ayat ini ialah bahwa Allah akan mengazab mereka.",[["۞ إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُدَٰفِعُ","mempertahankan"],["عَنِ","mempertahankan"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوٓا۟ ۗ","beriman"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يُحِبُّ","suka"],["كُلَّ","setiap"],["خَوَّانٍۢ","khianat"],["كَفُورٍ","tidak bersyukur"]]],"2634":["(Telah diizinkan bagi orang-orang yang diperangi) yaitu orang-orang Mukmin untuk berperang. Ayat ini adalah ayat pertama yang diturunkan sehubungan dengan masalah jihad (karena sesungguhnya mereka) (telah dianiaya) oleh orang-orang kafir. (Dan sesungguhnya Allah benar-benar Maha Kuasa menolong mereka).",[["أُذِنَ","Keizinan diberikan"],["لِلَّذِينَ","kepada mereka yang"],["يُقَـٰتَلُونَ","sedang diperangi"],["بِأَنَّهُمْ","kerana mereka"],["ظُلِمُوا۟ ۚ","telah dizalimi"],["وَإِنَّ","Dan sesungguhnya"],["ٱللَّهَ","Allah"],["عَلَىٰ","bagi"],["نَصْرِهِمْ","kemenangan mereka"],["لَقَدِيرٌ","(adalah) pasti Mampu"]]],"2635":["Mereka adalah (orang-orang yang telah diusir dari kampung halaman mereka tanpa alasan yang benar) di dalam pengusiran itu; mereka sekali-kali tidak diusir (melainkan karena mereka berkata) disebabkan perkataan yang mereka ucapkan yaitu, (\"Rabb kami hanyalah Allah\") semata. Perkataan ini adalah perkataan yang hak dan benar, maka mengusir hanya dengan alasan karena mengucapkan perkataan itu adalah tidak dibenarkan. (Dan sekiranya Allah tiada menolak keganasan sebagian manusia) lafal Ba'dhahum menjadi Badal Ba'dh lafal An-Naas (dengan sebagian yang lain, tentulah telah dirobohkan) dibaca Lahuddimat dengan memakai harakat Tasydid menunjukkan makna banyak, yakni telah banyak dirobohkan; sebagaimana dapat dibaca Takhfif yaitu Lahudimat (biara-biara) bagi para rahib (gereja-gereja) bagi orang-orang Nasrani (rumah-rumah ibadah) bagi orang-orang Yahudi; lafal shalawaat artinya tempat peribadatan menurut bahasa Ibrani (dan mesjid-mesjid) bagi kaum Muslimin (yang disebut di dalamnya) maksudnya di dalam tempat-tempat yang telah disebutkan tadi (nama Allah dengan banyak) sehingga ibadah menjadi terhenti karena robohnya tempat-tempat tersebut. (Sesungguhnya Allah pasti menolong orang yang menolong-Nya) menolong agama-Nya. (Sesungguhnya Allah benar-benar Maha Kuat) di atas semua makhluk-Nya (lagi Maha Perkasa) pengaruh dan kekuasaan-Nya maha perkasa.",[["ٱلَّذِينَ","Orang yang"],["أُخْرِجُوا۟","telah diusir"],["مِن","daripada"],["دِيَـٰرِهِم","rumah mereka"],["بِغَيْرِ","tanpa"],["حَقٍّ","betul"],["إِلَّآ","kecuali"],["أَن","bahawa"],["يَقُولُوا۟","mereka berkata"],["رَبُّنَا","Wahai Tuhan kami"],["ٱللَّهُ ۗ","(ialah) Allah"],["وَلَوْلَا","Dan jika tidak"],["دَفْعُ","Allah semak"],["ٱللَّهِ","Allah semak"],["ٱلنَّاسَ","manusia"],["بَعْضَهُم","sebahagian mereka"],["بِبَعْضٍۢ","oleh orang lain"],["لَّهُدِّمَتْ","nescaya (akan) telah dirobohkan"],["صَوَٰمِعُ","biara"],["وَبِيَعٌۭ","dan gereja"],["وَصَلَوَٰتٌۭ","dan rumah ibadat"],["وَمَسَـٰجِدُ","dan masjid"],["يُذْكَرُ","disebut"],["فِيهَا","di dalamnya"],["ٱسْمُ","(nama) Allah"],["ٱللَّهِ","(nama) Allah"],["كَثِيرًۭا ۗ","banyak"],["وَلَيَنصُرَنَّ","Dan sesungguhnya Allah akan menolong"],["ٱللَّهُ","Dan sesungguhnya Allah akan menolong"],["مَن","(mereka) yang"],["يَنصُرُهُۥٓ ۗ","tolonglah Dia"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَقَوِىٌّ","Sesungguhnya Maha Kuat"],["عَزِيزٌ","Maha Perkasa"]]],"2636":["(Yaitu orang-orang yang jika Kami teguhkan kedudukan mereka di muka bumi) dengan memberikan pertolongan kepada mereka sehingga mereka dapat mengalahkan musuh-musuhnya (niscaya mereka mendirikan salat, menunaikan zakat, menyuruh berbuat yang makruf dan mencegah dari perbuatan yang mungkar) kalimat ayat ini menjadi Jawab Syarat; dan Syarat beserta Jawabnya menjadi Shilah dari Maushul, kemudian diperkirakan adanya lafal Hum sebelumnya sebagai Mubtada (dan kepada Allahlah kembali segala urusan) di akhirat, semua urusan itu kembali kepada-Nya.",[["ٱلَّذِينَ","Orang yang"],["إِن","jika"],["مَّكَّنَّـٰهُمْ","Kami menubuhkan mereka"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["أَقَامُوا۟","mereka menubuhkan"],["ٱلصَّلَوٰةَ","solat"],["وَءَاتَوُا۟","dan mereka memberi"],["ٱلزَّكَوٰةَ","zakat"],["وَأَمَرُوا۟","dan mereka menyuruh"],["بِٱلْمَعْرُوفِ","yang betul"],["وَنَهَوْا۟","dan melarang"],["عَنِ","daripada"],["ٱلْمُنكَرِ ۗ","yang salah"],["وَلِلَّهِ","Dan untuk Allah"],["عَـٰقِبَةُ","(adalah) akhir"],["ٱلْأُمُورِ","(dari) perkara-perkara itu"]]],"2637":["(Dan jika mereka mendustakan kamu) ayat ini mengandung makna yang menghibur hati Nabi saw. (maka sesungguhnya telah mendustakan juga sebelum mereka kaum Nuh) lafal Qaum dimuannatskan karena memandang dari segi maknanya (Ad) yakni kaum Nabi Hud (dan Tsamud) kaum Nabi Saleh.",[["وَإِن","Dan jika"],["يُكَذِّبُوكَ","mereka menafikan kamu"],["فَقَدْ","jadi sesungguhnya"],["كَذَّبَتْ","dinafikan"],["قَبْلَهُمْ","sebelum mereka"],["قَوْمُ","kaum"],["نُوحٍۢ","(daripada) Nuh"],["وَعَادٌۭ","dan Aad"],["وَثَمُودُ","dan kaum Thamud"]]],"2638":["(Dan kaum Ibrahim, kaum Luth).",[["وَقَوْمُ","Dan (orang-orang) itu"],["إِبْرَٰهِيمَ","(dari) Ibrahim"],["وَقَوْمُ","dan (orang-orang) itu"],["لُوطٍۢ","(dari) Lut"]]],"2639":["(Dan penduduk Madyan) kaum Nabi Syuaib (dan telah didustakan Musa) didustakan oleh bangsa Koptik bukan oleh kaumnya sendiri yaitu Bani Israel. Maksudnya mereka semuanya mendustakan rasul-rasul mereka, hal itu menjadi perumpamaan bagimu (lalu Aku tangguhkan untuk orang-orang kafir) memberikan tangguh dengan mengakhirkan azab mereka (kemudian Aku balas mereka) yaitu menimpakan azab kepada mereka (maka lihatlah bagaimana besarnya kebencian-Ku) kemurkaan-Ku kepada mereka disebabkan kedustaan mereka, maka Aku binasakan mereka. Istifham di sini mengandung makna Taqrir, maksudnya azab itu benar-benar ditimpakan kepada orang-orang yang berhak menerimanya.",[["وَأَصْحَـٰبُ","Dan penduduk"],["مَدْيَنَ ۖ","(dari) Madyan"],["وَكُذِّبَ","Dan Musa telah dinafikan"],["مُوسَىٰ","Dan Musa telah dinafikan"],["فَأَمْلَيْتُ","jadi aku beri tangguh"],["لِلْكَـٰفِرِينَ","kepada orang-orang kafir"],["ثُمَّ","kemudian"],["أَخَذْتُهُمْ ۖ","Aku menangkap mereka"],["فَكَيْفَ","dan bagaimana"],["كَانَ","adalah"],["نَكِيرِ","hukuman aku"]]],"2640":["(Berapa banyaknya) sudah berapa banyak (negeri yang Kami telah membinasakannya) menurut qiraat yang lain dibaca Ahlaktuhaa (yang penduduknya dalam keadaan zalim) para penghuninya berbuat aniaya, disebabkan kekafiran mereka (maka runtuhlah) roboh tembok-temboknya (menutupi atap-atapnya) atap-atap rumah mereka tertutup oleh reruntuhan tembok-temboknya (dan) berapa banyak pula (sumur yang terlantar) ditinggalkan begitu saja disebabkan para pemiliknya binasa (dan istana yang tinggi) lagi sepi disebabkan para pemiliknya telah mati binasa.",[["فَكَأَيِّن","Dan berapa banyak"],["مِّن","daripada"],["قَرْيَةٍ","sebuah perbandaran"],["أَهْلَكْنَـٰهَا","Kami telah memusnahkannya"],["وَهِىَ","semasa itu"],["ظَالِمَةٌۭ","melakukan kesalahan"],["فَهِىَ","jadi ia"],["خَاوِيَةٌ","jatuh"],["عَلَىٰ","pada"],["عُرُوشِهَا","bumbungnya"],["وَبِئْرٍۢ","dan baik"],["مُّعَطَّلَةٍۢ","terbengkalai"],["وَقَصْرٍۢ","dan istana"],["مَّشِيدٍ","megah"]]],"2641":["(Maka apakah mereka tidak berjalan) mereka orang-orang kafir Mekah itu (di muka bumi, lalu mereka mempunyai hati yang dengan itu mereka dapat memahami) apa yang telah menimpa orang-orang yang mendustakan sebelum mereka (atau mempunyai telinga yang dengan itu mereka dapat mendengar?) berita-berita tentang dibinasakannya mereka dan hancurnya negeri-negeri tempat tinggal mereka, oleh sebab itu mereka mengambil pelajaran darinya. (Karena sesungguhnya) kisah yang sesungguhnya (bukanlah mata itu yang buta, tetapi yang buta ialah hati yang di dalam dada) kalimat ayat ini berfungsi mengukuhkan makna sebelumnya.",[["أَفَلَمْ","Jadi belum"],["يَسِيرُوا۟","mereka mengembara"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَتَكُونَ","dan adalah"],["لَهُمْ","bagi mereka"],["قُلُوبٌۭ","hati"],["يَعْقِلُونَ","(untuk) sebab"],["بِهَآ","dengannya"],["أَوْ","atau"],["ءَاذَانٌۭ","telinga"],["يَسْمَعُونَ","(untuk) mendengar"],["بِهَا ۖ","dengannya"],["فَإِنَّهَا","Kerana sesungguhnya, [ia]"],["لَا","tidak"],["تَعْمَى","(adalah) buta"],["ٱلْأَبْصَـٰرُ","mata"],["وَلَـٰكِن","tetapi"],["تَعْمَى","(adalah) buta"],["ٱلْقُلُوبُ","hati"],["ٱلَّتِى","yang"],["فِى","(ada) dalam"],["ٱلصُّدُورِ","buah dada"]]],"2642":["(Dan mereka meminta kepadamu agar azab itu disegerakan, padahal Allah sekali-kali tidak akan menyalahi janji-Nya) untuk menurunkan azab itu, maka Dia menurunkannya dalam perang Badar. (Sesungguhnya sehari di sisi Rabbmu) hari-hari di akhirat disebabkan pedihnya azab (adalah seperti seribu tahun dari tahun-tahun yang kalian hitung) dapat dibaca Ya'udduuna dan Ta'udduuna, yakni menurut perhitungan tahun-tahun di dunia.",[["وَيَسْتَعْجِلُونَكَ","Dan mereka meminta kamu untuk menyegerakan"],["بِٱلْعَذَابِ","azab"],["وَلَن","Tetapi tidak akan pernah"],["يُخْلِفَ","gagal/melanggar"],["ٱللَّهُ","Allah"],["وَعْدَهُۥ ۚ","(dalam) Janji-Nya"],["وَإِنَّ","Dan sesungguhnya"],["يَوْمًا","sehari"],["عِندَ","dengan"],["رَبِّكَ","Tuhanmu"],["كَأَلْفِ","(adalah) seperti seribu"],["سَنَةٍۢ","tahun"],["مِّمَّا","tentang apa"],["تَعُدُّونَ","kamu mengira"]]],"2643":["(Dan berapa banyaknya kota yang Kami tangguhkan azab-Ku kepadanya, yang penduduknya berbuat zalim, kemudian Aku azab mereka) yang dimaksud dengan kota di sini adalah para penduduknya (dan hanya kepada Akulah kembalinya segala sesuatu).",[["وَكَأَيِّن","Dan berapa banyak"],["مِّن","daripada"],["قَرْيَةٍ","sebuah perbandaran"],["أَمْلَيْتُ","Aku memberi tangguh"],["لَهَا","kepadanya"],["وَهِىَ","semasa itu"],["ظَالِمَةٌۭ","(sedang) melakukan kesalahan"],["ثُمَّ","Kemudian"],["أَخَذْتُهَا","Aku merampasnya"],["وَإِلَىَّ","dan kepada-Ku"],["ٱلْمَصِيرُ","(adalah) destinasi"]]],"2644":["(Katakanlah, \"Hai manusia!) yakni penduduk Mekah (Sesungguhnya aku adalah seorang pemberi peringatan yang nyata kepada kalian\") dan jelas peringatannya, dan aku adalah pembawa berita gembira bagi orang-orang yang beriman.",[["قُلْ","Katakanlah"],["يَـٰٓأَيُّهَا","Wahai umat manusia"],["ٱلنَّاسُ","Wahai umat manusia"],["إِنَّمَآ","Hanya"],["أَنَا۠","aku"],["لَكُمْ","kepada kamu"],["نَذِيرٌۭ","seorang pemberi amaran"],["مُّبِينٌۭ","yang nyata"]]],"2645":["(Maka orang-orang yang beriman dan mengerjakan amal saleh, bagi mereka ampunan) dari dosa-dosa (dan rezeki yang mulia) yaitu surga.",[["فَٱلَّذِينَ","Jadi mereka yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["لَهُم","bagi mereka"],["مَّغْفِرَةٌۭ","(ialah) pengampunan"],["وَرِزْقٌۭ","dan peruntukan"],["كَرِيمٌۭ","mulia"]]],"2646":["(Dan orang-orang yang berusaha terhadap ayat-ayat Kami) Alquran dengan menentang dan membatalkannya (dengan melemahkan) orang-orang yang mengikuti Nabi saw., mereka menganggap lemah orang-orang yang mengikutinya, dan mereka berupaya menghambat kaum Muslimin untuk beriman kepadanya, atau mereka menganggap lemah Kami untuk dapat mengazab mereka. Dan menurut qiraat yang lain dibaca Mu'ajjiziina, yakni mereka dapat mendahului Kami, atau dengan kata lain mereka mengira, bahwa diri mereka yang ingkar terhadap adanya hari berbangkit dan hari pembalasan mereka mengira akan selamat dari azab Kami (mereka itu adalah penghuni-penghuni Jahim) yakni neraka.",[["وَٱلَّذِينَ","Dan orang yang"],["سَعَوْا۟","berusaha"],["فِىٓ","terhadap"],["ءَايَـٰتِنَا","Ayat Kami"],["مُعَـٰجِزِينَ","(untuk) menyebabkan kegagalan"],["أُو۟لَـٰٓئِكَ","mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْجَحِيمِ","(dari) api Neraka"]]],"2647":["(Dan Kami tidak mengutus sebelum kamu seorang rasul pun) rasul adalah seorang nabi yang diperintahkan untuk menyampaikan wahyu (dan tidak pula seorang nabi) yaitu orang yang diberi wahyu akan tetapi tidak diperintahkan untuk menyampaikannya (melainkan apabila ia membaca) membacakan Alquran (setan pun, memasukkan godaan-godaan terhadap bacaannya itu) membisikkan apa-apa yang bukan Alquran dan disukai oleh orang-orang yang ia diutus kepada mereka. Sehubungan dengan hal ini Nabi saw. pernah mengatakan setelah beliau membacakan surah An-Najm, yaitu sesudah firman-Nya, \"Maka apakah patut kalian (hai orang-orang musyrik) menganggap Lata, Uzza dan Manat yang ketiganya...\" (Q.S. An-Najm, 19-2O) lalu beliau mengatakan, \"Bintang-bintang yang ada di langit yang tinggi itu, sesungguhnya manfaatnya dapat diharapkan\". Orang-orang musyrik yang ada di hadapan Nabi saw. kala itu merasa gembira mendengarnya. Hal ini dilakukan oleh Nabi saw. di hadapan mereka, dan sewaktu Nabi saw. membacakan ayat di atas lalu setan meniupkan godaan kepada lisan Nabi saw. tanpa ia sadari, sehingga keluarlah perkataan itu dari lisannya. Maka malaikat Jibril memberitahukan kepadanya apa yang telah ditiupkan oleh setan terhadap lisannya itu, lalu Nabi saw. merasa berduka cita atas peristiwa itu. Hati Nabi saw. menjadi terhibur kembali setelah turunnya ayat berikut ini, (\"Allah menghilangkan) membatalkan (apa yang ditiupkan oleh setan itu, dan Dia menguatkan ayat-ayat-Nya) memantapkannya. (Dan Allah Maha Mengetahui) apa yang telah dilancarkan oleh setan tadi (lagi Maha Bijaksana) di dalam memberikan kesempatan kepada setan untuk dapat meniupkan godaannya kepada Nabi saw. Dia berbuat apa saja yang dikehendaki-Nya.",[["وَمَآ","Dan tidak"],["أَرْسَلْنَا","Kami utus"],["مِن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["مِن","sebarang"],["رَّسُولٍۢ","Utusan"],["وَلَا","dan bukan"],["نَبِىٍّ","seorang Nabi"],["إِلَّآ","tetapi"],["إِذَا","apabila"],["تَمَنَّىٰٓ","dia mengaji"],["أَلْقَى","melemparkan"],["ٱلشَّيْطَـٰنُ","syaitan"],["فِىٓ","dalam"],["أُمْنِيَّتِهِۦ","bacaannya"],["فَيَنسَخُ","Tetapi Allah menghapuskan"],["ٱللَّهُ","Tetapi Allah menghapuskan"],["مَا","apa"],["يُلْقِى","membaling"],["ٱلشَّيْطَـٰنُ","syaitan"],["ثُمَّ","kemudian"],["يُحْكِمُ","Allah akan menetapkan"],["ٱللَّهُ","Allah akan menetapkan"],["ءَايَـٰتِهِۦ ۗ","Ayat-ayatNya"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌ","Maha Mengetahui"],["حَكِيمٌۭ","Maha Bijaksana"]]],"2648":["(Agar Dia menjadikan apa yang ditiupkan oleh setan itu sebagai cobaan) yakni musibah (bagi orang-orang yang di dalam hatinya ada penyakit) perselisihan dan kemunafikan (dan yang kasar hatinya) orang-orang musyrik; hati mereka kasar dan keras tidak mau menerima barang yang hak. (Dan sesungguhnya orang-orang yang zalim itu) yakni orang-orang kafir (benar-benar dalam permusuhan yang sangat\") mereka berada dalam perselisihan yang berkepanjangan dengan Nabi saw. dan orang-orang Mukmin, hal ini dapat diketahui sewaktu terlontar kata-kata dari lisan Nabi saw. yang menyebutkan tuhan-tuhan mereka dengan sebutan yang membuat mereka suka; hanya saja hal itu dibatalkan oleh firman Allah selanjutnya.",[["لِّيَجْعَلَ","Supaya Dia jadikan"],["مَا","apa"],["يُلْقِى","Syaitan melempar"],["ٱلشَّيْطَـٰنُ","Syaitan melempar"],["فِتْنَةًۭ","perbicaraan"],["لِّلَّذِينَ","untuk mereka"],["فِى","dalam"],["قُلُوبِهِم","hati mereka"],["مَّرَضٌۭ","(adalah) penyakit"],["وَٱلْقَاسِيَةِ","dan (adalah) keras"],["قُلُوبُهُمْ ۗ","hati mereka"],["وَإِنَّ","Dan sesungguhnya"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["لَفِى","(adalah) pasti, dalam"],["شِقَاقٍۭ","perpecahan"],["بَعِيدٍۢ","jauh"]]],"2649":["(Dan agar orang-orang yang telah diberi ilmu meyakini) diberi ilmu tentang ketauhidan dan Alquran (bahwasanya Alquran) itulah (yang hak dari Rabbmu lalu mereka beriman kepadanya dan tenanglah) yakni mantaplah (hati mereka kepadanya, dan sesungguhnya Allah adalah Pemberi petunjuk bagi orang-orang yang beriman kepada jalan) tuntunan (yang lurus) yaitu agama Islam.",[["وَلِيَعْلَمَ","Dan itu mungkin tahu"],["ٱلَّذِينَ","orang yang"],["أُوتُوا۟","telah diberikan"],["ٱلْعِلْمَ","pengetahuan itu"],["أَنَّهُ","bahawa ia"],["ٱلْحَقُّ","(adalah) kebenaran"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["فَيُؤْمِنُوا۟","dan mereka beriman"],["بِهِۦ","di dalamnya"],["فَتُخْبِتَ","dan boleh tunduk dengan rendah hati"],["لَهُۥ","kepadanya"],["قُلُوبُهُمْ ۗ","hati mereka"],["وَإِنَّ","Dan sesungguhnya"],["ٱللَّهَ","Allah"],["لَهَادِ","sesungguhnya (adalah) Petunjuk"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوٓا۟","beriman"],["إِلَىٰ","kepada"],["صِرَٰطٍۢ","a Laluan"],["مُّسْتَقِيمٍۢ","Lurus"]]],"2650":["(Dan senantiasalah orang-orang kafir itu berada dalam keragu-raguan) tidak percaya (terhadap Alquran) disebabkan apa-apa yang diembuskan oleh setan melalui lisan Nabi, kemudian hal itu dibatalkan (hingga datang kepada mereka saat ajalnya dengan tiba-tiba) saat kematian mereka, atau yang dimaksud adalah hari kiamat yang datang secara mendadak (atau datang kepada mereka azab hari kiamat) yaitu perang Badar, yang di dalam perang itu tiada kebaikan sedikit pun bagi orang-orang kafir; keadaan pada hari itu diserupakan bagaikan angin kering yang tidak membawa kebaikan sedikit pun. Atau makna yang dimaksud adalah azab hari kiamat, yaitu hari yang tidak ada malam hari lagi sesudahnya.",[["وَلَا","Dan tidak"],["يَزَالُ","akan terhenti"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["فِى","(menjadi) dalam"],["مِرْيَةٍۢ","keraguan"],["مِّنْهُ","daripadanya"],["حَتَّىٰ","sehingga"],["تَأْتِيَهُمُ","datang kepada mereka"],["ٱلسَّاعَةُ","Jam itu"],["بَغْتَةً","tiba-tiba"],["أَوْ","atau"],["يَأْتِيَهُمْ","datang kepada mereka"],["عَذَابُ","azab"],["يَوْمٍ","(dari) sehari"],["عَقِيمٍ","mandul"]]],"2651":["(Kekuasaan di hari itu) yaitu hari kiamat (hanyalah bagi Allah) semata. Makna Istiqrar atau tetap yang terkandung sebelum lafal Yaumaidzin adalah 'Amil yang menashabkan Zharaf atau lafal Yaumaidzin. Maksudnya; kekuasaan pada hari kiamat itu hanyalah tetap bagi Allah semata (Dia memberi keputusan di antara mereka) antara kaum Mukminin dan orang-orang kafir, pengertian ini dijelaskan oleh firman selanjutnya, yaitu, (Maka orang-orang yang beriman dan beramal saleh adalah di dalam surga yang penuh kenikmatan) penuh dengan anugerah dari Allah.",[["ٱلْمُلْكُ","Kedaulatan"],["يَوْمَئِذٍۢ","(pada) hari itu"],["لِّلَّهِ","(akan) untuk Allah"],["يَحْكُمُ","Dia akan menilai"],["بَيْنَهُمْ ۚ","antara mereka"],["فَٱلَّذِينَ","Jadi mereka yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan lakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["فِى","(akan) masuk"],["جَنَّـٰتِ","Taman-taman"],["ٱلنَّعِيمِ","(dari) Kegembiraan"]]],"2652":["(Dan orang-orang yang kafir dan mendustakan ayat-ayat Kami, maka bagi mereka azab yang menghinakan) azab yang keras disebabkan kekafiran mereka.",[["وَٱلَّذِينَ","Dan orang yang"],["كَفَرُوا۟","kufur"],["وَكَذَّبُوا۟","dan dinafikan"],["بِـَٔايَـٰتِنَا","Ayat Kami"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["لَهُمْ","bagi mereka"],["عَذَابٌۭ","(akan menjadi) azab"],["مُّهِينٌۭ","memalukan"]]],"2653":["(Dan orang-orang yang berhijrah di jalan Allah) jalan ketaatan kepada-Nya, yaitu berhijrah dari Mekah ke Madinah (kemudian mereka dibunuh atau mati, benar-benar Allah akan memberikan kepada mereka rezeki yang baik) yakni rezeki di surga. (Dan sesungguhnya Allah adalah sebaik-baik pemberi rezeki) Pemberi rezeki yang paling utama.",[["وَٱلَّذِينَ","Dan orang yang"],["هَاجَرُوا۟","berhijrah"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["ثُمَّ","kemudian"],["قُتِلُوٓا۟","telah dibunuh"],["أَوْ","atau"],["مَاتُوا۟","meninggal dunia"],["لَيَرْزُقَنَّهُمُ","nescaya Allah akan memberi rezeki kepada mereka"],["ٱللَّهُ","nescaya Allah akan memberi rezeki kepada mereka"],["رِزْقًا","suatu peruntukan"],["حَسَنًۭا ۚ","kebaikan"],["وَإِنَّ","Dan sesungguhnya"],["ٱللَّهَ","Allah"],["لَهُوَ","pasti, Dia"],["خَيْرُ","(adalah) Terbaik"],["ٱلرَّٰزِقِينَ","(dari) Pembekal"]]],"2654":["(Sesungguhnya Allah akan memasukkan mereka ke dalam suatu tempat) dapat dibaca Mudkhalan dan Madkhalan, artinya tempat masuk atau suatu tempat (yang mereka menyukainya) yaitu surga. (Dan sesungguhnya Allah Maha Mengetahui) tentang niat mereka (lagi Maha Penyantun) dari menghukum mereka.",[["لَيُدْخِلَنَّهُم","Sesungguhnya Dia akan memasukkan mereka"],["مُّدْخَلًۭا","(ke) pintu masuk"],["يَرْضَوْنَهُۥ ۗ","mereka akan redha (dengan)nya"],["وَإِنَّ","Dan sesungguhnya"],["ٱللَّهَ","Allah"],["لَعَلِيمٌ","sesungguhnya, (adalah) Maha Mengetahui"],["حَلِيمٌۭ","Maha Penyabar"]]],"2655":["Perkaranya (demikianlah) apa yang telah Kami ceritakan kepadamu (dan barang siapa membalas) melakukan pembalasan, yang dimaksud adalah orang-orang Mukmin (seimbang dengan penganiayaan yang pernah ia derita) sesuai dengan penganiayaan yang dialaminya dari orang-orang musyrik yang berbuat aniaya terhadapnya. Atau dengan kata lain, ia memerangi mereka sebagaimana mereka memeranginya di bulan Muharam (kemudian ia dianiaya lagi) dan diusir dari kampung halamannya oleh mereka (pasti Allah akan menolongnya. Sesungguhnya Allah benar-benar Maha Pemaaf) terhadap orang-orang yang beriman (lagi Maha Pengampun) terhadap mereka yang memerangi orang-orang musyrik, sekalipun dalam bulan Muharam.",[["۞ ذَٰلِكَ","Itu"],["وَمَنْ","dan sesiapa"],["عَاقَبَ","telah membalas dendam"],["بِمِثْلِ","dengan seumpamanya"],["مَا","(daripada) itu"],["عُوقِبَ","dia dibuat menderita"],["بِهِۦ","olehnya"],["ثُمَّ","kemudian"],["بُغِىَ","dia ditindas"],["عَلَيْهِ","[pada dia]"],["لَيَنصُرَنَّهُ","Allah pasti akan menolongnya"],["ٱللَّهُ ۗ","Allah pasti akan menolongnya"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَعَفُوٌّ","(adalah) pasti Maha Pengampun"],["غَفُورٌۭ","Selalu Memaafkan"]]],"2656":["(Yang demikian itu) pertolongan atau kemenangan itu (adalah karena sesungguhnya Allah kuasa memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam) Dia berkuasa untuk memasukkan masing-masing di antara keduanya kepada yang lainnya, yaitu dengan mengembalikan waktu pada salah satu di antaranya. Yang demikian itu merupakan pengaruh daripada kekuasaan Allah swt. yang dengan kekuasaan-Nya itu kaum Muslimin dapat kemenangan (dan bahwasanya Allah Maha Mendengar) terhadap doa-doa kaum Mukminin (lagi Maha Melihat) perihal orang-orang yang beriman, di mana Dia menjadikan iman dalam diri mereka, kemudian Dia memperkenankan doa mereka.",[["ذَٰلِكَ","Itu"],["بِأَنَّ","(adalah) kerana"],["ٱللَّهَ","Allah"],["يُولِجُ","menyebabkan masuk"],["ٱلَّيْلَ","malam"],["فِى","dalam (ke)"],["ٱلنَّهَارِ","hari itu"],["وَيُولِجُ","dan menyebabkan masuk"],["ٱلنَّهَارَ","hari itu"],["فِى","dalam (ke)"],["ٱلَّيْلِ","malam"],["وَأَنَّ","Dan sesungguhnya"],["ٱللَّهَ","Allah"],["سَمِيعٌۢ","(adalah) Yang Maha Mendengar"],["بَصِيرٌۭ","Maha Melihat"]]],"2657":["(Demikian itu) yakni kemenangan itu pun (adalah karena sesungguhnya Allah, Dialah Tuhan yang hak) yang semestinya (dan sesungguhnya apa saja yang mereka seru) dapat dibaca Yad'uuna dan Tad'uuna, maksudnya apa saja yang mereka sembah (selain dari Allah) yakni berhala-berhala (itulah yang batil) yakni yang akan lenyap (dan sesungguhnya Allah, Dialah Yang Maha Tinggi) atas segala sesuatu dengan kekuasaan-Nya (lagi Maha Besar) artinya segala sesuatu selain-Nya adalah kecil.",[["ذَٰلِكَ","Itu (ialah)"],["بِأَنَّ","kerana"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلْحَقُّ","(adalah) Kebenaran"],["وَأَنَّ","dan bahawa"],["مَا","apa"],["يَدْعُونَ","mereka menyeru"],["مِن","selain Dia"],["دُونِهِۦ","selain Dia"],["هُوَ","ia"],["ٱلْبَـٰطِلُ","(ialah) kebatilan"],["وَأَنَّ","Dan bahawa"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلْعَلِىُّ","(adalah) Yang Maha Tinggi"],["ٱلْكَبِيرُ","yang Maha Agung"]]],"2658":["(Apakah kamu tiada melihat) tidak mengetahui (bahwasanya Allah menurunkan air dari langit) yakni hujan (lalu jadilah bumi itu hijau?) disebabkan adanya tumbuh-tumbuhan sesudah itu, hal ini merupakan bukti bagi kekuasaan Allah. (Sesungguhnya Allah benar-benar Maha Lembut) terhadap hamba-hamba-Nya, karena itu Dia menumbuhkan tumbuh-tumbuhan dengan air hujan itu (lagi Maha Waspada) terhadap apa yang ada dalam hati mereka, di kala hujan datang terlambat.",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["أَنزَلَ","menghantar turun"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["فَتُصْبِحُ","kemudian menjadi"],["ٱلْأَرْضُ","bumi"],["مُخْضَرَّةً ۗ","hijau"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَطِيفٌ","(adalah) pasti Halus"],["خَبِيرٌۭ","Maha Mengetahui"]]],"2659":["(Kepunyaan-Nyalah segala yang ada di langit dan segala yang ada di bumi) sebagai milik-Nya. (Dan sesungguhnya Allah benar-benar Maha Kaya) tidak membutuhkan hamba-hamba-Nya (lagi Maha Terpuji) terhadap kekasih-kekasih-Nya.",[["لَّهُۥ","Untuk Dia"],["مَا","(adalah) apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۗ","bumi"],["وَإِنَّ","Dan sesungguhnya"],["ٱللَّهَ","Allah"],["لَهُوَ","pasti, Dia"],["ٱلْغَنِىُّ","(adalah) Bebas daripada keperluan"],["ٱلْحَمِيدُ","yang Terpuji"]]],"2660":["(Apakah kamu tiada melihat) tiada mengetahui (bahwasanya Allah menundukkan bagi kalian apa yang ada di bumi) berupa hewan-hewan ternak (dan bahtera) perahu, kapal (yang berlayar di laut) hingga dapat dinaiki dan dapat membawa muatan (dengan perintah-Nya) dengan seizin-Nya. (Dan Dia menahan benda-benda langit) (supaya tidak) supaya jangan (jatuh ke bumi melainkan dengan izin-Nya) oleh sebab itu mereka akan hancur binasa. (Sesungguhnya Allah benar-benar Maha Pengasih lagi Maha Penyayang kepada manusia) oleh karenanya Dia menundukkan kesemuanya itu, dan menahan langit supaya tidak jatuh menimpa mereka.",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["سَخَّرَ","(telah) tertakluk"],["لَكُم","kepada kamu"],["مَّا","apa"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["وَٱلْفُلْكَ","dan kapal-kapal itu"],["تَجْرِى","layar itu"],["فِى","melalui"],["ٱلْبَحْرِ","laut"],["بِأَمْرِهِۦ","dengan Perintah-Nya"],["وَيُمْسِكُ","Dan Dia menahan"],["ٱلسَّمَآءَ","langit"],["أَن","jangan-jangan"],["تَقَعَ","ia jatuh"],["عَلَى","pada"],["ٱلْأَرْضِ","bumi"],["إِلَّا","kecuali"],["بِإِذْنِهِۦٓ ۗ","dengan izinNya"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["بِٱلنَّاسِ","kepada manusia"],["لَرَءُوفٌۭ","(adalah) Penuh Kebaikan"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"2661":["(Dan Dialah Allah yang telah menghidupkan kalian) menumbuhkan kalian (kemudian mematikan kalian) bilamana ajal atau batas umur kalian telah habis (kemudian menghidupkan kalian lagi) di waktu hari berbangkit (sesungguhnya manusia itu) yakni orang yang musyrik (benar-benar sangat mengingkari) kepada nikmat-nikmat Allah, disebabkan mereka tidak mau mengesakan-Nya.",[["وَهُوَ","Dan Dia"],["ٱلَّذِىٓ","(ialah) Yang"],["أَحْيَاكُمْ","memberi kamu kehidupan"],["ثُمَّ","kemudian"],["يُمِيتُكُمْ","Dia akan menyebabkan kamu mati"],["ثُمَّ","kemudian"],["يُحْيِيكُمْ ۗ","Dia akan memberi kamu kehidupan (sekali lagi)"],["إِنَّ","Sesungguhnya"],["ٱلْإِنسَـٰنَ","lelaki"],["لَكَفُورٌۭ","(adalah) sesungguhnya ingkar"]]],"2662":["(Bagi tiap-tiap umat telah Kami tetapkan manasik tertentu) dapat dibaca Mansakan dan Minsakan artinya syariat (yang mereka lakukan) yakni mereka amalkan (maka janganlah sekali-kali mereka membantah kamu) makna yang dimaksud adalah, janganlah kamu membantah mereka (dalam urusan ini) masalah penyembelihan, karena mereka mengatakan, bahwa apa yang dimatikan oleh Allah yakni bangkai lebih berhak untuk kalian makan daripada apa yang kalian sembelih (dan serulah manusia kepada Rabbmu) agama-Nya. (Sesungguhnya kamu benar-benar berada pada petunjuk) agama (yang lurus).",[["لِّكُلِّ","Untuk setiap"],["أُمَّةٍۢ","bangsa"],["جَعَلْنَا","Kami telah membuat"],["مَنسَكًا","upacara"],["هُمْ","mereka"],["نَاسِكُوهُ ۖ","melaksanakannya"],["فَلَا","Maka janganlah mereka membantah kamu"],["يُنَـٰزِعُنَّكَ","Maka janganlah mereka membantah kamu"],["فِى","dalam"],["ٱلْأَمْرِ ۚ","perkara itu"],["وَٱدْعُ","tetapi jemput (mereka)"],["إِلَىٰ","kepada"],["رَبِّكَ ۖ","Tuhanmu"],["إِنَّكَ","Sesungguhnya kamu"],["لَعَلَىٰ","(ada) sudah pasti"],["هُدًۭى","bimbingan"],["مُّسْتَقِيمٍۢ","lurus"]]],"2663":["(Dan jika mereka membantah kamu) dalam masalah agama (maka katakanlah! \"Allah lebih mengetahui tentang apa yang kalian kerjakan\") maka Dia akan membalasnya kepada kalian. Ayat ini diturunkan sebelum ada perintah untuk berperang.",[["وَإِن","Dan jika"],["جَـٰدَلُوكَ","mereka membantah (dengan) kamu"],["فَقُلِ","kemudian berkata"],["ٱللَّهُ","Allah"],["أَعْلَمُ","(adalah) yang paling mengetahui"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"2664":["(Allah akan mengadili di antara kalian) hai orang-orang Mukmin dan orang-orang kafir (pada hari kiamat tentang apa yang kalian dahulu selalu berselisih padanya) yaitu satu golongan dengan golongan lainnya berbeda pendapat.",[["ٱللَّهُ","Allah"],["يَحْكُمُ","akan menilai"],["بَيْنَكُمْ","antara kamu"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["فِيمَا","berkenaan apa"],["كُنتُمْ","kamu pernah (untuk)"],["فِيهِ","di dalamnya"],["تَخْتَلِفُونَ","berbeza"]]],"2665":["(Apakah kamu tidak mengetahui) Istifham di sini bermakna Taqrir, maksudnya bukankah kamu telah mengetahui (bahwa sesungguhnya Allah mengetahui apa saja yang ada di langit dan di bumi; bahwasanya yang demikian itu) apa yang telah disebutkan tadi (terdapat dalam Kitab?) yang dimaksud adalah Lohmahfuz. (Sesungguhnya yang demikian itu) pengetahuan apa yang telah disebutkan tadi (amat mudah bagi Allah.)",[["أَلَمْ","Jangan"],["تَعْلَمْ","kamu tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["فِى","(berada) dalam"],["ٱلسَّمَآءِ","syurga itu"],["وَٱلْأَرْضِ ۗ","dan bumi"],["إِنَّ","Sesungguhnya"],["ذَٰلِكَ","bahawa"],["فِى","(berada) dalam"],["كِتَـٰبٍ ۚ","sebuah Rekod"],["إِنَّ","sesungguhnya"],["ذَٰلِكَ","bahawa"],["عَلَى","(adalah) untuk"],["ٱللَّهِ","Allah"],["يَسِيرٌۭ","mudah"]]],"2666":["(Dan mereka menyembah) yakni orang-orang musyrik (selain daripada Allah, apa yang Allah tidak menurunkan tentang itu) yang dimaksud adalah berhala-berhala (suatu keterangan pun) hujah mengenainya (dan apa yang mereka sendiri tidak mempunyai pengetahuan terhadapnya) bahwasanya hal-hal itu adalah tuhan-tuhan. (Dan bagi orang-orang yang zalim sekali-kali tidak ada) zalim karena melakukan kemusyrikan (seorang penolong pun) yang dapat mencegah azab Allah dari diri mereka.",[["وَيَعْبُدُونَ","Dan mereka menyembah"],["مِن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["مَا","apa"],["لَمْ","tidak"],["يُنَزِّلْ","Dia (telah) menurunkan"],["بِهِۦ","baginya"],["سُلْطَـٰنًۭا","mana-mana pihak berkuasa"],["وَمَا","dan apa"],["لَيْسَ","tidak"],["لَهُم","mereka ada"],["بِهِۦ","daripadanya"],["عِلْمٌۭ ۗ","sebarang pengetahuan"],["وَمَا","Dan tidak"],["لِلظَّـٰلِمِينَ","(untuk) bagi orang-orang yang zalim"],["مِن","sebarang"],["نَّصِيرٍۢ","penolong"]]],"2667":["(Dan apabila dibacakan di hadapan mereka ayat-ayat Kami) dari Alquran (yang terang) jelas keadaannya (niscaya kamu melihat tanda-tanda keingkaran pada muka orang-orang yang kafir itu) keingkaran mereka terhadap ayat-ayat Kami, yaitu sebagai pengaruh dari kebencian mereka terhadapnya, kelihatan muka mereka sangat masam. (Hampir-hampir mereka menyerang orang-orang yang membacakan ayat-ayat Kami di hadapan mereka) akan menimpakan kekerasan terhadap mereka. (Katakanlah! \"Apakah akan aku kabarkan kepada kalian yang lebih buruk daripada itu?) perkara yang lebih kalian tidak sukai daripada Alquran yang dibacakan kepada kalian ini (Yaitu neraka\". Allah telah mengancamkannya kepada orang-orang yang kafir) bahwasanya tempat kembali mereka adalah neraka. (Dan seburuk-buruk tempat kembali) itu adalah neraka.",[["وَإِذَا","Dan apabila"],["تُتْلَىٰ","dibacakan"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتُنَا","Ayat Kami"],["بَيِّنَـٰتٍۢ","yang nyata"],["تَعْرِفُ","kamu akan mengenali"],["فِى","pada"],["وُجُوهِ","(the) muka"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["ٱلْمُنكَرَ ۖ","penafian itu"],["يَكَادُونَ","Mereka hampir"],["يَسْطُونَ","menyerang"],["بِٱلَّذِينَ","orang yang"],["يَتْلُونَ","mengaji"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتِنَا ۗ","Ayat Kami"],["قُلْ","Katakanlah"],["أَفَأُنَبِّئُكُم","Kemudian aku akan memberitahu kamu"],["بِشَرٍّۢ","lebih teruk"],["مِّن","daripada"],["ذَٰلِكُمُ ۗ","bahawa"],["ٱلنَّارُ","Api"],["وَعَدَهَا","Allah (telah) menjanjikannya"],["ٱللَّهُ","Allah (telah) menjanjikannya"],["ٱلَّذِينَ","(bagi) mereka yang"],["كَفَرُوا۟ ۖ","kufur"],["وَبِئْسَ","dan celaka"],["ٱلْمَصِيرُ","(adalah) destinasi"]]],"2668":["(Hai manusia,) yakni penduduk Mekah (telah dibuatkan perumpamaan, maka dengarkanlah oleh kalian perumpamaan itu) yaitu, (Sesungguhnya segala yang kalian seru) kalian sembah (selain Allah) yaitu berhala-berhala (sekali-kali tidak dapat menciptakan seekor lalat pun) lafal Dzubaaban adalah isim jenis, yang artinya jamak, sedangkan bentuk tunggalnya adalah Dzubaabatun; lafal ini dapat dipakai untuk mudzakkar dan muanats (walaupun mereka bersatu untuk menciptakannya) untuk membuatnya. (Dan jika lalat itu merampas sesuatu dari mereka) apa yang ada pada mereka berupa wewangian dan minyak Za'faron yang dilumurkan kepada berhala-berhala mereka itu (tiadalah mereka dapat menyelamatkan sesuatu itu) dapat merampas kembali sesuatu itu (dari lalat itu) karena mereka tidak mampu, mengapa mereka menyembah selain Allah? Yaitu apa-apa yang mereka anggap sebagai sekutu-sekutu Allah. Ini adalah hal yang aneh sekali, diungkapkan oleh peribahasa dengan ungkapan seperti berikut ini, (\"Alangkah lemahnya yang menyeru) yakni yang menyembah (dan alangkah lemahnya pula yang diseru) yakni yang disembah.",[["يَـٰٓأَيُّهَا","Wahai umat manusia"],["ٱلنَّاسُ","Wahai umat manusia"],["ضُرِبَ","Ditetapkan"],["مَثَلٌۭ","satu contoh"],["فَٱسْتَمِعُوا۟","jadi dengar"],["لَهُۥٓ ۚ","kepadanya"],["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","mereka yang"],["تَدْعُونَ","kamu menyeru"],["مِن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["لَن","tidak akan pernah"],["يَخْلُقُوا۟","cipta"],["ذُبَابًۭا","seekor lalat"],["وَلَوِ","walaupun"],["ٱجْتَمَعُوا۟","mereka berkumpul bersama"],["لَهُۥ ۖ","baginya"],["وَإِن","Dan jika"],["يَسْلُبْهُمُ","dirampas dari mereka"],["ٱلذُّبَابُ","lalat itu"],["شَيْـًۭٔا","sesuatu perkara"],["لَّا","tidak"],["يَسْتَنقِذُوهُ","mereka (boleh) mengambilnya kembali"],["مِنْهُ ۚ","daripadanya"],["ضَعُفَ","Begitu lemah"],["ٱلطَّالِبُ","(adalah) yang mencari"],["وَٱلْمَطْلُوبُ","dan orang yang dicari"]]],"2669":["(Mereka tidak menganggap Allah) tidak mengagungkan-Nya (dengan sebenar-benarnya) dengan pengagungan yang sebenarnya, disebabkan mereka menyekutukan-Nya dengan apa-apa yang tidak dapat mencegah seekor lalat pun dan tidak dapat pula merebut apa yang telah diambilnya. (Sesungguhnya Allah benar-benar Maha Kuat lagi Maha Perkasa\") yakni Maha Menang.",[["مَا","Tidak"],["قَدَرُوا۟","mereka (telah) menganggarkan"],["ٱللَّهَ","Allah"],["حَقَّ","(dengan) kena dibayar"],["قَدْرِهِۦٓ ۗ","Anggaran [nya]."],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَقَوِىٌّ","Sesungguhnya Maha Kuat"],["عَزِيزٌ","Maha Perkasa"]]],"2670":["(Allah memilih utusan-utusan-Nya dari malaikat dan dari manusia) sebagai rasul-rasul-Nya. Ayat ini diturunkan ketika orang-orang musyrik mengatakan, sebagaimana yang telah disitir oleh firman-Nya, \"Mengapa Alquran itu diturunkan kepadanya di antara kita?\" (Q.S. Shad, 8) (sesungguhnya Allah Maha Mendengar) ucapan-ucapan mereka (lagi Maha Melihat) utusan yang telah diangkat-Nya, seperti malaikat Jibril, malaikat Mikail, Nabi Ibrahim, Nabi Muhammad dan Rasul-rasul lainnya, semoga selawat dan salam Allah curahkan kepada mereka semuanya.",[["ٱللَّهُ","Allah"],["يَصْطَفِى","memilih"],["مِنَ","daripada"],["ٱلْمَلَـٰٓئِكَةِ","para Malaikat"],["رُسُلًۭا","Utusan"],["وَمِنَ","dan daripada"],["ٱلنَّاسِ ۚ","umat manusia"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["سَمِيعٌۢ","(adalah) Yang Maha Mendengar"],["بَصِيرٌۭ","Maha Melihat"]]],"2671":["(Allah mengetahui apa yang ada di hadapan mereka dan apa yang ada di belakang mereka) apa yang akan mereka lakukan dan apa yang telah mereka lakukan, dan apa yang sekarang sedang mereka lakukan. (Dan hanya kepada Allah dikembalikan semua urusan).",[["يَعْلَمُ","Dia tahu"],["مَا","apa"],["بَيْنَ","(ada) di hadapan mereka"],["أَيْدِيهِمْ","(ada) di hadapan mereka"],["وَمَا","dan apa"],["خَلْفَهُمْ ۗ","(adalah) selepas mereka"],["وَإِلَى","Dan kepada"],["ٱللَّهِ","Allah"],["تُرْجَعُ","kembali"],["ٱلْأُمُورُ","semua perkara"]]],"2672":["(Hai orang-orang yang beriman! Rukuk dan sujudlah kalian) salatlah kalian (dan sembahlah Rabb kalian) tauhidkanlah Dia (dan perbuatlah kebaikan) seperti menghubungkan silaturahim dan melakukan akhlak-akhlak yang mulia (supaya kalian mendapat keberuntungan) kalian beruntung karena dapat hidup abadi di surga.",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["ٱرْكَعُوا۟","Tunduk"],["وَٱسْجُدُوا۟","dan sujud"],["وَٱعْبُدُوا۟","dan ibadah"],["رَبَّكُمْ","Tuhanmu"],["وَٱفْعَلُوا۟","dan melakukan"],["ٱلْخَيْرَ","[yang] baik"],["لَعَلَّكُمْ","supaya kamu"],["تُفْلِحُونَ ۩","berjaya"]]],"2673":["(Dan berjihadlah kalian pada jalan Allah) demi menegakkan agama-Nya (dengan jihad yang sebenar-benarnya) dengan mengerahkan segala kemampuan kalian di dalamnya. Lafal Haqqa dinashabkan disebabkan menjadi Mashdar. (Dia telah memilih kalian) untuk membela agama-Nya (dan Dia sekali-kali tidak menjadikan untuk kalian dalam agama suatu kesempitan) artinya hal-hal yang membuat kalian sulit untuk melakukannya, untuk itu Dia memberikan kemudahan kepada kalian dalam keadaan darurat, antara lain boleh mengkasar salat, bertayamum, memakan bangkai, dan berbuka puasa bagi orang yang sedang sakit dan bagi yang sedang melakukan perjalanan (sebagaimana agama orang tua kalian) kedudukan lafal Millata dinashabkan dengan cara mencabut huruf Jarrnya, yaitu huruf Kaf (Ibrahim) lafal ini menjadi athaf Bayan. (Dia) yakni Allah (telah menamai kalian orang-orang Muslim dari dahulu) sebelum diturunkannya Alquran (dan begitu pula dalam Kitab ini) yakni Alquran (supaya Rasul itu menjadi saksi atas diri kalian) kelak di hari kiamat, bahwasanya dia telah menyampaikan kepada kalian (dan kalian) semuanya (menjadi saksi atas segenap manusia) bahwasanya Rasul-rasul mereka telah menyampaikan risalah-Nya kepada mereka (maka dirikanlah salat) maksudnya laksanakanlah salat secara terus-menerus (tunaikanlah zakat dan berpeganglah kalian kepada Allah) percayalah kalian kepada-Nya (Dia adalah pelindung kalian) yang menolong kalian dan yang mengurus perkara-perkara kalian (maka sebaik-baik pelindung) adalah Dia (dan sebaik-baik penolong) kalian adalah Dia.",[["وَجَـٰهِدُوا۟","Dan berusahalah"],["فِى","bagi"],["ٱللَّهِ","Allah"],["حَقَّ","(dengan) berusaha kerana (kepada)Nya"],["جِهَادِهِۦ ۚ","(dengan) berusaha kerana (kepada)Nya"],["هُوَ","Dia"],["ٱجْتَبَىٰكُمْ","(telah) memilih kamu"],["وَمَا","dan bukan"],["جَعَلَ","diletakkan"],["عَلَيْكُمْ","ke atas kamu"],["فِى","dalam"],["ٱلدِّينِ","agama itu"],["مِنْ","sebarang"],["حَرَجٍۢ ۚ","kesukaran"],["مِّلَّةَ","(Agama)."],["أَبِيكُمْ","(dari) bapa kamu"],["إِبْرَٰهِيمَ ۚ","Ibrahim"],["هُوَ","Dia"],["سَمَّىٰكُمُ","menamakan kamu"],["ٱلْمُسْلِمِينَ","orang Islam"],["مِن","sebelum"],["قَبْلُ","sebelum"],["وَفِى","dan dalam"],["هَـٰذَا","ini"],["لِيَكُونَ","itu mungkin"],["ٱلرَّسُولُ","Rasul"],["شَهِيدًا","seorang saksi"],["عَلَيْكُمْ","atas kamu"],["وَتَكُونُوا۟","dan kamu mungkin"],["شُهَدَآءَ","saksi"],["عَلَى","pada"],["ٱلنَّاسِ ۚ","umat manusia"],["فَأَقِيمُوا۟","Jadi tegakkan"],["ٱلصَّلَوٰةَ","solat"],["وَءَاتُوا۟","dan memberi"],["ٱلزَّكَوٰةَ","zakat"],["وَٱعْتَصِمُوا۟","dan berpegang teguh"],["بِٱللَّهِ","kepada Allah"],["هُوَ","Dia"],["مَوْلَىٰكُمْ ۖ","(ialah) Pelindungmu"],["فَنِعْمَ","jadi Cemerlang"],["ٱلْمَوْلَىٰ","[the] Pelindung"],["وَنِعْمَ","dan Cemerlang"],["ٱلنَّصِيرُ","[the] Penolong"]]]});